// Package conv contains functions for converting values between types.
package conv

import (
	"fmt"
	"math"
	"reflect"
	"strconv"
	"strings"
	"time"
)

// ToString converts any value to a string.
func ToString(in any) string {
	if in == nil {
		return "nil"
	}
	switch s := in.(type) {
	case string:
		return s
	case fmt.Stringer:
		return s.String()
	case []byte:
		return string(s)
	case error:
		return s.Error()
	}

	v, ok := printableValue(reflect.ValueOf(in))
	if ok {
		in = v
	}
	return fmt.Sprint(in)
}

// printableValue mirrors the logic in text/template - dereference pointers
// where necessary so that the value prints well.
func printableValue(v reflect.Value) (any, bool) {
	if v.Kind() == reflect.Pointer {
		v, _ = indirect(v)
	}
	if !v.IsValid() {
		return "<no value>", true
	}

	if !v.Type().Implements(errorType) && !v.Type().Implements(fmtStringerType) {
		if v.CanAddr() && (reflect.PointerTo(v.Type()).Implements(errorType) || reflect.PointerTo(v.Type()).Implements(fmtStringerType)) {
			v = v.Addr()
		} else {
			switch v.Kind() {
			case reflect.Chan, reflect.Func:
				return nil, false
			}
		}
	}
	return v.Interface(), true
}

var (
	errorType       = reflect.TypeOf((*error)(nil)).Elem()
	fmtStringerType = reflect.TypeOf((*fmt.Stringer)(nil)).Elem()
)

func indirect(v reflect.Value) (rv reflect.Value, isNil bool) {
	for ; v.Kind() == reflect.Pointer || v.Kind() == reflect.Interface; v = v.Elem() {
		if v.IsNil() {
			return v, true
		}
	}
	return v, false
}

// ToStrings converts a list of values to strings.
func ToStrings(in ...any) []string {
	out := make([]string, len(in))
	for i, v := range in {
		out[i] = ToString(v)
	}
	return out
}

// ToBool converts a value to a boolean - true values are 1, "t", "true",
// "yes" (case-insensitive), or numeric strings equal to 1.
func ToBool(in any) bool {
	if b, ok := in.(bool); ok {
		return b
	}
	if s, ok := in.(string); ok {
		switch strings.ToLower(s) {
		case "t", "true", "yes":
			return true
		}
		f, err := strToFloat64(s)
		if err != nil {
			return false
		}
		return f == 1
	}
	v := reflect.Indirect(reflect.ValueOf(in))
	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return v.Int() == 1
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return v.Uint() == 1
	case reflect.Float32, reflect.Float64:
		return v.Float() == 1
	case reflect.Bool:
		return v.Bool()
	case reflect.String:
		return ToBool(v.String())
	}
	return false
}

// ToBools converts multiple values to booleans.
func ToBools(in ...any) []bool {
	out := make([]bool, len(in))
	for i, v := range in {
		out[i] = ToBool(v)
	}
	return out
}

func stripCommas(s string) string {
	if strings.Contains(s, ",") {
		return strings.ReplaceAll(s, ",", "")
	}
	return s
}

func strToInt64(s string) (int64, error) {
	s = stripCommas(s)
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return i, nil
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("could not convert %q to int64: %w", s, err)
	}
	return int64(f), nil
}

func strToFloat64(s string) (float64, error) {
	s = stripCommas(s)
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		return float64(i), nil
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("could not convert %q to float64: %w", s, err)
	}
	return f, nil
}

// ToInt64 converts the input to an int64.
func ToInt64(in any) (int64, error) {
	if s, ok := in.(string); ok {
		return strToInt64(s)
	}
	if d, ok := in.(time.Duration); ok {
		return int64(d), nil
	}
	v := reflect.Indirect(reflect.ValueOf(in))
	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return v.Int(), nil
	case reflect.Uint8, reflect.Uint16, reflect.Uint32:
		return int64(v.Uint()), nil
	case reflect.Uint, reflect.Uint64, reflect.Uintptr:
		u := v.Uint()
		if u > math.MaxInt64 {
			return 0, fmt.Errorf("could not convert %d to int64, would overflow", u)
		}
		return int64(u), nil
	case reflect.Float32, reflect.Float64:
		return int64(v.Float()), nil
	case reflect.Bool:
		if v.Bool() {
			return 1, nil
		}
		return 0, nil
	case reflect.String:
		return strToInt64(v.String())
	}
	return 0, fmt.Errorf("could not convert %v to int64", in)
}

// ToInt converts the input to an int.
func ToInt(in any) (int, error) {
	i, err := ToInt64(in)
	if err != nil {
		return 0, err
	}
	if i > math.MaxInt || i < math.MinInt {
		return -1, nil
	}
	return int(i), nil
}

// ToInt64s converts multiple values.
func ToInt64s(in ...any) ([]int64, error) {
	out := make([]int64, len(in))
	for i, v := range in {
		n, err := ToInt64(v)
		if err != nil {
			return nil, err
		}
		out[i] = n
	}
	return out, nil
}

// ToInts converts multiple values.
func ToInts(in ...any) ([]int, error) {
	out := make([]int, len(in))
	for i, v := range in {
		n, err := ToInt(v)
		if err != nil {
			return nil, err
		}
		out[i] = n
	}
	return out, nil
}

// ToFloat64 converts the input to a float64.
func ToFloat64(in any) (float64, error) {
	if s, ok := in.(string); ok {
		return strToFloat64(s)
	}
	v := reflect.Indirect(reflect.ValueOf(in))
	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return float64(v.Int()), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return float64(v.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return v.Float(), nil
	case reflect.Bool:
		if v.Bool() {
			return 1, nil
		}
		return 0, nil
	case reflect.String:
		return strToFloat64(v.String())
	}
	return 0, fmt.Errorf("could not convert %v to float64", in)
}

// ToFloat64s converts multiple values.
func ToFloat64s(in ...any) ([]float64, error) {
	out := make([]float64, len(in))
	for i, v := range in {
		f, err := ToFloat64(v)
		if err != nil {
			return nil, err
		}
		out[i] = f
	}
	return out, nil
}

// MustToInt converts or returns 0.
func MustToInt(in any) int {
	i, _ := ToInt(in)
	return i
}

// MustToInt64 converts or returns 0.
func MustToInt64(in any) int64 {
	i, _ := ToInt64(in)
	return i
}

// MustToFloat64 converts or returns 0.
func MustToFloat64(in any) float64 {
	f, _ := ToFloat64(in)
	return f
}
EOF
echo ok"}

