{"command":"mkdir -p /workspace/funcs && cat > /workspace/funcs/conv.go <<'EOF'
package funcs

import (
	"context"
	"fmt"
	"net/url"
	"reflect"
	"strconv"
	"strings"

	"github.com/hairyhenderson/gomplate/v4/conv"
)

// ConvFuncs - conversion functions
type ConvFuncs struct {
	ctx context.Context
}

// CreateConvFuncs -
func CreateConvFuncs(ctx context.Context) map[string]any {
	ns := &ConvFuncs{ctx}
	f := map[string]any{}
	f["conv"] = func() any { return ns }
	f["urlParse"] = ns.URL
	f["join"] = ns.Join
	f["default"] = ns.Default
	return f
}

// Join -
func (ConvFuncs) Join(in any, sep string) (string, error) {
	s, err := interfaceSlice(in)
	if err != nil {
		return "", fmt.Errorf("input to Join must be an array: %w", err)
	}
	parts := make([]string, len(s))
	for i, v := range s {
		parts[i] = conv.ToString(v)
	}
	return strings.Join(parts, sep), nil
}

// URL -
func (ConvFuncs) URL(s any) (*url.URL, error) {
	return url.Parse(conv.ToString(s))
}

// ParseInt -
func (ConvFuncs) ParseInt(s any, base, bitSize int) (int64, error) {
	return strconv.ParseInt(conv.ToString(s), base, bitSize)
}

// ParseFloat -
func (ConvFuncs) ParseFloat(s any, bitSize int) (float64, error) {
	return strconv.ParseFloat(conv.ToString(s), bitSize)
}

// ParseUint -
func (ConvFuncs) ParseUint(s any, base, bitSize int) (uint64, error) {
	return strconv.ParseUint(conv.ToString(s), base, bitSize)
}

// Atoi -
func (ConvFuncs) Atoi(s any) (int, error) {
	return strconv.Atoi(conv.ToString(s))
}

// ToBool -
func (ConvFuncs) ToBool(in any) bool { return conv.ToBool(in) }

// ToBools -
func (ConvFuncs) ToBools(in ...any) []bool { return conv.ToBools(in...) }

// ToInt64 -
func (ConvFuncs) ToInt64(in any) (int64, error) { return conv.ToInt64(in) }

// ToInt -
func (ConvFuncs) ToInt(in any) (int, error) { return conv.ToInt(in) }

// ToInt64s -
func (ConvFuncs) ToInt64s(in ...any) ([]int64, error) { return conv.ToInt64s(in...) }

// ToInts -
func (ConvFuncs) ToInts(in ...any) ([]int, error) { return conv.ToInts(in...) }

// ToFloat64 -
func (ConvFuncs) ToFloat64(in any) (float64, error) { return conv.ToFloat64(in) }

// ToFloat64s -
func (ConvFuncs) ToFloat64s(in ...any) ([]float64, error) { return conv.ToFloat64s(in...) }

// ToString -
func (ConvFuncs) ToString(in any) string { return conv.ToString(in) }

// ToStrings -
func (ConvFuncs) ToStrings(in ...any) []string { return conv.ToStrings(in...) }

// Default -
func (ConvFuncs) Default(def, in any) any {
	if truth(in) {
		return in
	}
	return def
}

// truth reports whether the value is 'true' in the text/template sense.
func truth(in any) bool {
	v := reflect.ValueOf(in)
	if !v.IsValid() {
		return false
	}
	switch v.Kind() {
	case reflect.Array, reflect.Map, reflect.Slice, reflect.String:
		return v.Len() > 0
	case reflect.Bool:
		return v.Bool()
	case reflect.Complex64, reflect.Complex128:
		return v.Complex() != 0
	case reflect.Chan, reflect.Func, reflect.Pointer, reflect.Interface:
		return !v.IsNil()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return v.Int() != 0
	case reflect.Float32, reflect.Float64:
		return v.Float() != 0
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return v.Uint() != 0
	case reflect.Struct:
		return true
	}
	return false
}

// interfaceSlice converts an array or slice of any type into []any
func interfaceSlice(slice any) ([]any, error) {
	if s, ok := slice.([]any); ok {
		return s, nil
	}
