// ToInt -
func (ConvFuncs) ToInt(in any) (int, error) { return conv.ToInt(in) }

// ToInt64s -
func (ConvFuncs) ToInt64s(in ...any) ([]int64, error) { return conv.ToInt64s(in...) }

// ToInts -
func (ConvFuncs) ToInts(in ...any) ([]int, error) { return conv.ToInts(in...) }

