func WordWrap(str string, width int, lbseq string) string {
	if str == "" {
		return ""
	}
	if lbseq == "" {
		lbseq = "\n"
	}
	if width < 1 {
		width = 1
	}
	inLen := len(str)
	offset := 0
	var out bytes.Buffer
	for inLen-offset > width {
		if str[offset] == ' ' {
			offset++
