{"command":"mkdir -p /workspace/internal/config && cat > /workspace/internal/config/config.go <<'EOF'
// Package config contains the gomplate configuration types.
package config

import (
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// Config - gomplate configuration
type Config struct {
	Stdin  io.Reader `yaml:"-"`
	Stdout io.Writer `yaml:"-"`
	Stderr io.Writer `yaml:"-"`

	DataSources map[string]DataSource   `yaml:"datasources,omitempty"`
	Context     map[string]DataSource   `yaml:"context,omitempty"`
	Templates   map[string]DataSource   `yaml:"templates,omitempty"`
	Plugins     map[string]PluginConfig `yaml:"plugins,omitempty"`

	Input                 string   `yaml:"in,omitempty"`
	InputDir              string   `yaml:"inputDir,omitempty"`
	InputFiles            []string `yaml:"inputFiles,omitempty,flow"`
	ExcludeGlob           []string `yaml:"excludes,omitempty"`
	ExcludeProcessingGlob []string `yaml:"excludeProcessing,omitempty"`

	OutputDir   string   `yaml:"outputDir,omitempty"`
	OutputMap   string   `yaml:"outputMap,omitempty"`
	OutputFiles []string `yaml:"outputFiles,omitempty,flow"`
	OutMode     string   `yaml:"chmod,omitempty"`

	LDelim     string `yaml:"leftDelim,omitempty"`
	RDelim     string `yaml:"rightDelim,omitempty"`
	MissingKey string `yaml:"missingKey,omitempty"`

	PostExec      []string      `yaml:"postExec,omitempty,flow"`
	PluginTimeout time.Duration `yaml:"pluginTimeout,omitempty"`
	ExecPipe      bool          `yaml:"execPipe,omitempty"`
	Experimental  bool          `yaml:"experimental,omitempty"`

	// internal - the include globs from the command line
	IncludeGlob []string `yaml:"-"`
	// ExtraHeaders - from -H flags, keyed by alias
	ExtraHeaders map[string]http.Header `yaml:"-"`
}

// DataSource - datasource configuration
type DataSource struct {
	URL    *url.URL
	Header http.Header
}

type rawDS struct {
	Header http.Header `yaml:"header"`
	URL    string      `yaml:"url"`
}

// UnmarshalYAML -
func (d *DataSource) UnmarshalYAML(value *yaml.Node) error {
	type raw struct {
		URL    string      `yaml:"url"`
		Header http.Header `yaml:"header,omitempty"`
	}
	r := raw{}
	if err := value.Decode(&r); err != nil {
		return err
	}
	u, err := ParseSourceURL(r.URL)
	if err != nil {
		return fmt.Errorf("could not parse datasource URL %q: %w", r.URL, err)
	}
	*d = DataSource{URL: u, Header: r.Header}
	return nil
}

// MarshalYAML -
func (d DataSource) MarshalYAML() (any, error) {
	h := d.Header
	if h == nil {
		h = http.Header{}
	}
	u := ""
	if d.URL != nil {
		u = d.URL.String()
	}
	return rawDS{Header: h, URL: u}, nil
}

// PluginConfig - plugin configuration
type PluginConfig struct {
	Cmd     string        `yaml:"cmd,omitempty"`
	Args    []string      `yaml:"args,omitempty"`
	Timeout time.Duration `yaml:"timeout,omitempty"`
	Pipe    bool          `yaml:"pipe,omitempty"`
}

// UnmarshalYAML - plugins may be configured with just a string
func (p *PluginConfig) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind == yaml.ScalarNode {
		s := ""
		if err := value.Decode(&s); err != nil {
			return err
		}
		*p = PluginConfig{Cmd: s}
		return nil
	}
	type raw struct {
		Cmd     string        `yaml:"cmd,omitempty"`
		Args    []string      `yaml:"args,omitempty"`
		Timeout time.Duration `yaml:"timeout,omitempty"`
		Pipe    bool          `yaml:"pipe,omitempty"`
	}
	r := raw{}
	if err := value.Decode(&r); err != nil {
		return err
	}
	*p = PluginConfig(r)
	return nil
}

// Parse a config file
func Parse(in io.Reader) (*Config, error) {
	out := &Config{}
	dec := yaml.NewDecoder(in)
	err := dec.Decode(out)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("YAML decoding failed, syntax may be invalid: %w", err)
	}
	return out, nil
}

// MergeFrom merges the other config into this one - values in o take
// precedence
func (c *Config) MergeFrom(o *Config) *Config {
	switch {
	case o.Input != "":
		c.Input = o.Input
		c.InputDir = ""
		c.InputFiles = nil
		c.OutputDir = ""
	case o.InputDir != "":
		c.Input = ""
		c.InputDir = o.InputDir
		c.InputFiles = nil
	case len(o.InputFiles) > 0:
		c.Input = ""
		c.InputFiles = o.InputFiles
		c.InputDir = ""
		c.OutputDir = ""
	}

	if o.OutputMap != "" {
		c.OutputDir = ""
		c.OutputFiles = nil
		c.OutputMap = o.OutputMap
	}
	if o.OutputDir != "" {
		c.OutputDir = o.OutputDir
		c.OutputFiles = nil
		c.OutputMap = ""
	}
	if len(o.OutputFiles) > 0 {
		c.OutputDir = ""
		c.OutputFiles = o.OutputFiles
		c.OutputMap = ""
	}
	if o.ExecPipe {
		c.ExecPipe = o.ExecPipe
		c.OutputMap = ""
		c.OutputDir = ""
		c.OutputFiles = []string{"-"}
	}
	if o.OutMode != "" {
		c.OutMode = o.OutMode
	}
	if o.LDelim != "" {
		c.LDelim = o.LDelim
	}
	if o.RDelim != "" {
		c.RDelim = o.RDelim
	}
	if o.MissingKey != "" {
		c.MissingKey = o.MissingKey
	}
	if o.Experimental {
		c.Experimental = o.Experimental
	}
	if len(o.PostExec) > 0 {
		c.PostExec = o.PostExec
	}
	if o.PluginTimeout != 0 {
		c.PluginTimeout = o.PluginTimeout
	}
	if len(o.ExcludeGlob) > 0 {
		c.ExcludeGlob = o.ExcludeGlob
	}
	if len(o.ExcludeProcessingGlob) > 0 {
		c.ExcludeProcessingGlob = o.ExcludeProcessingGlob
	}
	c.DataSources = mergeDataSourceMaps(c.DataSources, o.DataSources)
	c.Context = mergeDataSourceMaps(c.Context, o.Context)
	c.Templates = mergeDataSourceMaps(c.Templates, o.Templates)
	if len(o.Plugins) > 0 {
		if c.Plugins == nil {
			c.Plugins = map[string]PluginConfig{}
		}
		for k, v := range o.Plugins {
			c.Plugins[k] = v
		}
	}
	if len(o.ExtraHeaders) > 0 {
		if c.ExtraHeaders == nil {
			c.ExtraHeaders = map[string]http.Header{}
		}
		for k, v := range o.ExtraHeaders {
			c.ExtraHeaders[k] = v
		}
	}
	return c
}

func mergeDataSourceMaps(left, right map[string]DataSource) map[string]DataSource {
	if len(right) == 0 {
		return left
	}
	if left == nil {
		left = map[string]DataSource{}
	}
	for k, v := range right {
		left[k] = v
	}
	return left
