// Package cmd contains the gomplate command-line interface
package cmd

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"os/signal"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/hairyhenderson/gomplate/v4"
	"github.com/hairyhenderson/gomplate/v4/internal/config"
	"github.com/hairyhenderson/gomplate/v4/internal/logging"
	"github.com/hairyhenderson/gomplate/v4/version"
)

// Main runs the gomplate command
func Main(ctx context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	cmd := newGomplateCmd(stdin, stdout, stderr)
	cmd.SetArgs(args)
	err := cmd.ExecuteContext(ctx)
	if err != nil {
		if !loggerInitialized {
			fmt.Fprintf(stderr, "ERROR  err=%s\n", logging.FormatValue(slog.StringValue(err.Error())))
		} else {
			slog.ErrorContext(ctx, "", "err", err)
		}
		return 1
	}
	return 0
}

var loggerInitialized bool

func newGomplateCmd(stdin io.Reader, stdout, stderr io.Writer) *cobra.Command {
	rootCmd := &cobra.Command{
		Use:     "gomplate",
		Short:   "Process text files with Go templates",
		Version: version.Version,
		Args: func(cmd *cobra.Command, args []string) error {
			n := len(args)
			if d := cmd.ArgsLenAtDash(); d >= 0 {
				n = d
			}
			if n > 0 {
				return fmt.Errorf("unknown command %q for %q", args[0], cmd.CommandPath())
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			return runE(cmd, args, stdin, stdout, stderr)
		},
	}
	rootCmd.SetOut(stdout)
	rootCmd.SetErr(stderr)
	initFlags(rootCmd)
	return rootCmd
}

func initFlags(command *cobra.Command) {
	command.Flags().SortFlags = false

	command.Flags().StringSliceP("datasource", "d", nil, "`datasource` in alias=URL form. Specify multiple times to add multiple sources.")
	command.Flags().StringSliceP("datasource-header", "H", nil, "HTTP `header` field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")

	command.Flags().StringSliceP("context", "c", nil, "pre-load a `datasource` into the context, in alias=URL form. Use the special alias `.` to set the root context.")

	command.Flags().StringSlice("plugin", nil, "plug in an external command as a function in name=path form. Can be specified multiple times")

	command.Flags().StringSliceP("file", "f", []string{"-"}, "Template `file` to process. Omit to use standard input, or use --in or --input-dir")
	command.Flags().StringP("in", "i", "", "Template `string` to process (alternative to --file and --input-dir)")
	command.Flags().String("input-dir", "", "`directory` which is examined recursively for templates (alternative to --file and --in)")

	command.Flags().StringSlice("exclude", []string{}, "glob of files to not parse")
	command.Flags().StringSlice("exclude-processing", []string{}, "glob of files to be copied without parsing")
	command.Flags().StringSlice("include", []string{}, "glob of files to parse")

	command.Flags().StringSliceP("out", "o", []string{"-"}, "output `file` name. Omit to use standard output.")
	command.Flags().StringSliceP("template", "t", []string{}, "Additional template file(s)")
	command.Flags().String("output-dir", ".", "`directory` to store the processed templates. Only used for --input-dir")
	command.Flags().String("output-map", "", "Template `string` to map the input file to an output path")
	command.Flags().String("chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")

	command.Flags().Bool("exec-pipe", false, "pipe the output to the post-run exec command")

	ldDefault := os.Getenv("GOMPLATE_LEFT_DELIM")
	if ldDefault == "" {
		ldDefault = "{{"
	}
	rdDefault := os.Getenv("GOMPLATE_RIGHT_DELIM")
	if rdDefault == "" {
		rdDefault = "}}"
	}
	command.Flags().String("left-delim", ldDefault, "override the default left-`delimiter` [$GOMPLATE_LEFT_DELIM]")
	command.Flags().String("right-delim", rdDefault, "override the default right-`delimiter` [$GOMPLATE_RIGHT_DELIM]")

	command.Flags().String("missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")

	command.Flags().Bool("experimental", false, "enable experimental features [$GOMPLATE_EXPERIMENTAL]")

	command.Flags().BoolP("verbose", "V", false, "output extra information about what gomplate is doing")

	command.Flags().String("config", ".gomplate.yaml", "config file (overridden by commandline flags)")
}

func runE(cmd *cobra.Command, args []string, stdin io.Reader, stdout, stderr io.Writer) error {
	ctx := cmd.Context()

	verbose, _ := cmd.Flags().GetBool("verbose")
	level := slog.LevelWarn
	if verbose {
		level = slog.LevelDebug
	}
	logging.Init(level, stderr)
	loggerInitialized = true

	cfg, err := loadConfig(ctx, cmd, args)
	if err != nil {
		return err
	}
	cfg.Stdin = stdin
	cfg.Stdout = stdout
	cfg.Stderr = stderr

	slog.DebugContext(ctx, fmt.Sprintf("starting %s", cmd.Name()))
	slog.DebugContext(ctx, fmt.Sprintf("config is:\n%v", cfg),
		slog.String("version", version.Version),
		slog.String("build", version.GitCommit),
	)

	if cfg.Experimental {
		slog.SetDefault(slog.Default().With("experimental", true))
		slog.DebugContext(ctx, "experimental functions and features enabled!")
	}

	// silence errors & usage from here on
	cmd.SilenceErrors = true
	cmd.SilenceUsage = true

	start := time.Now()
	n, errCount, err := gomplate.RunTemplates(ctx, cfg)
	slog.DebugContext(ctx, "completed rendering",
		slog.Int("templatesRendered", n),
		slog.Int("errors", errCount),
		slog.Duration("duration", time.Since(start)))
	if err != nil {
		return err
	}

	return postRunExec(ctx, cfg.PostExec, stdin, stdout, stderr, cfg.ExecPipe, gomplate.PipeBuffer(cfg))
}

func loadConfig(ctx context.Context, cmd *cobra.Command, args []string) (*config.Config, error) {
	flagConfig, err := cobraConfig(cmd, args)
	if err != nil {
		return nil, err
	}

	cfg, err := readConfigFile(ctx, cmd)
	if err != nil {
		return nil, err
	}
	if cfg == nil {
		cfg = flagConfig
	} else {
		cfg = cfg.MergeFrom(flagConfig)
	}

	if !cfg.Experimental {
		if v, ok := os.LookupEnv("GOMPLATE_EXPERIMENTAL"); ok && conv_ToBool(v) {
			cfg.Experimental = true
		}
	}
	return cfg, nil
}

func conv_ToBool(s string) bool {
	switch strings.ToLower(s) {
	case "1", "t", "true", "yes":
		return true
	}
	return false
}

func readConfigFile(ctx context.Context, cmd *cobra.Command) (*config.Config, error) {
	cfgFile := ".gomplate.yaml"
	required := false
	if c := cmd.Flags().Lookup("config"); c != nil && c.Changed {
		cfgFile = c.Value.String()
		required = true
	} else if v, ok := os.LookupEnv("GOMPLATE_CONFIG"); ok {
		cfgFile = v
		required = true
	}
	if cfgFile == "" {
		return nil, nil
	}

	f, err := gomplate.OpenFile(cfgFile)
	if err != nil {
		if required {
			return nil, fmt.Errorf("config file requested, but couldn't be opened: %w", err)
		}
		return nil, nil
	}
	defer f.Close()

	cfg, err := config.Parse(f)
	if err != nil && required {
		return nil, fmt.Errorf("parsing config file %q: %w", cfgFile, err)
	}
	if err != nil {
		return nil, fmt.Errorf("parsing config file %q: %w", cfgFile, err)
	}

	slog.DebugContext(ctx, "using config file", "cfgFile", cfgFile)
	return cfg, nil
}

func cobraConfig(cmd *cobra.Command, args []string) (*config.Config, error) {
	cfg := &config.Config{}
	fl := cmd.Flags()

	changed := func(name string) bool {
		f := fl.Lookup(name)
		return f != nil && f.Changed
	}
	getSlice := func(name string) []string {
		v, _ := fl.GetStringSlice(name)
		return v
	}
	getString := func(name string) string {
		v, _ := fl.GetString(name)
		return v
	}
	getBool := func(name string) bool {
		v, _ := fl.GetBool(name)
		return v
	}

	if changed("file") {
		cfg.InputFiles = getSlice("file")
	}
	cfg.Input = getString("in")
	cfg.InputDir = getString("input-dir")
	if changed("out") {
		cfg.OutputFiles = getSlice("out")
	}
	if changed("output-dir") {
		cfg.OutputDir = getString("output-dir")
	}
	cfg.OutputMap = getString("output-map")
	cfg.OutMode = getString("chmod")

	cfg.ExecPipe = getBool("exec-pipe")
	if cfg.ExecPipe {
		cfg.OutputFiles = []string{"-"}
	}

	if changed("left-delim") || os.Getenv("GOMPLATE_LEFT_DELIM") != "" {
		cfg.LDelim = getString("left-delim")
	}
	if changed("right-delim") || os.Getenv("GOMPLATE_RIGHT_DELIM") != "" {
		cfg.RDelim = getString("right-delim")
	}
	if changed("missing-key") {
		cfg.MissingKey = getString("missing-key")
	}
	cfg.Experimental = getBool("experimental")

	includes := getSlice("include")
	excludes := getSlice("exclude")
	if len(includes) > 0 {
		globs := []string{"*"}
		for _, inc := range includes {
			globs = append(globs, "!"+inc)
		}
		excludes = append(globs, excludes...)
	}
	if len(excludes) > 0 {
		cfg.ExcludeGlob = excludes
	}
	if ep := getSlice("exclude-processing"); len(ep) > 0 {
		cfg.ExcludeProcessingGlob = ep
	}

	if err := cfg.ParsePluginFlags(getSlice("plugin")); err != nil {
		return nil, err
	}
	if err := cfg.ParseDataSourceFlags(
		getSlice("datasource"), getSlice("context"),
		getSlice("template"), getSlice("datasource-header")); err != nil {
		return nil, err
	}

	if d := cmd.ArgsLenAtDash(); d >= 0 && len(args) > d {
		cfg.PostExec = args[d:]
	}
	return cfg, nil
}

func postRunExec(ctx context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer, execPipe bool, pipe io.Reader) error {
	if len(args) == 0 {
		return nil
	}
	slog.DebugContext(ctx, "running post-exec command", "args", args)

	name := args[0]
	c := exec.CommandContext(ctx, name, args[1:]...)
	if execPipe {
		c.Stdin = pipe
	} else {
		c.Stdin = stdin
	}
	c.Stderr = stderr
	c.Stdout = stdout

	sigs := make(chan os.Signal, 1)
	signal.Notify(sigs)
	defer signal.Stop(sigs)

	if err := c.Start(); err != nil {
		return err
	}
	go func() {
		for sig := range sigs {
			if c.Process != nil {
				_ = c.Process.Signal(sig)
			}
		}
	}()
	err := c.Wait()
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		return err
	}
	return err
}
EOF
echo ok

