// yamlDecodeFirst decodes documents from the input until a non-empty value
// has been decoded into out
func yamlDecodeFirst(in string, out any) error {
	dec := yaml.NewDecoder(strings.NewReader(in))
	for {
		err := dec.Decode(out)
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		v := reflect.ValueOf(out).Elem()
		if !v.IsZero() {
			return nil
		}
	}
}

// JSON - Unmarshal a JSON Object. Can be ejson-encrypted.
func JSON(in string) (map[string]any, error) {
	obj := make(map[string]any)
	if err := yamlDecodeFirst(in, &obj); err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %w", in, err)
	}
	if obj == nil {
		obj = map[string]any{}
	}
	if pk, ok := obj["_public_key"]; ok && pk != nil {
		dec, err := decryptEJSON(in)
		if err != nil {
			return nil, err
		}
		return dec, nil
	}
	return stringifyMapKeys(obj).(map[string]any), nil
}

// JSONArray - Unmarshal a JSON Array
func JSONArray(in string) ([]any, error) {
	obj := make([]any, 1)
	if err := yamlDecodeFirst(in, &obj); err != nil {
		return nil, fmt.Errorf("unable to unmarshal array %s: %w", in, err)
	}
	return stringifyMapKeys(obj).([]any), nil
}

// YAML - Unmarshal a YAML Object
func YAML(in string) (map[string]any, error) {
	obj := make(map[string]any)
	if err := yamlDecodeFirst(in, &obj); err != nil {
		return nil, err
	}
	if obj == nil {
		obj = map[string]any{}
	}
	return stringifyMapKeys(obj).(map[string]any), nil
}

// YAMLArray - Unmarshal a YAML Array
func YAMLArray(in string) ([]any, error) {
	obj := make([]any, 1)
	if err := yamlDecodeFirst(in, &obj); err != nil {
		return nil, err
	}
	return stringifyMapKeys(obj).([]any), nil
}

// stringifyMapKeys recursively converts map[any]any into map[string]any
func stringifyMapKeys(in any) any {
	switch v := in.(type) {
	case map[string]any:
		for k, val := range v {
			v[k] = stringifyMapKeys(val)
		}
		return v
	case map[any]any:
		out := make(map[string]any, len(v))
		for k, val := range v {
			out[conv.ToString(k)] = stringifyMapKeys(val)
		}
		return out
	case []any:
		for i, val := range v {
			v[i] = stringifyMapKeys(val)
		}
		return v
	}
	return in
}

// TOML - Unmarshal a TOML Object
func TOML(in string) (any, error) {
	obj := make(map[string]any)
	if _, err := toml.Decode(in, &obj); err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %w", in, tomlError(err))
	}
	return obj, nil
}

type tomlErr struct {
	msg string
	err error
}

func (e *tomlErr) Error() string { return e.msg }
func (e *tomlErr) Unwrap() error { return e.err }

func tomlError(err error) error {
	var pe toml.ParseError
	if errors.As(err, &pe) {
		msg := pe.Message
		if msg == "" {
			msg = strings.TrimPrefix(pe.Error(), "toml: ")
		}
		return &tomlErr{msg: fmt.Sprintf("Near line %d (last key parsed '%s'): %s", pe.Position.Line, pe.LastKey, msg), err: err}
	}
	return err
}

func parseCSV(args ...string) ([][]string, []string, error) {
	in, delim, hdr := csvParseArgs(args...)
	c := csv.NewReader(strings.NewReader(in))
	c.Comma = rune(delim[0])
	records, err := c.ReadAll()
	if err != nil {
		return nil, nil, err
	}
	if len(records) > 0 {
		if hdr == nil {
			hdr = records[0]
			records = records[1:]
		} else if len(hdr) == 0 {
			hdr = autoIndex(len(records[0]))
		}
	}
	return records, hdr, nil
}

func csvParseArgs(args ...string) (in, delim string, hdr []string) {
	delim = ","
	switch len(args) {
	case 1:
		in = args[0]
	case 2:
		in = args[1]
		switch len(args[0]) {
		case 1:
			delim = args[0]
		case 0:
			hdr = []string{}
		default:
			hdr = strings.Split(args[0], delim)
		}
	case 3:
		delim = args[0]
		hdr = strings.Split(args[1], delim)
		in = args[2]
	}
	return in, delim, hdr
}

// autoIndex - calculates a default string column name given a numeric value
func autoIndex(n int) []string {
	out := make([]string, n)
	for i := 0; i < n; i++ {
		out[i] = autoIndexName(i)
	}
	return out
}

func autoIndexName(i int) string {
	l := 26
	s := ""
	s += string(rune('A' + i%l))
	for j := i / l; j > 0; j /= l {
		s += string(rune('A' + i%l))
	}
	return s
}

// CSV - Unmarshal CSV
func CSV(args ...string) ([][]string, error) {
	records, hdr, err := parseCSV(args...)
	if err != nil {
		return nil, err
	}
	records = append(records, nil)
	copy(records[1:], records)
	records[0] = hdr
	return records, nil
}

// CSVByRow - Unmarshal CSV in a row-oriented form
func CSVByRow(args ...string) (rows []map[string]string, err error) {
	records, hdr, err := parseCSV(args...)
	if err != nil {
		return nil, err
	}
	for _, record := range records {
		m := make(map[string]string)
		for i, v := range record {
			m[hdr[i]] = v
		}
		rows = append(rows, m)
	}
	return rows, nil
}

// CSVByColumn - Unmarshal CSV in a Columnar form
func CSVByColumn(args ...string) (cols map[string][]string, err error) {
	records, hdr, err := parseCSV(args...)
	if err != nil {
		return nil, err
	}
	cols = make(map[string][]string)
	for _, record := range records {
		for i, v := range record {
			cols[hdr[i]] = append(cols[hdr[i]], v)
		}
	}
	return cols, nil
}

// ToCSV -
func ToCSV(args ...any) (string, error) {
	delim := ","
	var in any
	if len(args) == 2 {
		var ok bool
		delim, ok = args[0].(string)
		if !ok {
			return "", fmt.Errorf("can't parse ToCSV delimiter (%v) - must be string (is a %T)", args[0], args[0])
		}
		in = args[1]
	}
	if len(args) == 1 {
		in = args[0]
	}

	if len(delim) != 1 {
		return "", fmt.Errorf("can't use delimiter %q", delim)
	}

	b := &bytes.Buffer{}
	c := csv.NewWriter(b)
	c.Comma = rune(delim[0])
	// We output RFC4180 CSV, so force this to CRLF
	c.UseCRLF = true
	var data [][]string
	if in != nil {
		var err error
		data, err = toStringSlices(in)
		if err != nil {
			return "", err
		}
	}
	err := c.WriteAll(data)
	return b.String(), err
}

func toStringSlices(in any) ([][]string, error) {
	switch v := in.(type) {
	case [][]string:
		return v, nil
	case []any:
		out := make([][]string, len(v))
		for i, row := range v {
			switch r := row.(type) {
			case []string:
				out[i] = r
			case []any:
				out[i] = conv.ToStrings(r...)
			default:
				return nil, fmt.Errorf("can't parse ToCSV input - must be a two-dimensional array (like [][]string or [][]any) (was %T)", in)
			}
		}
		return out, nil
	}
	return nil, fmt.Errorf("can't parse ToCSV input - must be a two-dimensional array (like [][]string or [][]any) (was %T)", in)
}

// ToJSON - Stringify a struct as JSON
func ToJSON(in any) (string, error) {
	s, err := toJSONBytes(in)
	if err != nil {
		return "", err
	}
	return string(s), nil
}

// ToJSONPretty - Stringify a struct as JSON (indented)
func ToJSONPretty(indent string, in any) (string, error) {
	out := new(bytes.Buffer)
	b, err := toJSONBytes(in)
	if err != nil {
		return "", err
	}
	if len(b) == 0 {
		return "", nil
	}
	err = json.Indent(out, b, "", indent)
	if err != nil {
		return "", fmt.Errorf("unable to indent JSON %s: %w", b, err)
	}
	return out.String(), nil
}

func toJSONBytes(in any) ([]byte, error) {
	buf := &bytes.Buffer{}
	e := &jsonEncoder{buf: buf}
	if err := e.encode(reflect.ValueOf(in)); err != nil {
		return nil, fmt.Errorf("unable to marshal %s: %w", in, err)
	}
	return buf.Bytes(), nil
}

