func (e *jsonEncoder) encode(v reflect.Value) error {
	if !v.IsValid() {
		e.buf.WriteString("null")
		return nil
	}

	// check for marshalers
	if v.Kind() != reflect.Interface {
		if v.Type().Implements(jsonMarshalerType) {
			if (v.Kind() == reflect.Pointer || v.Kind() == reflect.Map || v.Kind() == reflect.Slice) && v.IsNil() {
				e.buf.WriteString("null")
				return nil
			}
			b, err := v.Interface().(json.Marshaler).MarshalJSON()
			if err != nil {
				return err
			}
			e.buf.Write(b)
			return nil
		}
		if v.Kind() != reflect.Pointer && reflect.PointerTo(v.Type()).Implements(jsonMarshalerType) && v.CanAddr() {
			b, err := v.Addr().Interface().(json.Marshaler).MarshalJSON()
			if err != nil {
				return err
			}
			e.buf.Write(b)
			return nil
		}
		if v.Type().Implements(textMarshalerType) {
			if v.Kind() == reflect.Pointer && v.IsNil() {
				e.buf.WriteString("null")
				return nil
			}
			b, err := v.Interface().(encoding.TextMarshaler).MarshalText()
			if err != nil {
				return err
			}
			e.writeString(string(b))
			return nil
		}
		if v.Kind() != reflect.Pointer && reflect.PointerTo(v.Type()).Implements(textMarshalerType) {
			pv := reflect.New(v.Type())
			pv.Elem().Set(v)
			b, err := pv.Interface().(encoding.TextMarshaler).MarshalText()
			if err != nil {
				return err
			}
			e.writeString(string(b))
			return nil
		}
	}

	switch v.Kind() {
	case reflect.Interface, reflect.Pointer:
		if v.IsNil() {
			e.buf.WriteString("null")
			return nil
		}
		return e.encode(v.Elem())
	case reflect.Bool:
		if v.Bool() {
			e.buf.WriteString("true")
		} else {
			e.buf.WriteString("false")
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		e.buf.WriteString(strconv.FormatInt(v.Int(), 10))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		e.buf.WriteString(strconv.FormatUint(v.Uint(), 10))
	case reflect.Float32:
		e.writeFloat(v.Float(), 32)
	case reflect.Float64:
		e.writeFloat(v.Float(), 64)
	case reflect.String:
		e.writeString(v.String())
	case reflect.Slice:
		if v.IsNil() {
			e.buf.WriteString("null")
			return nil
		}
		if v.Type().Elem().Kind() == reflect.Uint8 {
			e.buf.WriteByte('"')
			e.buf.WriteString(base64.StdEncoding.EncodeToString(v.Bytes()))
			e.buf.WriteByte('"')
			return nil
		}
		return e.encodeArray(v)
	case reflect.Array:
		return e.encodeArray(v)
	case reflect.Map:
		if v.IsNil() {
			e.buf.WriteString("null")
			return nil
		}
		return e.encodeMap(v)
	case reflect.Struct:
		return e.encodeStruct(v)
	default:
		return fmt.Errorf("unsupported type: %s", v.Type())
	}
	return nil
}

func (e *jsonEncoder) encodeArray(v reflect.Value) error {
	e.buf.WriteByte('[')
	for i := 0; i < v.Len(); i++ {
		if i > 0 {
			e.buf.WriteByte(',')
		}
		if err := e.encode(v.Index(i)); err != nil {
			return err
		}
	}
	e.buf.WriteByte(']')
	return nil
}

func (e *jsonEncoder) encodeMap(v reflect.Value) error {
	type kv struct {
		k string
		v reflect.Value
	}
	kvs := make([]kv, 0, v.Len())
	iter := v.MapRange()
	for iter.Next() {
		k := iter.Key()
		for k.Kind() == reflect.Interface && !k.IsNil() {
			k = k.Elem()
		}
		ks := ""
		switch k.Kind() {
		case reflect.String:
			ks = k.String()
		default:
			if k.IsValid() && k.Type().Implements(textMarshalerType) {
				b, err := k.Interface().(encoding.TextMarshaler).MarshalText()
				if err != nil {
					return err
				}
				ks = string(b)
			} else if k.IsValid() {
				ks = fmt.Sprint(k.Interface())
			}
		}
		kvs = append(kvs, kv{ks, iter.Value()})
	}
	sort.Slice(kvs, func(i, j int) bool { return kvs[i].k < kvs[j].k })
	e.buf.WriteByte('{')
	for i, p := range kvs {
		if i > 0 {
			e.buf.WriteByte(',')
		}
		e.writeString(p.k)
		e.buf.WriteByte(':')
		if err := e.encode(p.v); err != nil {
			return err
		}
	}
	e.buf.WriteByte('}')
	return nil
}

type structField struct {
	name      string
	index     []int
	omitEmpty bool
}

func structFields(t reflect.Type) []structField {
	fields := []structField{}
	var walk func(t reflect.Type, index []int)
	walk = func(t reflect.Type, index []int) {
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			idx := append(append([]int{}, index...), i)
			tag := f.Tag.Get("codec")
			if tag == "" {
				tag = f.Tag.Get("json")
			}
			if tag == "-" {
				continue
			}
			name, opts, _ := strings.Cut(tag, ",")
			if f.Anonymous && name == "" {
				ft := f.Type
				if ft.Kind() == reflect.Pointer {
					ft = ft.Elem()
				}
				if ft.Kind() == reflect.Struct {
					walk(ft, idx)
					continue
				}
			}
			if !f.IsExported() {
				continue
			}
			if name == "" {
				name = f.Name
			}
			fields = append(fields, structField{name: name, index: idx, omitEmpty: strings.Contains(opts, "omitempty")})
		}
	}
	walk(t, nil)
	sort.SliceStable(fields, func(i, j int) bool { return fields[i].name < fields[j].name })
	return fields
}

func (e *jsonEncoder) encodeStruct(v reflect.Value) error {
	e.buf.WriteByte('{')
	first := true
	for _, f := range structFields(v.Type()) {
		fv, ok := fieldByIndex(v, f.index)
		if !ok {
			continue
		}
		if f.omitEmpty && fv.IsZero() {
			continue
		}
		if !first {
			e.buf.WriteByte(',')
		}
		first = false
		e.writeString(f.name)
		e.buf.WriteByte(':')
		if err := e.encode(fv); err != nil {
			return err
		}
	}
	e.buf.WriteByte('}')
	return nil
}

func fieldByIndex(v reflect.Value, index []int) (reflect.Value, bool) {
	for i, x := range index {
		if i > 0 && v.Kind() == reflect.Pointer {
			if v.IsNil() {
				return reflect.Value{}, false
			}
			v = v.Elem()
		}
		v = v.Field(x)
	}
	return v, true
}

func (e *jsonEncoder) writeFloat(f float64, bits int) {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		e.buf.WriteString("null")
		return
	}
	abs := math.Abs(f)
	fmtc := byte('f')
	prec := -1
	if abs == 0 || abs == 1 {
		prec = 1
	} else if (bits == 64 && (abs < 1e-6 || abs >= 1e21)) || (bits == 32 && (float32(abs) < 1e-6 || float32(abs) >= 1e21)) {
		fmtc = 'e'
	} else if noFrac(f, bits) {
		prec = 1
	}
	e.buf.WriteString(strconv.FormatFloat(f, fmtc, prec, bits))
}

func noFrac(f float64, bits int) bool {
	if bits == 32 {
		fb := math.Float32bits(float32(f))
		exp := uint32(fb>>23)&0xFF - 127
		return exp < 23 && fb<<(9+exp) == 0
	}
	fb := math.Float64bits(f)
	exp := uint64(fb>>52)&0x7FF - 1023
	return exp < 52 && fb<<(12+exp) == 0
}

const hexLower = "0123456789abcdef"

func (e *jsonEncoder) writeString(s string) {
	b := e.buf
	b.WriteByte('"')
	for i := 0; i < len(s); {
		c := s[i]
		if c < utf8.RuneSelf {
			switch {
			case c == '\\' || c == '"':
				b.WriteByte('\\')
				b.WriteByte(c)
			case c == '\b':
				b.WriteString(`\b`)
			case c == '\f':
				b.WriteString(`\f`)
			case c == '\n':
				b.WriteString(`\n`)
			case c == '\r':
				b.WriteString(`\r`)
			case c == '\t':
				b.WriteString(`\t`)
			case c < 0x20 || c == '<' || c == '>' || c == '&':
				b.WriteString(`\u00`)
				b.WriteByte(hexLower[c>>4])
				b.WriteByte(hexLower[c&0xF])
			default:
				b.WriteByte(c)
			}
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			b.WriteString(`\uFFFD`)
			i++
			continue
		}
		if r == '\u2028' || r == '\u2029' {
			b.WriteString(`\u202`)
			b.WriteByte(hexLower[r&0xF])
			i += size
			continue
		}
		b.WriteString(s[i : i+size])
		i += size
	}
	b.WriteByte('"')
}
EOF
echo ok

