{"command":"cat > /workspace/data/cue.go <<'EOF'
package data

import (
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"math"
	"math/big"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"
)

// ToCUE - marshal the input as a CUE document
func ToCUE(in any) (string, error) {
	w := &cueWriter{}
	if err := w.value(reflect.ValueOf(in), 0); err != nil {
		return "", fmt.Errorf("unable to marshal %s: %w", in, err)
	}
	return w.buf.String(), nil
}

type cueWriter struct {
	buf bytes.Buffer
}

func cueIndent(n int) string { return strings.Repeat("\t", n) }

func (w *cueWriter) value(v reflect.Value, depth int) error {
	for v.IsValid() && (v.Kind() == reflect.Interface || v.Kind() == reflect.Pointer) {
		if v.IsNil() {
			w.buf.WriteString("null")
			return nil
		}
		v = v.Elem()
	}
	if !v.IsValid() {
		w.buf.WriteString("null")
		return nil
	}
	if t, ok := v.Interface().(time.Time); ok {
		w.buf.WriteString(cueString(t.Format(time.RFC3339Nano), depth))
		return nil
	}
	switch v.Kind() {
	case reflect.Bool:
		w.buf.WriteString(strconv.FormatBool(v.Bool()))
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		w.buf.WriteString(strconv.FormatInt(v.Int(), 10))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		w.buf.WriteString(strconv.FormatUint(v.Uint(), 10))
	case reflect.Float32, reflect.Float64:
		w.buf.WriteString(cueFloat(v.Float()))
	case reflect.String:
		w.buf.WriteString(cueString(v.String(), depth))
	case reflect.Slice, reflect.Array:
		if v.Kind() == reflect.Slice && v.Type().Elem().Kind() == reflect.Uint8 {
			w.buf.WriteString(cueBytes(v.Bytes()))
			return nil
		}
		w.buf.WriteByte('[')
		for i := 0; i < v.Len(); i++ {
			if i > 0 {
				w.buf.WriteString(", ")
			}
			if err := w.value(v.Index(i), depth); err != nil {
				return err
			}
		}
		w.buf.WriteByte(']')
	case reflect.Map:
		keys := []string{}
		vals := map[string]reflect.Value{}
		iter := v.MapRange()
		for iter.Next() {
			k := fmt.Sprint(iter.Key().Interface())
			keys = append(keys, k)
			vals[k] = iter.Value()
		}
		sort.Strings(keys)
		return w.structFields(keys, vals, depth)
	case reflect.Struct:
		keys := []string{}
		vals := map[string]reflect.Value{}
		for _, f := range structFields(v.Type()) {
			fv, ok := fieldByIndex(v, f.index)
			if !ok {
				continue
			}
			if f.omitEmpty && fv.IsZero() {
				continue
			}
			keys = append(keys, f.name)
			vals[f.name] = fv
		}
		return w.structFields(keys, vals, depth)
	default:
		return fmt.Errorf("unsupported type %s", v.Type())
	}
	return nil
}

func isCueSimple(v reflect.Value) bool {
	for v.IsValid() && (v.Kind() == reflect.Interface || v.Kind() == reflect.Pointer) {
		if v.IsNil() {
			return true
		}
		v = v.Elem()
	}
	if !v.IsValid() {
		return true
	}
	switch v.Kind() {
	case reflect.Map, reflect.Struct, reflect.Array:
		if _, ok := v.Interface().(time.Time); ok {
			return true
		}
		return false
	case reflect.Slice:
		return v.Type().Elem().Kind() == reflect.Uint8
	case reflect.String:
		return !strings.Contains(v.String(), "\n")
	}
	return true
}

func (w *cueWriter) structFields(keys []string, vals map[string]reflect.Value, depth int) error {
	if len(keys) == 0 {
		w.buf.WriteString("{}")
		return nil
	}
	w.buf.WriteString("{\n")
	// group consecutive simple fields for alignment
	type line struct {
		label  string
		simple bool
		value  string
	}
	lines := []line{}
	for _, k := range keys {
		sub := &cueWriter{}
		if err := sub.value(vals[k], depth+1); err != nil {
			return err
		}
		lines = append(lines, line{label: cueLabel(k) + ":", simple: isCueSimple(vals[k]), value: sub.buf.String()})
	}
	for i := 0; i < len(lines); {
		if !lines[i].simple {
			w.buf.WriteString(cueIndent(depth + 1))
			w.buf.WriteString(lines[i].label)
			w.buf.WriteByte(' ')
			w.buf.WriteString(lines[i].value)
			w.buf.WriteByte('\n')
			i++
			continue
		}
		j := i
		width := 0
		for j < len(lines) && lines[j].simple {
			if l := len([]rune(lines[j].label)); l > width {
				width = l
			}
			j++
		}
		for ; i < j; i++ {
			w.buf.WriteString(cueIndent(depth + 1))
			w.buf.WriteString(lines[i].label)
			w.buf.WriteString(strings.Repeat(" ", width-len([]rune(lines[i].label))+1))
			w.buf.WriteString(lines[i].value)
			w.buf.WriteByte('\n')
		}
	}
	w.buf.WriteString(cueIndent(depth))
	w.buf.WriteByte('}')
	return nil
}

func cueLabel(k string) string {
	if isCueIdent(k) {
		return k
	}
	return strconv.Quote(k)
}

func isCueIdent(s string) bool {
	if s == "" {
		return false
	}
	if strings.HasPrefix(s, "#") || strings.HasPrefix(s, "_") {
		return false
	}
	for i, r := range s {
		if r == '$' || r == '_' || unicode.IsLetter(r) {
			continue
		}
		if i > 0 && unicode.IsDigit(r) {
			continue
		}
		return false
	}
	return true
}

func cueString(s string, depth int) string {
	if strings.Contains(s, "\n") {
		var b strings.Builder
		b.WriteString(`"""`)
		b.WriteByte('\n')
		for _, l := range strings.Split(s, "\n") {
			if l != "" {
				b.WriteString(cueIndent(depth + 1))
			}
			q := strconv.Quote(l)
			q = q[1 : len(q)-1]
			q = strings.ReplaceAll(q, `\"`, `"`)
			b.WriteString(q)
			b.WriteByte('\n')
		}
		b.WriteString(cueIndent(depth + 1))
		b.WriteString(`"""`)
		return b.String()
	}
	return strconv.Quote(s)
}

func cueBytes(b []byte) string {
	var sb strings.Builder
	sb.WriteByte('\'')
	for _, c := range b {
		switch {
		case c == '\'':
			sb.WriteString(`\'`)
		case c == '\\':
			sb.WriteString(`\\`)
		case c == '\n':
			sb.WriteString(`\n`)
		case c == '\t':
			sb.WriteString(`\t`)
		case c >= 0x20 && c < 0x7f:
			sb.WriteByte(c)
		default:
			sb.WriteString(fmt.Sprintf(`\x%02x`, c))
		}
	}
	sb.WriteByte('\'')
	_ = base64.StdEncoding
	return sb.String()
}

// cueFloat formats a float like CUE's decimal representation
func cueFloat(f float64) string {
	if math.IsInf(f, 1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	// shortest decimal representation
	s := strconv.FormatFloat(f, 'e', -1, 64)
	mant, expS, _ := strings.Cut(s, "e")
	exp, _ := strconv.Atoi(expS)
	neg := strings.HasPrefix(mant, "-")
	mant = strings.TrimPrefix(mant, "-")
	digits := strings.Replace(mant, ".", "", 1)
	// coefficient digits & exponent (value = digits * 10^(exp - (len(digits)-1)))
	e := exp - (len(digits) - 1)
	sign := ""
	if neg {
		sign = "-"
	}
	// apd-style to-string: if e <= 0 and adjusted exponent >= -6, plain
	adj := e + len(digits) - 1
	var out string
	if e <= 0 && adj >= -6 {
		if e == 0 {
			out = digits
		} else {
			n := -e
			if n >= len(digits) {
				out = "0." + strings.Repeat("0", n-len(digits)) + digits
			} else {
				out = digits[:len(digits)-n] + "." + digits[len(digits)-n:]
			}
		}
	} else {
		out = digits[:1]
		if len(digits) > 1 {
			out += "." + digits[1:]
		}
		if adj >= 0 {
			out += "e+" + strconv.Itoa(adj)
		} else {
			out += "e" + strconv.Itoa(adj)
		}
	}
	if !strings.ContainsAny(out, ".e") {
		out += ".0"
	}
	_ = big.NewInt
	return sign + out
}

// CUE - parse a CUE document
func CUE(in string) (any, error) {
	p := &cueParser{src: in}
	v, err := p.parseFile()
	if err != nil {
		return nil, fmt.Errorf("unable to process CUE: %w", err)
	}
	return v, nil
}

