			if l != "" {
				b.WriteString(cueIndent(depth + 1))
			}
			q := strconv.Quote(l)
			q = q[1 : len(q)-1]
			q = strings.ReplaceAll(q, `\"`, `"`)
			b.WriteString(q)
			b.WriteByte('\n')
		}
		b.WriteString(cueIndent(depth + 1))
		b.WriteString(`"""`)
		return b.String()
	}
	return strconv.Quote(s)
}

