// Package datasources handles reading data from datasources
package datasources

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"mime"
	"net/http"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/hairyhenderson/gomplate/v4/data"
	"github.com/hairyhenderson/gomplate/v4/internal/config"
)

// MIME types
const (
	TextMimetype      = "text/plain"
	CSVMimetype       = "text/csv"
	JSONMimetype      = "application/json"
	JSONArrayMimetype = "application/array+json"
	TOMLMimetype      = "application/toml"
	YAMLMimetype      = "application/yaml"
	EnvMimetype       = "application/x-env"
	CUEMimetype       = "application/cue"
)

func init() {
	_ = mime.AddExtensionType(".json", JSONMimetype)
	_ = mime.AddExtensionType(".yml", YAMLMimetype)
	_ = mime.AddExtensionType(".yaml", YAMLMimetype)
	_ = mime.AddExtensionType(".csv", CSVMimetype)
	_ = mime.AddExtensionType(".toml", TOMLMimetype)
	_ = mime.AddExtensionType(".env", EnvMimetype)
	_ = mime.AddExtensionType(".cue", CUEMimetype)
}

// Source - a datasource definition
type Source struct {
	Alias  string
	URL    *url.URL
	Header http.Header
}

// Registry holds the datasources
type Registry struct {
	mu           sync.RWMutex
	sources      map[string]*Source
	extraHeaders map[string]http.Header
	stdin        io.Reader
	stdinData    []byte
	stdinRead    bool
	cache        map[string]*cached
}

type cached struct {
	data []byte
	mime string
}

// NewRegistry -
func NewRegistry(cfg *config.Config) *Registry {
	r := &Registry{
		sources:      map[string]*Source{},
		extraHeaders: cfg.ExtraHeaders,
		stdin:        cfg.Stdin,
		cache:        map[string]*cached{},
	}
	for k, v := range cfg.DataSources {
		r.sources[k] = &Source{Alias: k, URL: v.URL, Header: v.Header}
	}
	for k, v := range cfg.Context {
		r.sources[k] = &Source{Alias: k, URL: v.URL, Header: v.Header}
	}
	return r
}

// Lookup a datasource
func (r *Registry) Lookup(alias string) (*Source, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	s, ok := r.sources[alias]
	return s, ok
}

// Register a datasource (if not already registered)
func (r *Registry) Register(alias string, u *url.URL, h http.Header) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.sources[alias]; ok {
		return
	}
	if h == nil {
		if eh, ok := r.extraHeaders[alias]; ok {
			h = eh
		}
	}
	r.sources[alias] = &Source{Alias: alias, URL: u, Header: h}
}

// List the aliases
func (r *Registry) List() []string {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]string, 0, len(r.sources))
	for k := range r.sources {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// errUndefined is returned when a datasource is not defined
type undefinedError struct {
	alias string
}

func (e *undefinedError) Error() string {
	return fmt.Sprintf("undefined datasource '%s': %%!w(<nil>)", e.alias)
}

// ResolveSource finds (or dynamically defines) a datasource
func (r *Registry) ResolveSource(alias string) (*Source, error) {
	if s, ok := r.Lookup(alias); ok {
		return s, nil
	}
	u, err := url.Parse(alias)
	if err != nil || !u.IsAbs() {
		return nil, &undefinedError{alias}
	}
	r.Register(alias, u, nil)
	s, _ := r.Lookup(alias)
	return s, nil
}

// subURL resolves the args (sub-paths) against the source URL
func subURL(base *url.URL, args ...string) (*url.URL, error) {
	if len(args) == 0 || args[0] == "" {
		return base, nil
	}
	ref, err := url.Parse(args[0])
	if err != nil {
		return nil, err
	}
	if base.Opaque != "" {
		// opaque URLs (e.g. env:FOO, merge:a|b) - append the subpath
		u := *base
		u.Opaque = base.Opaque + ref.Path
		if ref.RawQuery != "" {
			u.RawQuery = ref.RawQuery
		}
		return &u, nil
	}
	u := base.ResolveReference(ref)
	if ref.RawQuery == "" && base.RawQuery != "" {
		u.RawQuery = base.RawQuery
	}
	return u, nil
}

// Read the raw data for the given alias & args
func (r *Registry) Read(ctx context.Context, alias string, args ...string) ([]byte, string, error) {
	src, err := r.ResolveSource(alias)
	if err != nil {
		return nil, "", err
	}
	u, err := subURL(src.URL, args...)
	if err != nil {
		return nil, "", err
	}
	header := src.Header
	if eh, ok := r.extraHeaders[alias]; ok && header == nil {
		header = eh
	}
	b, mt, err := r.readURL(ctx, u, header, src.URL.Scheme == "" && !src.URL.IsAbs())
	if err != nil {
		return nil, "", fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, u, err)
	}
	return b, mt, nil
}

func typeParamName() string {
	if p := os.Getenv("GOMPLATE_TYPE_PARAM"); p != "" {
		return p
	}
	return "type"
}

// typeOverride returns the mime type from the URL query, if present
func typeOverride(u *url.URL) string {
	return u.Query().Get(typeParamName())
}

func mimeFromExt(p string) string {
	ext := filepath.Ext(p)
	if ext == "" {
		return ""
	}
	return mime.TypeByExtension(ext)
}

// readURL reads the raw content at the URL
func (r *Registry) readURL(ctx context.Context, u *url.URL, header http.Header, relative bool) ([]byte, string, error) {
	key := u.String()
	r.mu.RLock()
	c, ok := r.cache[key]
	r.mu.RUnlock()
	if ok {
		return c.data, c.mime, nil
	}

	var (
		b   []byte
		mt  string
		err error
	)
	switch u.Scheme {
	case "", "file":
		b, mt, err = readFile(u, relative)
	case "env":
		b, mt, err = readEnv(u)
	case "stdin":
		b, mt, err = r.readStdin(u)
	case "http", "https":
		b, mt, err = readHTTP(ctx, u, header)
	case "merge":
		b, mt, err = r.readMerge(ctx, u)
	default:
		b, mt, err = readUnsupported(u)
	}
	if err != nil {
		return nil, "", err
	}
	if t := typeOverride(u); t != "" {
		mt = t
	}
	r.mu.Lock()
	r.cache[key] = &cached{data: b, mime: mt}
	r.mu.Unlock()
	return b, mt, nil
}

// fsPathError formats an error the way an fs rooted at base would
func fsPathError(op, base, name string, err error) error {
	return fmt.Errorf("%s (url: %q, name: %q): %w", op, base, name, err)
}

// ToFSPath converts a native path into a path relative to the root of the
// filesystem
func ToFSPath(p string) string {
	if !filepath.IsAbs(p) {
		wd, _ := os.Getwd()
		p = filepath.Join(wd, p)
	}
	p = filepath.Clean(p)
	p = strings.TrimPrefix(filepath.ToSlash(p), "/")
	if p == "" {
		p = "."
	}
	return p
}

// RootFS is the filesystem rooted at /
var RootFS = os.DirFS("/")

func readFile(u *url.URL, relative bool) ([]byte, string, error) {
	p := u.Path
	if u.Opaque != "" {
		p = u.Opaque
	}
	base := "file:///"
	name := p
	fsPath := ""
	if relative {
		base = "/"
		name = strings.TrimPrefix(p, "/")
		if name == "" {
			name = "."
		}
		fsPath = ToFSPath(name)
	} else {
		fsPath = ToFSPath(p)
	}
	isDirURL := strings.HasSuffix(p, "/")

	fi, err := fs.Stat(RootFS, fsPath)
	if err != nil {
		if isDirURL {
			name = strings.TrimSuffix(name, "/")
		}
		return nil, "", fsPathError("open", base, name, err)
	}
	if fi.IsDir() {
		entries, err := fs.ReadDir(RootFS, fsPath)
		if err != nil {
			return nil, "", fsPathError("open", base, name, err)
		}
		names := make([]string, len(entries))
		for i, e := range entries {
			names[i] = e.Name()
		}
		b, _ := json.Marshal(names)
		return b, JSONArrayMimetype, nil
	}
	b, err := fs.ReadFile(RootFS, fsPath)
	if err != nil {
		return nil, "", fsPathError("open", base, name, err)
	}
	mt := mimeFromExt(p)
	if mt == "" {
		mt = TextMimetype
	}
	return b, mt, nil
}

func readEnv(u *url.URL) ([]byte, string, error) {
	n := u.Opaque
	if n == "" {
		n = strings.TrimLeft(u.Path, "/")
	}
	v, ok := os.LookupEnv(n)
	if !ok {
		return nil, "", fsPathError("stat", "env:///", n, fs.ErrNotExist)
	}
	return []byte(v), TextMimetype, nil
}

func (r *Registry) readStdin(u *url.URL) ([]byte, string, error) {
	r.mu.Lock()
	if !r.stdinRead {
		r.stdinRead = true
		if r.stdin != nil {
			b, err := io.ReadAll(r.stdin)
			if err != nil {
				r.mu.Unlock()
				return nil, "", err
			}
			r.stdinData = b
		}
	}
	b := r.stdinData
	r.mu.Unlock()
	p := u.Path
	if p == "" {
		p = u.Opaque
	}
	mt := mimeFromExt(p)
	if mt == "" {
		mt = TextMimetype
	}
	return b, mt, nil
}

var httpClient = &http.Client{Timeout: 30 * time.Second}

func readHTTP(ctx context.Context, u *url.URL, header http.Header) ([]byte, string, error) {
	base := *u
	dir, name := path.Split(u.Path)
	base.Path = dir
	base.RawQuery = ""
	base.Fragment = ""
	baseStr := base.String()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, "", err
	}
	for k, v := range header {
		for _, vv := range v {
			req.Header.Add(k, vv)
		}
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		var ue *url.Error
		if errors.As(err, &ue) {
			err = fmt.Errorf("Head %q: %w", ue.URL, ue.Err)
		}
		return nil, "", fsPathError("stat", baseStr, name, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, "", fsPathError("stat", baseStr, name, fmt.Errorf("http HEAD failed with status %d", resp.StatusCode))
	}
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, "", err
	}
	mt := resp.Header.Get("Content-Type")
	if mt == "" {
		mt = mimeFromExt(u.Path)
	}
	if mt == "" {
		mt = TextMimetype
	}
	return b, mt, nil
}

func readUnsupported(u *url.URL) ([]byte, string, error) {
	return nil, "", fmt.Errorf("no filesystem registered for scheme %q", u.Scheme)
}

func (r *Registry) readMerge(ctx context.Context, u *url.URL) ([]byte, string, error) {
	opaque := u.Opaque
	if opaque == "" {
		opaque = strings.TrimPrefix(u.Path, "/")
	}
	parts := strings.Split(opaque, "|")
	if len(parts) < 2 {
		return nil, "", fsPathError("open", "merge:///", opaque, fmt.Errorf("open %s: need at least 2 datasources to merge", opaque))
	}
	maps := make([]map[string]any, len(parts))
	for i, part := range parts {
		var (
			b   []byte
			mt  string
			err error
		)
		if src, ok := r.Lookup(part); ok {
			b, mt, err = r.readURL(ctx, src.URL, src.Header, src.URL.Scheme == "" && !src.URL.IsAbs())
		} else {
			pu, perr := config.ParseSourceURL(part)
			if perr != nil {
				return nil, "", perr
			}
			b, mt, err = r.readURL(ctx, pu, nil, pu.Scheme == "" && !pu.IsAbs())
		}
		if err != nil {
			var pe *fs.PathError
			if errors.As(err, &pe) {
				err = pe
			}
			return nil, "", fsPathError("open", "merge:///", opaque, fmt.Errorf("open %s: opening merge part %q: %w", opaque, part, err))
		}
		v, err := Parse(b, mt)
		if err != nil {
			return nil, "", err
		}
		m, ok := v.(map[string]any)
		if !ok {
			return nil, "", fsPathError("stat", "merge:///", opaque,
				fmt.Errorf("read: readSubFile: parsing map with content type %s: unexpected data type '%T' for datasource (type %s); merge: can only merge maps", mt, v, mt))
		}
		maps[i] = m
	}
	merged := data.MergeMaps(maps[0], maps[1:]...)
	s, err := data.ToYAML(merged)
	if err != nil {
		return nil, "", err
	}
	return []byte(s), YAMLMimetype, nil
}

// Parse the data according to its MIME type
func Parse(b []byte, mimeType string) (any, error) {
	mt, _, err := mime.ParseMediaType(mimeType)
	if err != nil {
		mt = mimeType
	}
	s := string(b)
	switch mt {
	case JSONMimetype:
		obj, err := data.JSON(s)
		if err != nil {
			arr, aerr := data.JSONArray(s)
			if aerr != nil {
				return nil, aerr
			}
			return arr, nil
		}
		return obj, nil
	case JSONArrayMimetype:
		return data.JSONArray(s)
	case YAMLMimetype, "application/x-yaml":
		obj, err := data.YAML(s)
		if err != nil {
			arr, aerr := data.YAMLArray(s)
			if aerr != nil {
				return nil, aerr
			}
			return arr, nil
		}
		return obj, nil
	case CSVMimetype:
		return data.CSV(s)
	case TOMLMimetype:
		return data.TOML(s)
	case EnvMimetype:
		return data.DotEnv(s)
	case TextMimetype:
		return s, nil
	case CUEMimetype:
		return data.CUE(s)
	}
	return nil, fmt.Errorf("data of type %q not yet supported", mimeType)
}

// ReadAndParse reads and parses the datasource
func (r *Registry) ReadAndParse(ctx context.Context, alias string, args ...string) (any, error) {
	b, mt, err := r.Read(ctx, alias, args...)
	if err != nil {
		return nil, err
	}
	return Parse(b, mt)
}

// Include reads the raw content of a datasource
func (r *Registry) Include(ctx context.Context, alias string, args ...string) (string, error) {
	b, _, err := r.Read(ctx, alias, args...)
	if err != nil {
		return "", err
	}
	return string(bytes.Clone(b)), nil
}
