		}
		fsPath = ToFSPath(name)
	} else {
		fsPath = ToFSPath(p)
	}
	isDirURL := strings.HasSuffix(p, "/")

	fi, err := fs.Stat(RootFS, fsPath)
	if err != nil {
		if isDirURL {
			name = strings.TrimSuffix(name, "/")
		}
		return nil, "", fsPathError("open", base, name, err)
	}
	if fi.IsDir() {
		entries, err := fs.ReadDir(RootFS, fsPath)
		if err != nil {
			return nil, "", fsPathError("open", base, name, err)
		}
		names := make([]string, len(entries))
		for i, e := range entries {
			names[i] = e.Name()
		}
		b, _ := json.Marshal(names)
		return b, JSONArrayMimetype, nil
	}
	b, err := fs.ReadFile(RootFS, fsPath)
	if err != nil {
		return nil, "", fsPathError("open", base, name, err)
	}
	mt := mimeFromExt(p)
	if mt == "" {
		mt = TextMimetype
	}
	return b, mt, nil
}

