package data

import (
	"bytes"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"unicode"
)

// DotEnv parses a .env-format document into a map
func DotEnv(in string) (map[string]any, error) {
	out := map[string]string{}
	if err := parseEnvBytes([]byte(in), out); err != nil {
		return nil, err
	}
	res := make(map[string]any, len(out))
	for k, v := range out {
		res[k] = v
	}
	return res, nil
}

func envIsSpace(r rune) bool {
	switch r {
	case '\t', '\v', '\f', '\r', ' ', 0x85, 0xA0:
		return true
	}
	return false
}

func parseEnvBytes(src []byte, out map[string]string) error {
	src = bytes.ReplaceAll(src, []byte("\r\n"), []byte("\n"))
	cutset := src
	for {
		cutset = envStatementStart(cutset)
		if cutset == nil {
			break
		}
		key, left, err := envKeyName(cutset)
		if err != nil {
			return err
		}
		value, left, err := envValue(left, out)
		if err != nil {
			return err
		}
		out[key] = value
		cutset = left
	}
	return nil
}

func envStatementStart(src []byte) []byte {
	pos := bytes.IndexFunc(src, func(r rune) bool { return !unicode.IsSpace(r) })
	if pos == -1 {
		return nil
	}
	src = src[pos:]
	if src[0] != '#' {
		return src
	}
	pos = bytes.IndexByte(src, '\n')
	if pos == -1 {
		return nil
	}
	return envStatementStart(src[pos:])
}

func envKeyName(src []byte) (key string, cutset []byte, err error) {
	src = bytes.TrimLeftFunc(src, envIsSpace)
	if bytes.HasPrefix(src, []byte("export")) {
		trimmed := bytes.TrimPrefix(src, []byte("export"))
		if bytes.IndexFunc(trimmed, envIsSpace) == 0 {
			src = bytes.TrimLeftFunc(trimmed, envIsSpace)
		}
	}
	offset := 0
loop:
	for i, char := range src {
		rchar := rune(char)
		if envIsSpace(rchar) {
			continue
		}
		switch char {
		case '=', ':':
			key = string(src[0:i])
			offset = i + 1
			break loop
		case '_':
		default:
			if unicode.IsLetter(rchar) || unicode.IsNumber(rchar) || rchar == '.' {
				continue
			}
			return "", nil, fmt.Errorf(`unexpected character %q in variable name near %q`, string(char), string(src))
		}
	}
	if len(src) == 0 {
