package data

// MergeMaps merges srcs into a copy of dst - values in dst take precedence,
// then sources in left-to-right order. Nested maps are merged recursively.
func MergeMaps(dst map[string]any, srcs ...map[string]any) map[string]any {
	out := copyMap(dst)
	for _, src := range srcs {
		out = mergeInto(out, src)
	}
	return out
}

func copyMap(m map[string]any) map[string]any {
	out := make(map[string]any, len(m))
	for k, v := range m {
		if mm, ok := v.(map[string]any); ok {
			out[k] = copyMap(mm)
		} else {
			out[k] = v
		}
	}
	return out
}

// mergeInto merges src into dst, without overriding existing values in dst
func mergeInto(dst, src map[string]any) map[string]any {
	for k, sv := range src {
		dv, ok := dst[k]
		if !ok {
			if mm, ok := sv.(map[string]any); ok {
				dst[k] = copyMap(mm)
			} else {
				dst[k] = sv
			}
			continue
		}
		dm, dok := dv.(map[string]any)
		sm, sok := sv.(map[string]any)
		if dok && sok {
			dst[k] = mergeInto(dm, sm)
		}
	}
	return dst
}
