			depth = int(dv.Uint())
		default:
			return nil, fmt.Errorf("wrong depth type: must be int, got %T (%+v)", args[0], args[0])
		}
	}
	l, err := interfaceSlice(list)
	if err != nil {
		return nil, err
	}
	return flatten(l, depth), nil
}

func flatten(list []any, depth int) []any {
	out := make([]any, 0, len(list))
	for _, v := range list {
		s := reflect.ValueOf(v)
		if depth != 0 && (s.Kind() == reflect.Slice || s.Kind() == reflect.Array) {
			sub, _ := interfaceSlice(v)
			out = append(out, flatten(sub, depth-1)...)
			continue
		}
		out = append(out, v)
	}
	return out
}

func pickOmitArgs(args ...any) (map[string]any, []string, error) {
	if len(args) <= 1 {
		return nil, nil, fmt.Errorf("wrong number of args: wanted 2 or more, got %d", len(args))
	}
	m, ok := args[len(args)-1].(map[string]any)
	if !ok {
		return nil, nil, fmt.Errorf("wrong map type: must be map[string]any, got %T", args[len(args)-1])
	}
	keys := []string{}
	for _, a := range args[:len(args)-1] {
		switch v := a.(type) {
		case string:
			keys = append(keys, v)
		case []string:
			keys = append(keys, v...)
		case []any:
			for _, k := range v {
				ks, ok := k.(string)
				if !ok {
					return nil, nil, fmt.Errorf("wrong key type: must be string, got %T (%+v)", k, k)
				}
				keys = append(keys, ks)
			}
		default:
			return nil, nil, fmt.Errorf("wrong key type: must be string, got %T (%+v)", a, a)
		}
	}
	return m, keys, nil
}

// Pick -
func (CollFuncs) Pick(args ...any) (map[string]any, error) {
	m, keys, err := pickOmitArgs(args...)
	if err != nil {
		return nil, err
	}
	out := map[string]any{}
	for _, k := range keys {
		if v, ok := m[k]; ok {
			out[k] = v
		}
	}
	return out, nil
}

// Omit -
func (CollFuncs) Omit(args ...any) (map[string]any, error) {
	m, keys, err := pickOmitArgs(args...)
	if err != nil {
		return nil, err
	}
	out := map[string]any{}
	for k, v := range m {
		out[k] = v
	}
	for _, k := range keys {
		delete(out, k)
	}
	return out, nil
}

// Set -
func (CollFuncs) Set(key string, value any, m map[string]any) (map[string]any, error) {
	m[key] = value
	return m, nil
}

// Unset -
func (CollFuncs) Unset(key string, m map[string]any) (map[string]any, error) {
	delete(m, key)
	return m, nil
}

// Index -
func (CollFuncs) Index(args ...any) (any, error) {
	if len(args) < 2 {
		return nil, fmt.Errorf("wrong number of args: wanted at least 2, got %d", len(args))
	}
	item := args[len(args)-1]
	indexes := args[:len(args)-1]
	return collIndex(item, indexes...)
}
