// Base64Funcs - base64 functions
type Base64Funcs struct {
	ctx context.Context
}

// CreateBase64Funcs -
func CreateBase64Funcs(ctx context.Context) map[string]any {
	ns := &Base64Funcs{ctx}
	return map[string]any{"base64": func() any { return ns }}
}

// Encode -
func (Base64Funcs) Encode(in any) (string, error) {
	return base64.StdEncoding.EncodeToString(toBytes(in)), nil
}

// Decode -
func (f Base64Funcs) Decode(in any) (string, error) {
	b, err := f.DecodeBytes(in)
	return string(b), err
}

// DecodeBytes -
func (Base64Funcs) DecodeBytes(in any) ([]byte, error) {
	s := conv.ToString(in)
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		b, err = base64.URLEncoding.DecodeString(s)
		if err != nil {
			return nil, err
		}
	}
	return b, nil
}

func toBytes(in any) []byte {
	if in == nil {
		return []byte{}
	}
	if s, ok := in.([]byte); ok {
		return s
	}
	if s, ok := in.(string); ok {
		return []byte(s)
	}
	return []byte(conv.ToString(in))
}
