	return err == nil
}

// IsDir -
func (FileFuncs) IsDir(path any) bool {
	i, err := fs.Stat(datasources.RootFS, fsPath(conv.ToString(path)))
	return err == nil && i.IsDir()
}

// ReadDir -
func (FileFuncs) ReadDir(path any) ([]string, error) {
	entries, err := fs.ReadDir(datasources.RootFS, fsPath(conv.ToString(path)))
	if err != nil {
		return nil, err
	}
	out := make([]string, len(entries))
	for i, e := range entries {
		out[i] = e.Name()
	}
	return out, nil
}

// Walk -
func (FileFuncs) Walk(path any) ([]string, error) {
	root := conv.ToString(path)
	files := []string{}
	base := fsPath(root)
	err := fs.WalkDir(datasources.RootFS, base, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel := strings.TrimPrefix(strings.TrimPrefix(p, base), "/")
		if rel == "" {
			files = append(files, root)
		} else {
			files = append(files, filepath.Join(root, rel))
		}
		return nil
	})
	return files, err
}

// Write -
func (FileFuncs) Write(path any, data any) (string, error) {
	var b []byte
	switch v := data.(type) {
	case []byte:
		b = v
	case string:
		b = []byte(v)
	default:
		b = []byte(conv.ToString(data))
	}
	fname := conv.ToString(path)
	if err := checkContained(fname); err != nil {
		return "", fmt.Errorf("failed to open %s: %w", fname, err)
	}
	dir := filepath.Dir(fname)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return "", fmt.Errorf("failed to make dirs for %s: %w", fname, err)
	}
	if err := os.WriteFile(fname, b, 0o644); err != nil {
		return "", fmt.Errorf("failed to write %s: %w", fname, err)
	}
	return "", nil
}

func checkContained(fname string) error {
	wd, err := os.Getwd()
	if err != nil {
		return err
	}
	abs := fname
	if !filepath.IsAbs(abs) {
		abs = filepath.Join(wd, fname)
	}
	rel, err := filepath.Rel(wd, abs)
	if err != nil {
		return err
	}
	if rel == ".." || strings.HasPrefix(rel, "../") {
		return fmt.Errorf("path %s not contained by working directory %s (rel: %s)", fname, wd, rel)
	}
	return nil
}
