	_, o := gotime.Now().Zone()
	return o
}

// Parse -
func (TimeFuncs) Parse(layout string, value any) (gotime.Time, error) {
	return gotime.Parse(layout, conv.ToString(value))
}

// ParseLocal -
func (TimeFuncs) ParseLocal(layout string, value any) (gotime.Time, error) {
	tz := os.Getenv("TZ")
	if tz == "" {
		return gotime.ParseInLocation(layout, conv.ToString(value), gotime.Local)
	}
	loc, err := gotime.LoadLocation(tz)
	if err != nil {
		return gotime.Time{}, err
	}
	return gotime.ParseInLocation(layout, conv.ToString(value), loc)
}

// ParseInLocation -
func (TimeFuncs) ParseInLocation(layout, location string, value any) (gotime.Time, error) {
	loc, err := gotime.LoadLocation(location)
	if err != nil {
		return gotime.Time{}, err
	}
	return gotime.ParseInLocation(layout, conv.ToString(value), loc)
}

// Now -
func (TimeFuncs) Now() gotime.Time {
	return gotime.Now()
}

// Unix -
func (TimeFuncs) Unix(in any) (gotime.Time, error) {
	sec, nsec, err := parseNum(in)
	if err != nil {
		return gotime.Time{}, err
	}
	return gotime.Unix(sec, nsec), nil
}

