	return durationOf(n, gotime.Minute)
}

// Hour -
func (TimeFuncs) Hour(n any) (gotime.Duration, error) {
	return durationOf(n, gotime.Hour)
}

func durationOf(n any, unit gotime.Duration) (gotime.Duration, error) {
	i, err := conv.ToInt64(n)
	if err != nil {
		return 0, fmt.Errorf("expected a number: %w", err)
	}
	return gotime.Duration(i) * unit, nil
}

// ParseDuration -
func (TimeFuncs) ParseDuration(n any) (gotime.Duration, error) {
	return gotime.ParseDuration(conv.ToString(n))
}

// Since -
func (TimeFuncs) Since(n gotime.Time) gotime.Duration {
	return gotime.Since(n)
}

// Until -
func (TimeFuncs) Until(n gotime.Time) gotime.Duration {
	return gotime.Until(n)
}

func parseNum(in any) (integral int64, fractional int64, err error) {
	if s, ok := in.(fmt.Stringer); ok {
		in = s.String()
	}
	if i, ok := in.(int); ok {
		return int64(i), 0, nil
	}
	if u, ok := in.(uint64); ok {
		return int64(u), 0, nil
	}
	if f, ok := in.(float64); ok {
		return 0, 0, fmt.Errorf("can not parse floating point number (%f) - use a string instead", f)
	}
	if in == nil {
		return 0, 0, nil
	}
	s, ok := in.(string)
	if !ok {
		return 0, 0, nil
	}
	parts := strings.Split(s, ".")
	if len(parts) > 2 {
		return 0, 0, fmt.Errorf("can not parse '%s' as a number - too many decimal points", s)
	}
	integral, err = strconv.ParseInt(parts[0], 0, 64)
	if err != nil {
		return 0, 0, err
	}
	if len(parts) == 2 {
		frac := (parts[1] + "000000000")[:9]
		fractional, err = strconv.ParseInt(frac, 0, 64)
		if err != nil {
			return 0, 0, err
		}
	}
	return integral, fractional, nil
}
