// RandomFuncs - random functions
type RandomFuncs struct {
	ctx context.Context
}

// CreateRandomFuncs -
func CreateRandomFuncs(ctx context.Context) map[string]any {
	ns := &RandomFuncs{ctx}
	return map[string]any{"random": func() any { return ns }}
}

const defaultRandChars = `[a-zA-Z0-9_.-]`

func randFromRange(count int, lower, upper rune) (string, error) {
	if count == 0 {
		return "", errors.New("count must be greater than 0")
	}
	chars := []rune{}
	for r := lower; r <= upper; r++ {
		if unicode.IsGraphic(r) {
			chars = append(chars, r)
		}
	}
	return randFromRunes(count, chars)
}

func randFromRunes(count int, chars []rune) (string, error) {
	if count == 0 {
		return "", errors.New("count must be greater than 0")
	}
	if len(chars) == 0 {
		return "", errors.New("no characters to choose from")
	}
	b := make([]rune, count)
	for i := range b {
		b[i] = chars[rand.IntN(len(chars))]
	}
	return string(b), nil
}

func randMatching(count int, re string) (string, error) {
	r, err := regexp.Compile(re)
	if err != nil {
		return "", err
	}
	chars := []rune{}
	for c := rune(0); c <= unicode.MaxRune; c++ {
		if c >= 0xD800 && c <= 0xDFFF {
			continue
		}
		if !unicode.IsGraphic(c) && !unicode.IsSpace(c) {
			if c > 0x10000 {
				// skip large non-graphic ranges quickly
				continue
			}
			continue
		}
		var buf [utf8.UTFMax]byte
		n := utf8.EncodeRune(buf[:], c)
		if r.Match(buf[:n]) {
			chars = append(chars, c)
		}
	}
	return randFromRunes(count, chars)
}

// ASCII -
func (RandomFuncs) ASCII(count any) (string, error) {
	n, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if n < 0 {
		_ = make([]rune, n)
	}
	return randFromRange(n, ' ', '~')
}

// Alpha -
func (RandomFuncs) Alpha(count any) (string, error) {
	n, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if n < 0 {
		_ = make([]rune, n)
	}
	return randMatchingFast(n, "[[:alpha:]]")
}

// AlphaNum -
func (RandomFuncs) AlphaNum(count any) (string, error) {
	n, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if n < 0 {
		_ = make([]rune, n)
	}
	return randMatchingFast(n, "[[:alnum:]]")
}

func randMatchingFast(n int, re string) (string, error) {
	r := regexp.MustCompile(re)
	chars := []rune{}
	for c := rune(0); c < 128; c++ {
		if r.MatchString(string(c)) {
			chars = append(chars, c)
		}
	}
	return randFromRunes(n, chars)
}

// String -
func (RandomFuncs) String(count any, args ...any) (string, error) {
	c, err := conv.ToInt(count)
	if err != nil {
		return "", fmt.Errorf("count must be an integer: %w", err)
	}
	if c < 0 {
		_ = make([]rune, c)
	}
	switch len(args) {
	case 0:
		return randMatchingFast(c, defaultRandChars)
	case 1:
		re := conv.ToString(args[0])
		if _, err := regexp.Compile(re); err != nil {
			return "", err
		}
		if c == 0 {
			return "", errors.New("count must be greater than 0")
		}
		return randMatching(c, re)
	case 2:
		lower, err := toCodePoint(args[0])
		if err != nil {
			return "", err
		}
		upper, err := toCodePoint(args[1])
		if err != nil {
			return "", err
		}
		return randFromRange(c, lower, upper)
	}
	return randMatchingFast(c, defaultRandChars)
}

func toCodePoint(r any) (rune, error) {
	if s, ok := r.(string); ok {
		if utf8.RuneCountInString(s) == 1 {
			ru, _ := utf8.DecodeRuneInString(s)
			return ru, nil
		}
		i, err := strconv.ParseInt(s, 0, 32)
		if err != nil {
			return 0, err
		}
		return rune(i), nil
	}
	i, err := conv.ToInt64(r)
	if err != nil {
		return 0, err
	}
	return rune(i), nil
}

// Item -
func (RandomFuncs) Item(items any) (any, error) {
	i, err := interfaceSlice(items)
	if err != nil {
		return nil, err
	}
	if len(i) == 0 {
		return nil, errors.New("expected a non-empty array or slice")
	}
	if len(i) == 1 {
		return i[0], nil
	}
	return i[rand.IntN(len(i))], nil
}

// Number -
func (RandomFuncs) Number(args ...any) (int64, error) {
	var nMin, nMax int64
	nMin, nMax = 0, 100
	var err error
	switch len(args) {
	case 0:
	case 1:
		nMax, err = conv.ToInt64(args[0])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	case 2:
		nMin, err = conv.ToInt64(args[0])
		if err != nil {
			return 0, fmt.Errorf("min must be a number: %w", err)
		}
		nMax, err = conv.ToInt64(args[1])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	}
	if nMin > nMax {
		return 0, fmt.Errorf("min must not be greater than max (was %d, %d)", nMin, nMax)
	}
	if nMax-nMin >= math.MaxInt64 || nMax-nMin < 0 {
		return 0, errors.New("spread between min and max too high - must not be greater than 63-bit maximum")
	}
	return rand.Int64N(nMax-nMin+1) + nMin, nil
}

// Float -
func (RandomFuncs) Float(args ...any) (float64, error) {
	var nMin, nMax float64
	nMin, nMax = 0, 1.0
	var err error
	switch len(args) {
	case 0:
	case 1:
		nMax, err = conv.ToFloat64(args[0])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	case 2:
		nMin, err = conv.ToFloat64(args[0])
		if err != nil {
			return 0, fmt.Errorf("min must be a number: %w", err)
		}
		nMax, err = conv.ToFloat64(args[1])
		if err != nil {
			return 0, fmt.Errorf("max must be a number: %w", err)
		}
	}
	return nMin + rand.Float64()*(nMax-nMin), nil
}
