)

// CryptoFuncs - crypto functions
type CryptoFuncs struct {
	ctx context.Context
}

// CreateCryptoFuncs -
func CreateCryptoFuncs(ctx context.Context) map[string]any {
	ns := &CryptoFuncs{ctx}
	return map[string]any{"crypto": func() any { return ns }}
}

var hashFuncs = map[string]func() hash.Hash{}

func init() {
	add := func(f func() hash.Hash, names ...string) {
		for _, n := range names {
			hashFuncs[n] = f
		}
	}
	add(sha1.New, "SHA1", "SHA-1")
	add(sha256.New224, "SHA224", "SHA-224")
	add(sha256.New, "SHA256", "SHA-256")
	add(sha512.New384, "SHA384", "SHA-384")
	add(sha512.New, "SHA512", "SHA-512")
	add(sha512.New512_224, "SHA512_224", "SHA512/224", "SHA-512/224")
	add(sha512.New512_256, "SHA512_256", "SHA512/256", "SHA-512/256")
}

// PBKDF2 -
func (CryptoFuncs) PBKDF2(password, salt, iter, keylen any, hashFunc ...string) (string, error) {
	h := sha1.New
	if len(hashFunc) > 0 {
		f, ok := hashFuncs[hashFunc[0]]
		if !ok {
			return "", fmt.Errorf("no such hash %s", hashFunc[0])
		}
		h = f
	}
	pw := toBytes(password)
	s := toBytes(salt)
	i, err := conv.ToInt(iter)
	if err != nil {
		return "", fmt.Errorf("iter must be an integer: %w", err)
	}
	kl, err := conv.ToInt(keylen)
	if err != nil {
		return "", fmt.Errorf("keylen must be an integer: %w", err)
	}
	k := pbkdf2.Key(pw, s, i, kl, h)
	return fmt.Sprintf("%x", k), nil
}

// WPAPSK -
func (f CryptoFuncs) WPAPSK(ssid, password any) (string, error) {
	return f.PBKDF2(password, ssid, 4096, 32)
}

func hashHex(h hash.Hash, in any) string {
	h.Write(toBytes(in))
	return fmt.Sprintf("%02x", h.Sum(nil))
}

func hashBytes(h hash.Hash, in any) []byte {
	h.Write(toBytes(in))
	return h.Sum(nil)
}

// SHA1 -
