func (f *CryptoFuncs) DecryptAESBytes(key string, args ...any) ([]byte, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return nil, err
	}
	k, in, err := aesArgs(key, args...)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(k)
	if err != nil {
		return nil, err
	}
	bs := block.BlockSize()
	iv := in[:bs]
	in = in[bs:]
	if len(in)%bs != 0 {
		return nil, errors.New("ciphertext is not a multiple of the block size")
	}
	out := make([]byte, len(in))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(out, in)
	padding := int(out[len(out)-1])
	if padding > len(out) || padding > bs || padding == 0 {
		return nil, errors.New("invalid padding")
	}
	return out[:len(out)-padding], nil
}

