		return "", fmt.Errorf("failed to marshal PKIX public key: %w", err)
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: b})), nil
}

// Ed25519GenerateKey -
func (f *CryptoFuncs) Ed25519GenerateKey() (string, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return "", err
	}
	_, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return "", fmt.Errorf("generateKey: %w", err)
	}
	return ed25519PEM(priv)
}

func ed25519PEM(priv ed25519.PrivateKey) (string, error) {
	der, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil {
		return "", fmt.Errorf("pkcs8: failed to marshal private key: %w", err)
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der})), nil
}

// Ed25519GenerateKeyFromSeed -
func (f *CryptoFuncs) Ed25519GenerateKeyFromSeed(encoding, seed string) (string, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return "", err
	}
	var seedB []byte
	var err error
	switch encoding {
	case "base64":
		seedB, err = base64.StdEncoding.DecodeString(seed)
	case "hex":
		seedB, err = hex.DecodeString(seed)
	default:
		return "", fmt.Errorf("invalid encoding given: %s - only 'hex' or 'base64' are valid options", encoding)
	}
	if err != nil {
		return "", fmt.Errorf("could not decode given seed: %w", err)
	}
	if len(seedB) != ed25519.SeedSize {
		return "", fmt.Errorf("generateKeyFromSeed: incorrect seed size - given: %d wanted %d", len(seedB), ed25519.SeedSize)
	}
	return ed25519PEM(ed25519.NewKeyFromSeed(seedB))
}

// Ed25519DerivePublicKey -
func (f *CryptoFuncs) Ed25519DerivePublicKey(privateKey string) (string, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return "", err
	}
	block, _ := pem.Decode([]byte(privateKey))
	if block == nil {
		return "", errors.New("ed25519DecodeFromPEM: could not decode private key: decode: failed to read key")
	}
	k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return "", fmt.Errorf("ed25519DecodeFromPEM: could not decode private key: %w", err)
	}
	priv, ok := k.(ed25519.PrivateKey)
	if !ok {
		return "", errors.New("ed25519DecodeFromPEM: could not decode private key: not an ed25519 key")
	}
	b, err := x509.MarshalPKIXPublicKey(priv.Public())
	if err != nil {
		return "", fmt.Errorf("failed to marshal PKIX public key: %w", err)
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: b})), nil
}

func aesArgs(key string, args ...any) ([]byte, []byte, error) {
	keyBits := 256
	var input []byte
	switch len(args) {
	case 1:
		input = toBytes(args[0])
	case 2:
		var err error
		keyBits, err = conv.ToInt(args[0])
		if err != nil {
			return nil, nil, fmt.Errorf("keyBits must be an integer: %w", err)
		}
		input = toBytes(args[1])
	default:
		return nil, nil, fmt.Errorf("wrong number of args: want 2 or 3, got %d", len(args))
	}
	k := make([]byte, keyBits/8)
	copy(k, key)
	return k, input, nil
}

// EncryptAES -
func (f *CryptoFuncs) EncryptAES(key string, args ...any) ([]byte, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return nil, err
	}
	k, in, err := aesArgs(key, args...)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(k)
	if err != nil {
		return nil, err
	}
	bs := block.BlockSize()
	padding := bs - len(in)%bs
	in = append(append([]byte{}, in...), bytes.Repeat([]byte{byte(padding)}, padding)...)
	ciphertext := make([]byte, bs+len(in))
	iv := ciphertext[:bs]
	if _, err := rand.Read(iv); err != nil {
		return nil, err
	}
	cipher.NewCBCEncrypter(block, iv).CryptBlocks(ciphertext[bs:], in)
	return ciphertext, nil
}

// DecryptAES -
func (f *CryptoFuncs) DecryptAES(key string, args ...any) (string, error) {
	out, err := f.DecryptAESBytes(key, args...)
	return string(out), err
}

// DecryptAESBytes -
func (f *CryptoFuncs) DecryptAESBytes(key string, args ...any) ([]byte, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return nil, err
	}
	k, in, err := aesArgs(key, args...)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(k)
	if err != nil {
		return nil, err
	}
	bs := block.BlockSize()
	iv := in[:bs]
	in = in[bs:]
	if len(in)%bs != 0 {
		return nil, errors.New("ciphertext is not a multiple of the block size")
	}
	out := make([]byte, len(in))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(out, in)
	padding := int(out[len(out)-1])
	if padding > len(out) || padding > bs || padding == 0 {
		return nil, errors.New("invalid padding")
	}
	return out[:len(out)-padding], nil
}

