// Package gitignore implements .gitignore-style pattern matching
package gitignore

import (
	"bufio"
	"io"
	"path/filepath"
	"strings"
)

type result int

const (
	noMatch result = iota
	exclude
	include
)

// Pattern is a single gitignore pattern
type Pattern struct {
	domain    []string
	pattern   []string
	inclusion bool
	dirOnly   bool
	isGlob    bool
}

// ParsePattern parses a gitignore pattern relative to the given domain
func ParsePattern(p string, domain []string) *Pattern {
	res := &Pattern{domain: domain}
	if strings.HasPrefix(p, "!") {
		res.inclusion = true
		p = p[1:]
	}
	if !strings.HasSuffix(p, "\\ ") {
		p = strings.TrimRight(p, " ")
	}
	if strings.HasSuffix(p, "/") {
		res.dirOnly = true
		p = p[:len(p)-1]
	}
	if strings.Contains(p, "/") {
		res.isGlob = true
	}
	res.pattern = strings.Split(p, "/")
	return res
}

func (p *Pattern) match(path []string, isDir bool) result {
	if len(path) <= len(p.domain) {
		return noMatch
	}
	for i, e := range p.domain {
		if path[i] != e {
			return noMatch
		}
	}
	path = path[len(p.domain):]
	if p.isGlob && !p.globMatch(path, isDir) {
		return noMatch
	} else if !p.isGlob && !p.simpleNameMatch(path, isDir) {
		return noMatch
	}
	if p.inclusion {
		return include
	}
	return exclude
}

func (p *Pattern) simpleNameMatch(path []string, isDir bool) bool {
	for i, name := range path {
		match, err := filepath.Match(p.pattern[0], name)
		if err != nil {
			return false
		}
		if !match {
			continue
		}
		if p.dirOnly && !isDir && i == len(path)-1 {
			return false
		}
		return true
	}
	return false
}

func (p *Pattern) globMatch(path []string, isDir bool) bool {
	matched := false
	canTraverse := false
	for i, pattern := range p.pattern {
		if pattern == "" {
			canTraverse = false
			continue
		}
		if pattern == "**" {
			if i == len(p.pattern)-1 {
				break
			}
			canTraverse = true
			continue
		}
		if strings.Contains(pattern, "**") {
			return false
		}
		if len(path) == 0 {
			return false
		}
		if canTraverse {
			canTraverse = false
			for len(path) > 0 {
				e := path[0]
				path = path[1:]
				match, err := filepath.Match(pattern, e)
				if err != nil {
					return false
				}
				if match {
					matched = true
					break
				} else if len(path) == 0 {
					matched = false
				}
			}
		} else {
			match, err := filepath.Match(pattern, path[0])
			if err != nil || !match {
				return false
			}
			matched = true
			path = path[1:]
		}
	}
	if matched && p.dirOnly && !isDir && len(path) == 0 {
		matched = false
	}
	return matched
}

// Matcher matches paths against a list of patterns
type Matcher struct {
	patterns []*Pattern
}

// NewMatcher -
func NewMatcher(ps []*Pattern) *Matcher {
	return &Matcher{patterns: ps}
}

// Add patterns
func (m *Matcher) Add(ps ...*Pattern) {
	m.patterns = append(m.patterns, ps...)
}

// Match reports whether the path is excluded
func (m *Matcher) Match(path []string, isDir bool) bool {
	for i := len(m.patterns) - 1; i >= 0; i-- {
		if r := m.patterns[i].match(path, isDir); r > noMatch {
			return r == exclude
		}
	}
	return false
}

// ReadPatterns reads patterns from a gitignore-format file
func ReadPatterns(r io.Reader, domain []string) []*Pattern {
	ps := []*Pattern{}
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		s := scanner.Text()
		if !strings.HasPrefix(s, "#") && len(strings.TrimSpace(s)) > 0 {
			ps = append(ps, ParsePattern(s, domain))
		}
	}
	return ps
}
