// Package gomplate is a template renderer which supports a number of datasources,
// and includes hundreds of built-in functions.
package gomplate

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"io/fs"
	"os"

	"github.com/hairyhenderson/gomplate/v4/internal/config"
	"github.com/hairyhenderson/gomplate/v4/internal/datasources"
)

var pipeBuffers = map[*config.Config]*bytes.Buffer{}

// PipeBuffer returns the buffer used for --exec-pipe output
func PipeBuffer(cfg *config.Config) io.Reader {
	if b, ok := pipeBuffers[cfg]; ok {
		return b
	}
	return &bytes.Buffer{}
}

// OpenFile opens a file in the root filesystem
func OpenFile(name string) (fs.File, error) {
	return datasources.RootFS.Open(datasources.ToFSPath(name))
}

// RunTemplates - run all gomplate templates specified by the given configuration
func RunTemplates(ctx context.Context, cfg *config.Config) (rendered int, errCount int, err error) {
	cfg.ApplyDefaults()
	if err := cfg.Validate(); err != nil {
		return 0, 0, fmt.Errorf("failed to validate config: %w\n%s", err, cfg)
	}

	if cfg.ExecPipe {
		buf := &bytes.Buffer{}
		pipeBuffers[cfg] = buf
		cfg.Stdout = buf
	}

	r := newRenderer(cfg)
	if err := r.loadContext(ctx); err != nil {
		return 0, 0, err
