	return nil
}

func missingKeyOption(mk string) string {
	switch mk {
	case "zero":
		return "missingkey=zero"
	case "default", "invalid":
		return "missingkey=default"
	}
	return "missingkey=error"
}

func (r *renderer) parseTemplate(ctx context.Context, name, text, tpath string) (*template.Template, error) {
	t := template.New(name)
	ns := tmpl.New(t, r.tctx, tpath)
	fm := template.FuncMap{}
	for k, v := range r.funcs {
		fm[k] = v
	}
	fm["tmpl"] = func() any { return ns }
	fm["tpl"] = ns.Inline
	t.Option(missingKeyOption(r.cfg.MissingKey))
	t.Funcs(fm)
	t.Delims(r.cfg.LDelim, r.cfg.RDelim)

	if err := r.parseNestedTemplates(ctx, t); err != nil {
		return nil, fmt.Errorf("parse nested templates: %w", err)
	}

	return t.Parse(text)
}

func (r *renderer) parseNestedTemplates(ctx context.Context, t *template.Template) error {
	aliases := make([]string, 0, len(r.cfg.Templates))
	for a := range r.cfg.Templates {
		aliases = append(aliases, a)
	}
	sort.Strings(aliases)
	for _, alias := range aliases {
		ds := r.cfg.Templates[alias]
		u := ds.URL
		p := u.Path
		if u.Opaque != "" {
			p = u.Opaque
		}
		fi, err := os.Stat(p)
		if err != nil {
			return fmt.Errorf("stat %q: %w", p, err)
		}
		if fi.IsDir() {
			entries, err := fs.ReadDir(datasources.RootFS, datasources.ToFSPath(p))
			if err != nil {
				return err
			}
			for _, e := range entries {
				if e.IsDir() {
					continue
				}
				name := path.Join(strings.TrimSuffix(alias, "/"), e.Name())
				b, err := os.ReadFile(filepath.Join(p, e.Name()))
				if err != nil {
					return err
				}
				if _, err := t.New(name).Parse(string(b)); err != nil {
					return fmt.Errorf("parse nested template %q: %w", filepath.Join(p, e.Name()), err)
				}
			}
			continue
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		if _, err := t.New(alias).Parse(string(b)); err != nil {
			return fmt.Errorf("parse nested template %q: %w", u.String(), err)
		}
	}
	return nil
}

func (r *renderer) renderTemplates(ctx context.Context, tmpls []*gtemplate) (int, error) {
	n := 0
	for _, t := range tmpls {
		if err := r.render(ctx, t); err != nil {
			return n, fmt.Errorf("renderTemplate: %w", err)
		}
		n++
	}
	return n, nil
}

func (r *renderer) render(ctx context.Context, t *gtemplate) error {
	defer t.target.Close()
	if t.copyOnly {
		_, err := t.target.Write([]byte(t.text))
		return err
	}
	tp := t.name
	tm, err := r.parseTemplate(ctx, t.name, t.text, tp)
	if err != nil {
		return fmt.Errorf("parse template %s: %w", t.name, err)
	}
	if err := tm.Execute(t.target, r.tctx); err != nil {
		return fmt.Errorf("failed to render template %s: %w", t.name, err)
	}
	return nil
}
