package semver

import (
	"fmt"
	"regexp"
	"strings"
)

// Constraints is one or more constraint that a semantic version can be
// checked against.
type Constraints struct {
	constraints [][]*constraint
}

type constraint struct {
	con      *Version
	orig     string
	origfunc string
	minorDirty bool
	patchDirty bool
	dirty      bool
}

const cvRegex string = `v?([0-9|x|X|\*]+)(\.[0-9|x|X|\*]+)?(\.[0-9|x|X|\*]+)?` +
	`(-([0-9A-Za-z\-]+(\.[0-9A-Za-z\-]+)*))?` +
	`(\+([0-9A-Za-z\-]+(\.[0-9A-Za-z\-]+)*))?`

var (
	opsList              = []string{"", "=", "!=", ">", "<", ">=", "=>", "<=", "=<", "~", "~>", "^"}
	constraintRegex      *regexp.Regexp
	constraintRangeRegex *regexp.Regexp
	findConstraintRegex  *regexp.Regexp
	validConstraintRegex *regexp.Regexp
)

func init() {
	ops := make([]string, 0, len(opsList))
	// longest first so regex alternation prefers them
	order := []string{">=", "=>", "<=", "=<", "!=", "~>", "=", ">", "<", "~", "^", ""}
	for _, k := range order {
		ops = append(ops, regexp.QuoteMeta(k))
	}
	opsRe := strings.Join(ops, "|")
	constraintRegex = regexp.MustCompile(fmt.Sprintf(`^\s*(%s)\s*(%s)\s*$`, opsRe, cvRegex))
	constraintRangeRegex = regexp.MustCompile(fmt.Sprintf(`\s*(%s)\s+-\s+(%s)\s*`, cvRegex, cvRegex))
	findConstraintRegex = regexp.MustCompile(fmt.Sprintf(`(%s)\s*(%s)`, opsRe, cvRegex))
	validConstraintRegex = regexp.MustCompile(fmt.Sprintf(`^(\s*(%s)\s*(%s)\s*)((?:\s+|,\s*)(%s)\s*(%s)\s*)*$`, opsRe, cvRegex, opsRe, cvRegex))
}

// NewConstraint returns a Constraints instance that a Version instance can
// be checked against.
func NewConstraint(c string) (*Constraints, error) {
	c = rewriteRange(c)
	ors := strings.Split(c, "||")
	or := make([][]*constraint, len(ors))
	for k, v := range ors {
		if !validConstraintRegex.MatchString(v) {
			return nil, fmt.Errorf("improper constraint: %s", v)
		}
		cs := findConstraintRegex.FindAllString(v, -1)
		if cs == nil {
			cs = append(cs, v)
		}
		result := make([]*constraint, len(cs))
		for i, s := range cs {
			pc, err := parseConstraint(s)
			if err != nil {
				return nil, err
			}
			result[i] = pc
		}
		or[k] = result
	}
	return &Constraints{constraints: or}, nil
}

// Check tests if a version satisfies the constraints.
func (cs Constraints) Check(v *Version) bool {
	for _, o := range cs.constraints {
		joy := true
		for _, c := range o {
			if !c.check(v) {
				joy = false
				break
			}
		}
		if joy {
			return true
		}
	}
	return false
}

func rewriteRange(i string) string {
	m := constraintRangeRegex.FindAllStringSubmatch(i, -1)
	if m == nil {
		return i
	}
	o := i
	for _, v := range m {
		t := fmt.Sprintf(">= %s, <= %s ", v[1], v[11])
		o = strings.Replace(o, v[0], t, 1)
	}
	return o
}

func isX(s string) bool {
	switch s {
	case "x", "*", "X":
		return true
	}
	return false
}

func parseConstraint(c string) (*constraint, error) {
	if len(c) > 0 {
		m := constraintRegex.FindStringSubmatch(c)
		if m == nil {
			return nil, fmt.Errorf("improper constraint: %s", c)
		}
		cs := &constraint{orig: m[2], origfunc: m[1]}
		ver := m[2]
		minorDirty := false
		patchDirty := false
		dirty := false
		if isX(m[3]) || m[3] == "" {
			ver = fmt.Sprintf("0.0.0%s", m[6])
			dirty = true
		} else if isX(strings.TrimPrefix(m[4], ".")) || m[4] == "" {
			minorDirty = true
			dirty = true
			ver = fmt.Sprintf("%s.0.0%s", m[3], m[6])
		} else if isX(strings.TrimPrefix(m[5], ".")) || m[5] == "" {
			dirty = true
			patchDirty = true
			ver = fmt.Sprintf("%s%s.0%s", m[3], m[4], m[6])
		}
		con, err := NewVersion(ver)
		if err != nil {
			return nil, fmt.Errorf("improper constraint: %s", c)
		}
		cs.con = con
		cs.minorDirty = minorDirty
		cs.patchDirty = patchDirty
		cs.dirty = dirty
		return cs, nil
	}
	con, _ := NewVersion("0.0.0")
	return &constraint{con: con, orig: c, origfunc: "", dirty: true}, nil
}

func (c *constraint) check(v *Version) bool {
	switch c.origfunc {
	case "", "=":
		return constraintTildeOrEqual(v, c)
	case "!=":
		return constraintNotEqual(v, c)
	case ">":
		return constraintGreaterThan(v, c)
	case "<":
		return constraintLessThan(v, c)
	case ">=", "=>":
		return constraintGreaterThanEqual(v, c)
	case "<=", "=<":
		return constraintLessThanEqual(v, c)
	case "~", "~>":
		return constraintTilde(v, c)
	case "^":
		return constraintCaret(v, c)
	}
	return false
}

func constraintNotEqual(v *Version, c *constraint) bool {
	if c.dirty {
		if v.Prerelease() != "" && c.con.Prerelease() == "" {
			return false
		}
		if c.con.Major() != v.Major() {
			return true
		}
		if c.con.Minor() != v.Minor() && !c.minorDirty {
			return true
		} else if c.minorDirty {
			return false
		} else if c.con.Patch() != v.Patch() && !c.patchDirty {
			return true
		} else if c.patchDirty {
			if v.Prerelease() != "" || c.con.Prerelease() != "" {
				return comparePrerelease(v.Prerelease(), c.con.Prerelease()) != 0
			}
			return false
		}
	}
	eq := v.Equal(c.con)
	if eq {
		return false
	}
	return true
}

func constraintGreaterThan(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	if !c.dirty {
		return v.Compare(c.con) == 1
	}
	if v.Major() > c.con.Major() {
		return true
	} else if v.Major() < c.con.Major() {
		return false
	} else if c.minorDirty {
		return false
	} else if c.patchDirty {
		return v.Minor() > c.con.Minor()
	}
	return v.Compare(c.con) == 1
}

func constraintLessThan(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	return v.Compare(c.con) < 0
}

func constraintGreaterThanEqual(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	return v.Compare(c.con) >= 0
}

func constraintLessThanEqual(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	if !c.dirty {
		return v.Compare(c.con) <= 0
	}
	if v.Major() > c.con.Major() {
		return false
	} else if v.Major() == c.con.Major() && v.Minor() > c.con.Minor() && !c.minorDirty {
		return false
	}
	return true
}

func constraintTilde(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	if v.LessThan(c.con) {
		return false
	}
	if c.con.Major() == 0 && c.con.Minor() == 0 && c.con.Patch() == 0 && !c.minorDirty && !c.patchDirty {
		return true
	}
	if v.Major() != c.con.Major() {
		return false
	}
	if v.Minor() != c.con.Minor() && !c.minorDirty {
		return false
	}
	return true
}

func constraintTildeOrEqual(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	if c.dirty {
		return constraintTilde(v, c)
	}
	return v.Equal(c.con)
}

func constraintCaret(v *Version, c *constraint) bool {
	if v.Prerelease() != "" && c.con.Prerelease() == "" {
		return false
	}
	if v.LessThan(c.con) {
		return false
	}
	if c.con.Major() > 0 || c.minorDirty {
		return v.Major() == c.con.Major()
	} else if c.con.Minor() > 0 || c.patchDirty {
		return v.Major() == c.con.Major() && v.Minor() == c.con.Minor()
	}
	return v.Major() == c.con.Major() && v.Minor() == c.con.Minor() && v.Patch() == c.con.Patch()
}
