// Package netipx contains IP range helpers
package netipx

import (
	"errors"
	"fmt"
	"math/big"
	"net/netip"
	"strings"
)

// IPRange represents an inclusive range of IP addresses from the same
// address family.
type IPRange struct {
	from netip.Addr
	to   netip.Addr
}

// IPRangeFrom returns an IPRange from from to to.
func IPRangeFrom(from, to netip.Addr) IPRange {
	return IPRange{from: from, to: to}
}

// From returns the lower bound of r.
func (r IPRange) From() netip.Addr { return r.from }

// To returns the upper bound of r.
func (r IPRange) To() netip.Addr { return r.to }

// ParseIPRange parses a range out of two IPs separated by a hyphen.
func ParseIPRange(s string) (IPRange, error) {
	var r IPRange
	h := strings.IndexByte(s, '-')
	if h == -1 {
		return r, fmt.Errorf("no hyphen in range %q", s)
	}
	from, to := s[:h], s[h+1:]
	var err error
	r.from, err = netip.ParseAddr(from)
	if err != nil {
		return r, fmt.Errorf("invalid From IP %q in range %q", from, s)
	}
	r.from = r.from.WithZone("")
	r.to, err = netip.ParseAddr(to)
	if err != nil {
		return r, fmt.Errorf("invalid To IP %q in range %q", to, s)
	}
	r.to = r.to.WithZone("")
	if !r.IsValid() {
		return r, fmt.Errorf("range %v to %v not valid", r.from, r.to)
	}
	return r, nil
}

// IsValid reports whether r.From() and r.To() are both non-zero and
// obey the documented requirements.
func (r IPRange) IsValid() bool {
	return r.from.IsValid() &&
		r.from.BitLen() == r.to.BitLen() &&
		r.from.Zone() == r.to.Zone() &&
		!r.to.Less(r.from)
}

// String returns a string representation of the range.
func (r IPRange) String() string {
	if !r.IsValid() {
		return "invalid IPRange"
	}
	return r.from.String() + "-" + r.to.String()
}

// MarshalText implements the encoding.TextMarshaler interface
func (r IPRange) MarshalText() ([]byte, error) {
	if r.from == (netip.Addr{}) && r.to == (netip.Addr{}) {
		return []byte(""), nil
	}
	return []byte(r.String()), nil
}

// Contains reports whether the range includes addr.
func (r IPRange) Contains(addr netip.Addr) bool {
	return r.IsValid() && addr.Zone() == "" && r.from.Compare(addr) <= 0 && r.to.Compare(addr) >= 0
}

// Overlaps reports whether p and o overlap at all.
func (r IPRange) Overlaps(o IPRange) bool {
	return r.IsValid() && o.IsValid() && r.from.Compare(o.to) <= 0 && o.from.Compare(r.to) <= 0
}

// IsZero reports whether r is the zero value of the IPRange type.
func (r IPRange) IsZero() bool {
	return r == IPRange{}
}

func addrToInt(a netip.Addr) *big.Int {
	b := a.AsSlice()
	return new(big.Int).SetBytes(b)
}

func intToAddr(i *big.Int, bits int) netip.Addr {
	b := i.Bytes()
	n := bits / 8
	buf := make([]byte, n)
	copy(buf[n-len(b):], b)
	a, _ := netip.AddrFromSlice(buf)
	return a
}

// Prefixes returns the set of IPPrefix entries that covers r.
func (r IPRange) Prefixes() []netip.Prefix {
	if !r.IsValid() {
		return nil
	}
	bits := r.from.BitLen()
	out := []netip.Prefix{}
	start := addrToInt(r.from)
	end := addrToInt(r.to)
	one := big.NewInt(1)
	for start.Cmp(end) <= 0 {
		// find the largest block starting at start that fits
		size := 0
		for size < bits {
			blk := new(big.Int).Lsh(one, uint(size+1))
			mask := new(big.Int).Sub(blk, one)
			if new(big.Int).And(start, mask).Sign() != 0 {
				break
			}
			last := new(big.Int).Add(start, mask)
			if last.Cmp(end) > 0 {
				break
			}
			size++
		}
		out = append(out, netip.PrefixFrom(intToAddr(start, bits), bits-size))
		start = new(big.Int).Add(start, new(big.Int).Lsh(one, uint(size)))
	}
	return out
}

// RangeOfPrefix returns the inclusive range of IPs that p covers.
func RangeOfPrefix(p netip.Prefix) IPRange {
	p = p.Masked()
	if !p.IsValid() {
		return IPRange{}
	}
	bits := p.Addr().BitLen()
	start := addrToInt(p.Addr())
	host := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), uint(bits-p.Bits())), big.NewInt(1))
	end := new(big.Int).Or(start, host)
	return IPRangeFrom(p.Addr(), intToAddr(end, bits))
}

