	case netip.Prefix:
		return v, nil
	case *stdnet.IPNet:
		ones, _ := v.Mask.Size()
		a, _ := netip.AddrFromSlice(v.IP)
		return netip.PrefixFrom(a.Unmap(), ones), nil
	}
