// CIDRHost -
func (f *NetFuncs) CIDRHost(hostnum any, prefix any) (netip.Addr, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return netip.Addr{}, err
	}
	network, err := f.parsePrefix(prefix)
	if err != nil {
		return netip.Addr{}, err
	}
	n, err := conv.ToInt64(hostnum)
	if err != nil {
		return netip.Addr{}, fmt.Errorf("expected a number: %w", err)
	}
	return cidrHost(network, big.NewInt(n))
}

func cidrHost(network netip.Prefix, num *big.Int) (netip.Addr, error) {
	network = network.Masked()
	bits := network.Addr().BitLen()
	hostLen := bits - network.Bits()
	maxHostNum := new(big.Int).Lsh(big.NewInt(1), uint(hostLen))
	if num.Sign() >= 0 && num.Cmp(maxHostNum) >= 0 {
		return netip.Addr{}, fmt.Errorf("prefix of %d does not accommodate a host numbered %d", network.Bits(), num)
	}
	if num.Sign() < 0 {
		if new(big.Int).Neg(num).Cmp(maxHostNum) > 0 {
			return netip.Addr{}, fmt.Errorf("prefix of %d does not accommodate a host numbered %d", network.Bits(), num)
		}
		num = new(big.Int).Add(maxHostNum, num)
	}
	base := new(big.Int).SetBytes(network.Addr().AsSlice())
	res := new(big.Int).Or(base, num)
	return bigToAddr(res, bits), nil
}

func bigToAddr(i *big.Int, bits int) netip.Addr {
	b := i.Bytes()
	n := bits / 8
	buf := make([]byte, n)
	if len(b) > n {
		b = b[len(b)-n:]
	}
	copy(buf[n-len(b):], b)
	a, _ := netip.AddrFromSlice(buf)
	return a
}

// CIDRNetmask -
func (f *NetFuncs) CIDRNetmask(prefix any) (netip.Addr, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return netip.Addr{}, err
	}
	network, err := f.parsePrefix(prefix)
	if err != nil {
		return netip.Addr{}, err
	}
	bits := network.Addr().BitLen()
	mask := stdnet.CIDRMask(network.Bits(), bits)
	a, _ := netip.AddrFromSlice(mask)
	return a, nil
}

// CIDRSubnets -
func (f *NetFuncs) CIDRSubnets(newbits any, prefix any) ([]netip.Prefix, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return nil, err
	}
	network, err := f.parsePrefix(prefix)
	if err != nil {
		return nil, err
	}
	nBits, err := conv.ToInt(newbits)
	if err != nil {
		return nil, fmt.Errorf("newbits must be a number: %w", err)
	}
	if nBits < 1 {
		return nil, fmt.Errorf("must extend prefix by at least one bit")
	}
	maxNetNum := int64(1 << uint64(nBits))
	retValues := make([]netip.Prefix, maxNetNum)
	for i := int64(0); i < maxNetNum; i++ {
		subnet, err := cidrSubnet(network, nBits, big.NewInt(i))
		if err != nil {
			return nil, err
		}
		retValues[i] = subnet
	}
	return retValues, nil
}

func cidrSubnet(base netip.Prefix, newBits int, num *big.Int) (netip.Prefix, error) {
	base = base.Masked()
	bits := base.Addr().BitLen()
	parentLen := base.Bits()
	newPrefixLen := parentLen + newBits
	if newPrefixLen > bits {
		return netip.Prefix{}, fmt.Errorf("insufficient address space to extend prefix of %d by %d", parentLen, newBits)
	}
	maxNetNum := new(big.Int).Lsh(big.NewInt(1), uint(newBits))
	if num.Cmp(maxNetNum) >= 0 {
		return netip.Prefix{}, fmt.Errorf("prefix extension of %d does not accommodate a subnet numbered %d", newBits, num)
	}
	b := new(big.Int).SetBytes(base.Addr().AsSlice())
	shifted := new(big.Int).Lsh(num, uint(bits-newPrefixLen))
	res := new(big.Int).Or(b, shifted)
	return netip.PrefixFrom(bigToAddr(res, bits), newPrefixLen), nil
}

// CIDRSubnetSizes -
func (f *NetFuncs) CIDRSubnetSizes(args ...any) ([]netip.Prefix, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return nil, err
	}
	if len(args) < 2 {
		return nil, fmt.Errorf("wrong number of args: want 2 or more, got %d", len(args))
	}
	network, err := f.parsePrefix(args[len(args)-1])
	if err != nil {
		return nil, err
	}
	newbits, err := conv.ToInts(args[:len(args)-1]...)
	if err != nil {
		return nil, fmt.Errorf("newbits must be numbers: %w", err)
	}
	network = network.Masked()
	startPrefixLen := network.Bits()
	bits := network.Addr().BitLen()
	firstLength := newbits[0]
	firstLength += startPrefixLen
	retValues := make([]netip.Prefix, len(newbits))

	current, _ := cidrSubnet(network, firstLength-startPrefixLen, big.NewInt(0))
	current = netip.PrefixFrom(network.Addr(), firstLength)
	for i, length := range newbits {
		if length < 1 {
			return nil, fmt.Errorf("must extend prefix by at least one bit")
		}
		length += startPrefixLen
		if length > bits {
			return nil, fmt.Errorf("would extend prefix to %d bits, which is too long for an IPv%d address", length, map[int]int{32: 4, 128: 6}[bits])
		}
		if i > 0 {
			// next subnet after current with the given length
			last := netipx.RangeOfPrefix(current).To()
			nextInt := new(big.Int).Add(new(big.Int).SetBytes(last.AsSlice()), big.NewInt(1))
			next := netip.PrefixFrom(bigToAddr(nextInt, bits), length).Masked()
			// align
			if next.Addr().Compare(bigToAddr(nextInt, bits)) < 0 {
				// move to the next aligned block
				r := netipx.RangeOfPrefix(next).To()
				ni := new(big.Int).Add(new(big.Int).SetBytes(r.AsSlice()), big.NewInt(1))
				next = netip.PrefixFrom(bigToAddr(ni, bits), length)
			}
			current = next
		} else {
			current = netip.PrefixFrom(network.Addr(), length)
		}
		if !network.Contains(current.Addr()) || !network.Contains(netipx.RangeOfPrefix(current).To()) {
			return nil, fmt.Errorf("not enough remaining address space for a subnet with a prefix of %d bits after %s", length, retValues[i-1].String())
		}
		retValues[i] = current
	}
	return retValues, nil
}
