package jsonpath

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

const (
	leftDelim  = "{"
	rightDelim = "}"
	eof        = -1
)

type nodeType int

const (
	nodeText nodeType = iota
	nodeArray
	nodeList
	nodeField
	nodeIdentifier
	nodeFilter
	nodeInt
	nodeFloat
	nodeWildcard
	nodeRecursive
	nodeUnion
	nodeBool
)

type node interface {
	Type() nodeType
}

type listNode struct{ Nodes []node }

func (l *listNode) Type() nodeType { return nodeList }
func (l *listNode) append(n node)  { l.Nodes = append(l.Nodes, n) }

type textNode struct{ Text string }

func (t *textNode) Type() nodeType { return nodeText }

type fieldNode struct{ Value string }

func (f *fieldNode) Type() nodeType { return nodeField }

type identifierNode struct{ Name string }

func (f *identifierNode) Type() nodeType { return nodeIdentifier }

type paramsEntry struct {
	Value   int
	Known   bool
	Derived bool
}

type arrayNode struct{ Params [3]paramsEntry }

func (a *arrayNode) Type() nodeType { return nodeArray }

type filterNode struct {
	Left     *listNode
	Right    *listNode
	Operator string
}

func (f *filterNode) Type() nodeType { return nodeFilter }

type intNode struct{ Value int }

func (i *intNode) Type() nodeType { return nodeInt }

type floatNode struct{ Value float64 }

func (f *floatNode) Type() nodeType { return nodeFloat }

type boolNode struct{ Value bool }

func (b *boolNode) Type() nodeType { return nodeBool }

type wildcardNode struct{}

func (w *wildcardNode) Type() nodeType { return nodeWildcard }

type recursiveNode struct{}

func (r *recursiveNode) Type() nodeType { return nodeRecursive }

type unionNode struct{ Nodes []*listNode }

func (u *unionNode) Type() nodeType { return nodeUnion }

type parser struct {
	input string
	root  *listNode
	pos   int
	start int
	width int
}

var (
	errSyntax        = errors.New("invalid syntax")
	dictKeyRex       = regexp.MustCompile(`^'([^']*)'$`)
	sliceOperatorRex = regexp.MustCompile(`^(-?[\d]*)(:-?[\d]*)?(:-?[\d]*)?$`)
)

func parse(text string) (*parser, error) {
	p := &parser{input: text, root: &listNode{}}
	err := p.parseText(p.root)
	if err != nil {
		return nil, err
	}
	return p, nil
}

func parseAction(text string) (*parser, error) {
	return parse(fmt.Sprintf("%s%s%s", leftDelim, text, rightDelim))
}

func (p *parser) consumeText() string {
	value := p.input[p.start:p.pos]
	p.start = p.pos
	return value
}

func (p *parser) next() rune {
	if p.pos >= len(p.input) {
		p.width = 0
		return eof
	}
	r, w := utf8.DecodeRuneInString(p.input[p.pos:])
	p.width = w
	p.pos += p.width
	return r
}

func (p *parser) peek() rune {
	r := p.next()
	p.backup()
	return r
}

func (p *parser) backup() {
	p.pos -= p.width
}

func (p *parser) parseText(cur *listNode) error {
	for {
		if strings.HasPrefix(p.input[p.pos:], leftDelim) {
			if p.pos > p.start {
				cur.append(&textNode{p.consumeText()})
			}
			return p.parseLeftDelim(cur)
		}
		if p.next() == eof {
			break
		}
	}
	if p.pos > p.start {
		cur.append(&textNode{p.consumeText()})
	}
	return nil
}

func (p *parser) parseLeftDelim(cur *listNode) error {
	p.pos += len(leftDelim)
	p.consumeText()
	newNode := &listNode{}
	cur.append(newNode)
	cur = newNode
	return p.parseInsideAction(cur)
}

func (p *parser) parseInsideAction(cur *listNode) error {
	if strings.HasPrefix(p.input[p.pos:], rightDelim) {
		return p.parseRightDelim(cur)
	}
	if strings.HasPrefix(p.input[p.pos:], "[?(") {
		return p.parseFilter(cur)
	}
	if strings.HasPrefix(p.input[p.pos:], "..") {
		return p.parseRecursive(cur)
	}

	switch r := p.next(); {
	case r == eof || isEndOfLine(r):
		return fmt.Errorf("unclosed action")
	case r == ' ':
		p.consumeText()
	case r == '@' || r == '$':
		p.consumeText()
	case r == '[':
		return p.parseArray(cur)
	case r == '"' || r == '\'':
		return p.parseQuote(cur, r)
	case r == '.':
		return p.parseField(cur)
	case r == '+' || r == '-' || unicode.IsDigit(r):
		p.backup()
		return p.parseNumber(cur)
	case isAlphaNumeric(r):
		p.backup()
		return p.parseIdentifier(cur)
	default:
		return fmt.Errorf("unrecognized character in action: %#U", r)
	}
	return p.parseInsideAction(cur)
}

func (p *parser) parseRightDelim(cur *listNode) error {
	p.pos += len(rightDelim)
	p.consumeText()
	return p.parseText(p.root)
}

func (p *parser) parseIdentifier(cur *listNode) error {
	var r rune
	for {
		r = p.next()
		if isTerminator(r) {
			p.backup()
			break
		}
	}
	value := p.consumeText()
	if value == "true" || value == "false" {
		v, err := strconv.ParseBool(value)
		if err != nil {
			return fmt.Errorf("can not parse bool '%s': %s", value, err.Error())
		}
		cur.append(&boolNode{v})
	} else {
		cur.append(&identifierNode{value})
	}
	return p.parseInsideAction(cur)
}

func (p *parser) parseRecursive(cur *listNode) error {
	if lastIndex := len(cur.Nodes) - 1; lastIndex >= 0 && cur.Nodes[lastIndex].Type() == nodeRecursive {
		return fmt.Errorf("invalid multiple recursive descent")
	}
	p.pos += len("..")
	p.consumeText()
	cur.append(&recursiveNode{})
	if r := p.peek(); isAlphaNumeric(r) {
		return p.parseField(cur)
	}
	return p.parseInsideAction(cur)
}

func (p *parser) parseNumber(cur *listNode) error {
	r := p.peek()
	if r == '+' || r == '-' {
		p.next()
	}
	for {
		r = p.next()
		if r != '.' && !unicode.IsDigit(r) {
			p.backup()
			break
		}
	}
	value := p.consumeText()
	i, err := strconv.Atoi(value)
	if err == nil {
		cur.append(&intNode{i})
		return p.parseInsideAction(cur)
	}
	d, err := strconv.ParseFloat(value, 64)
	if err == nil {
		cur.append(&floatNode{d})
		return p.parseInsideAction(cur)
	}
	return fmt.Errorf("cannot parse number %s", value)
}

func (p *parser) parseArray(cur *listNode) error {
Loop:
	for {
		switch p.next() {
		case eof, '\n':
			return fmt.Errorf("unterminated array")
		case ']':
			break Loop
		}
	}
	text := p.consumeText()
	text = text[1 : len(text)-1]
	if text == "*" {
		text = ":"
	}

	strs := strings.Split(text, ",")
	if len(strs) > 1 {
		union := []*listNode{}
		for _, str := range strs {
			sp, err := parseAction(fmt.Sprintf("[%s]", strings.Trim(str, " ")))
			if err != nil {
				return err
			}
			union = append(union, sp.root)
		}
		cur.append(&unionNode{union})
		return p.parseInsideAction(cur)
	}

	value := dictKeyRex.FindStringSubmatch(text)
	if value != nil {
		sp, err := parseAction(fmt.Sprintf(".%s", value[1]))
		if err != nil {
			return err
		}
		for _, n := range sp.root.Nodes {
			cur.append(n)
		}
		return p.parseInsideAction(cur)
	}

	value = sliceOperatorRex.FindStringSubmatch(text)
	if value == nil {
		return fmt.Errorf("invalid array index %s", text)
	}
	value = value[1:]
	params := [3]paramsEntry{}
	for i := 0; i < 3; i++ {
		if value[i] != "" {
			if i > 0 {
				value[i] = value[i][1:]
			}
			if i > 0 && value[i] == "" {
				params[i].Known = false
			} else {
				var err error
				params[i].Known = true
				params[i].Value, err = strconv.Atoi(value[i])
				if err != nil {
					return fmt.Errorf("array index %s is not a number", value[i])
				}
			}
		} else {
			if i == 1 {
				params[i].Known = true
				params[i].Value = params[0].Value + 1
				params[i].Derived = true
			} else {
				params[i].Known = false
				params[i].Value = 0
			}
		}
	}
	cur.append(&arrayNode{params})
	return p.parseInsideAction(cur)
}

func (p *parser) parseFilter(cur *listNode) error {
	p.pos += len("[?(")
	p.consumeText()
	begin := false
	end := false
	var pair rune

Loop:
	for {
		r := p.next()
		switch r {
		case eof, '\n':
			return fmt.Errorf("unterminated filter")
		case '"', '\'':
			if !begin {
				begin = true
				pair = r
				continue
			}
			if p.input[p.pos-2] != '\\' && r == pair {
				end = true
			}
		case ')':
			if begin == end {
				break Loop
			}
		}
	}
	if p.next() != ']' {
		return fmt.Errorf("unclosed array expect ]")
	}
	reg := regexp.MustCompile(`^([^!<>=]+)([!<>=]+)(.+?)$`)
	text := p.consumeText()
	text = text[:len(text)-2]
	value := reg.FindStringSubmatch(text)
	if value == nil {
		sp, err := parseAction(text)
		if err != nil {
			return err
		}
		cur.append(&filterNode{sp.root, &listNode{}, "exists"})
	} else {
		lp, err := parseAction(value[1])
		if err != nil {
			return err
		}
		rp, err := parseAction(value[3])
		if err != nil {
			return err
		}
		cur.append(&filterNode{lp.root, rp.root, value[2]})
	}
	return p.parseInsideAction(cur)
}

func (p *parser) parseQuote(cur *listNode, end rune) error {
Loop:
	for {
		switch p.next() {
		case eof, '\n':
			return fmt.Errorf("unterminated quoted string")
		case end:
			if p.input[p.pos-2] != '\\' {
				break Loop
			}
		}
	}
	value := p.consumeText()
	s, err := unquoteExtend(value)
	if err != nil {
		return fmt.Errorf("unquote string %s error %v", value, err)
	}
	cur.append(&textNode{s})
	return p.parseInsideAction(cur)
}

func (p *parser) parseField(cur *listNode) error {
	p.consumeText()
	for p.advance() {
	}
	value := p.consumeText()
	if value == "*" {
		cur.append(&wildcardNode{})
	} else {
		cur.append(&fieldNode{strings.ReplaceAll(value, "\\", "")})
	}
	return p.parseInsideAction(cur)
}

func (p *parser) advance() bool {
	r := p.next()
	if r == '\\' {
		p.next()
	} else if isTerminator(r) {
		p.backup()
		return false
	}
	return true
}

func isTerminator(r rune) bool {
	if isSpace(r) || isEndOfLine(r) {
		return true
	}
	switch r {
	case eof, '.', ',', '[', ']', '$', '@', '{', '}':
		return true
	}
	return false
}

func isSpace(r rune) bool {
	return r == ' ' || r == '\t'
}

func isEndOfLine(r rune) bool {
	return r == '\r' || r == '\n'
}

func isAlphaNumeric(r rune) bool {
	return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

func unquoteExtend(s string) (string, error) {
	n := len(s)
	if n < 2 {
		return "", errSyntax
	}
	quote := s[0]
	if quote != s[n-1] {
		return "", errSyntax
	}
	s = s[1 : n-1]
	if quote != '"' && quote != '\'' {
		return "", errSyntax
	}
	if !strings.ContainsAny(s, "\\"+string(quote)) {
		return s, nil
	}
	var runeTmp [utf8.UTFMax]byte
	buf := make([]byte, 0, 3*len(s)/2)
	for len(s) > 0 {
		c, multibyte, ss, err := strconv.UnquoteChar(s, quote)
		if err != nil {
			return "", err
		}
		s = ss
		if c < utf8.RuneSelf || !multibyte {
			buf = append(buf, byte(c))
		} else {
			n := utf8.EncodeRune(runeTmp[:], c)
			buf = append(buf, runeTmp[:n]...)
		}
	}
	return string(buf), nil
}
