// Package jsonpath implements JSONPath queries, compatible with the
// Kubernetes-style JSONPath syntax.
package jsonpath

import (
	"errors"
	"fmt"
	"reflect"
	"sort"
	"strings"
)

// Query runs the JSONPath expression against the input
func Query(p string, in any) (any, error) {
	jp, err := parse("{" + p + "}")
	if err != nil {
		return nil, fmt.Errorf("couldn't parse JSONPath %s: %w", p, err)
	}
	results, err := findResults(jp, in)
	if err != nil {
		return nil, fmt.Errorf("executing JSONPath failed: %w", err)
	}

	if len(results) == 1 && len(results[0]) == 1 {
		return extractResult(results[0][0])
	}
	a := []any{}
	for _, r := range results {
		for _, v := range r {
			o, err := extractResult(v)
			if err != nil {
				return nil, err
			}
			if o != nil {
				a = append(a, o)
			}
		}
	}
	return a, nil
}

func extractResult(v reflect.Value) (any, error) {
	if v.CanInterface() {
		return v.Interface(), nil
	}
	return nil, fmt.Errorf("JSONPath couldn't access field")
}

func findResults(p *parser, data any) ([][]reflect.Value, error) {
	fullResult := [][]reflect.Value{}
	cur := []reflect.Value{reflect.ValueOf(data)}
	for _, n := range p.root.Nodes {
		results, err := walk(cur, n)
		if err != nil {
			return nil, err
		}
		fullResult = append(fullResult, results)
	}
	return fullResult, nil
}

func indirect(v reflect.Value) (rv reflect.Value, isNil bool) {
	for ; v.Kind() == reflect.Pointer || v.Kind() == reflect.Interface; v = v.Elem() {
		if v.IsNil() {
			return v, true
		}
	}
	return v, false
}

func walk(value []reflect.Value, n node) ([]reflect.Value, error) {
	switch n := n.(type) {
	case *listNode:
		return evalList(value, n)
	case *textNode:
		return []reflect.Value{reflect.ValueOf(n.Text)}, nil
	case *fieldNode:
		return evalField(value, n)
	case *arrayNode:
		return evalArray(value, n)
	case *filterNode:
		return evalFilter(value, n)
	case *intNode:
		return []reflect.Value{reflect.ValueOf(n.Value)}, nil
	case *boolNode:
		return []reflect.Value{reflect.ValueOf(n.Value)}, nil
	case *floatNode:
		return []reflect.Value{reflect.ValueOf(n.Value)}, nil
	case *wildcardNode:
		return evalWildcard(value)
	case *recursiveNode:
		return evalRecursive(value)
	case *unionNode:
		return evalUnion(value, n)
	case *identifierNode:
		return evalIdentifier(value, n)
	}
	return value, fmt.Errorf("unexpected Node %v", n)
}

func evalList(value []reflect.Value, n *listNode) ([]reflect.Value, error) {
	var err error
	cur := value
	for _, nd := range n.Nodes {
		cur, err = walk(cur, nd)
		if err != nil {
			return cur, err
		}
	}
	return cur, nil
}

func evalIdentifier(input []reflect.Value, n *identifierNode) ([]reflect.Value, error) {
	switch n.Name {
	case "range", "end":
		return input, fmt.Errorf("range is not supported")
	}
	return input, fmt.Errorf("unrecognized identifier %v", n.Name)
}

func evalArray(input []reflect.Value, n *arrayNode) ([]reflect.Value, error) {
	result := []reflect.Value{}
	for _, value := range input {
		value, isNil := indirect(value)
		if isNil {
			continue
		}
		if value.Kind() != reflect.Array && value.Kind() != reflect.Slice {
			return input, fmt.Errorf("%v is not array or slice", value.Type())
		}
		params := n.Params
		if !params[0].Known {
			params[0].Value = 0
		}
		if params[0].Value < 0 {
			params[0].Value += value.Len()
		}
		if !params[1].Known {
			params[1].Value = value.Len()
		}
		if params[1].Value < 0 || (params[1].Value == 0 && params[1].Derived) {
			params[1].Value += value.Len()
		}
		sliceLength := value.Len()
		if params[1].Value != params[0].Value {
			if params[0].Value >= sliceLength || params[0].Value < 0 {
				return input, fmt.Errorf("array index out of bounds: index %d, length %d", params[0].Value, sliceLength)
			}
			if params[1].Value > sliceLength || params[1].Value < 0 {
				return input, fmt.Errorf("array index out of bounds: index %d, length %d", params[1].Value-1, sliceLength)
			}
			if params[0].Value > params[1].Value {
				return input, fmt.Errorf("starting index %d is greater than ending index %d", params[0].Value, params[1].Value)
			}
		} else {
			return result, nil
		}
		value = value.Slice(params[0].Value, params[1].Value)
		step := 1
		if params[2].Known {
			if params[2].Value <= 0 {
				return input, fmt.Errorf("step must be > 0")
			}
			step = params[2].Value
		}
		for i := 0; i < value.Len(); i += step {
			result = append(result, value.Index(i))
		}
	}
	return result, nil
}

func evalUnion(input []reflect.Value, n *unionNode) ([]reflect.Value, error) {
	result := []reflect.Value{}
	for _, ln := range n.Nodes {
		temp, err := evalList(input, ln)
		if err != nil {
			return input, err
		}
		result = append(result, temp...)
	}
	return result, nil
}

func findFieldInValue(value *reflect.Value, n *fieldNode) (reflect.Value, error) {
	t := value.Type()
	var inlineValue *reflect.Value
	for ix := 0; ix < t.NumField(); ix++ {
		f := t.Field(ix)
		jsonTag := f.Tag.Get("json")
		parts := strings.Split(jsonTag, ",")
		if jsonTag == "" || parts[0] == "" {
			if f.Name == n.Value {
				return value.Field(ix), nil
			}
		}
		if len(parts[0]) != 0 {
			if parts[0] == n.Value {
				return value.Field(ix), nil
			}
		}
		if len(parts[0]) == 0 {
			for ix := 1; ix < len(parts); ix++ {
				if parts[ix] == "inline" {
					if inlineValue != nil {
						return reflect.Value{}, fmt.Errorf("multiple inline fields")
					}
					fv := value.Field(ix)
					inlineValue = &fv
				}
			}
		}
	}
	if inlineValue != nil {
		if inlineValue.Kind() == reflect.Struct {
			return findFieldInValue(inlineValue, n)
		}
	}
	return value.FieldByName(n.Value), nil
}

func evalField(input []reflect.Value, n *fieldNode) ([]reflect.Value, error) {
	results := []reflect.Value{}
	if len(input) == 0 {
		return results, nil
	}
	for _, value := range input {
		var result reflect.Value
		value, isNil := indirect(value)
		if isNil {
			continue
		}
		if value.Kind() == reflect.Struct {
			var err error
			if result, err = findFieldInValue(&value, n); err != nil {
				return nil, err
			}
		} else if value.Kind() == reflect.Map {
			mapKeyType := value.Type().Key()
			nodeValue := reflect.ValueOf(n.Value)
			if !nodeValue.Type().ConvertibleTo(mapKeyType) {
				return results, fmt.Errorf("%s is not convertible to %s", nodeValue, mapKeyType)
			}
			result = value.MapIndex(nodeValue.Convert(mapKeyType))
		}
		if result.IsValid() {
			results = append(results, result)
		}
	}
	if len(results) == 0 {
		return results, fmt.Errorf("%s is not found", n.Value)
	}
	return results, nil
}

func sortedMapKeys(value reflect.Value) []reflect.Value {
	keys := value.MapKeys()
	sort.Slice(keys, func(i, j int) bool {
		return fmt.Sprint(keys[i].Interface()) < fmt.Sprint(keys[j].Interface())
	})
	return keys
}

func children(value reflect.Value) []reflect.Value {
	results := []reflect.Value{}
	kind := value.Kind()
	switch kind {
	case reflect.Struct:
		for i := 0; i < value.NumField(); i++ {
			results = append(results, value.Field(i))
		}
	case reflect.Map:
		for _, key := range sortedMapKeys(value) {
			results = append(results, value.MapIndex(key))
		}
	case reflect.Array, reflect.Slice, reflect.String:
		for i := 0; i < value.Len(); i++ {
			results = append(results, value.Index(i))
		}
	}
	return results
}

func evalWildcard(input []reflect.Value) ([]reflect.Value, error) {
	results := []reflect.Value{}
	for _, value := range input {
		value, isNil := indirect(value)
		if isNil {
			continue
		}
		results = append(results, children(value)...)
	}
	return results, nil
}

func evalRecursive(input []reflect.Value) ([]reflect.Value, error) {
	result := []reflect.Value{}
	for _, value := range input {
		value, isNil := indirect(value)
		if isNil {
			continue
		}
		results := children(value)
		if len(results) != 0 {
			result = append(result, value)
			output, err := evalRecursive(results)
			if err != nil {
				return result, err
			}
			result = append(result, output...)
		}
	}
	return result, nil
}

func evalFilter(input []reflect.Value, n *filterNode) ([]reflect.Value, error) {
	results := []reflect.Value{}
	for _, value := range input {
		value, _ = indirect(value)
		if value.Kind() != reflect.Array && value.Kind() != reflect.Slice {
			return input, fmt.Errorf("%v is not array or slice and cannot be filtered", value)
		}
		for i := 0; i < value.Len(); i++ {
			temp := []reflect.Value{value.Index(i)}
			lefts, err := evalList(temp, n.Left)
			if n.Operator == "exists" {
				if len(lefts) > 0 {
					results = append(results, value.Index(i))
				}
				continue
			}
			if err != nil {
				return input, err
			}
			var left, right any
			switch {
			case len(lefts) == 0:
				continue
			case len(lefts) > 1:
				return input, fmt.Errorf("can only compare one element at a time")
			}
			left = lefts[0].Interface()

			rights, err := evalList(temp, n.Right)
			if err != nil {
				return input, err
			}
			switch {
			case len(rights) == 0:
				continue
			case len(rights) > 1:
				return input, fmt.Errorf("can only compare one element at a time")
			}
			right = rights[0].Interface()

			pass := false
			switch n.Operator {
			case "<":
				pass, err = lt(left, right)
			case ">":
				pass, err = lt(right, left)
			case "==":
				pass, err = eq(left, right)
			case "!=":
				pass, err = eq(left, right)
				pass = !pass
			case "<=":
				pass, err = le(left, right)
			case ">=":
				pass, err = le(right, left)
			default:
				return results, fmt.Errorf("unrecognized filter operator %s", n.Operator)
			}
			if err != nil {
				return results, err
			}
			if pass {
				results = append(results, value.Index(i))
			}
		}
	}
	return results, nil
}

var (
	errBadComparisonType = errors.New("invalid type for comparison")
	errBadComparison     = errors.New("incompatible types for comparison")
)

type kind int

const (
	invalidKind kind = iota
	boolKind
	complexKind
	intKind
	floatKind
	stringKind
	uintKind
)

func basicKind(v reflect.Value) (kind, error) {
	switch v.Kind() {
	case reflect.Bool:
		return boolKind, nil
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return intKind, nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return uintKind, nil
	case reflect.Float32, reflect.Float64:
		return floatKind, nil
	case reflect.Complex64, reflect.Complex128:
		return complexKind, nil
	case reflect.String:
		return stringKind, nil
	}
	return invalidKind, errBadComparisonType
}

func eq(arg1, arg2 any) (bool, error) {
	v1 := reflect.ValueOf(arg1)
	k1, err := basicKind(v1)
	if err != nil {
		return false, err
	}
	v2 := reflect.ValueOf(arg2)
	k2, err := basicKind(v2)
	if err != nil {
		return false, err
	}
	if k1 != k2 {
		switch {
		case k1 == intKind && k2 == uintKind:
			return v1.Int() >= 0 && uint64(v1.Int()) == v2.Uint(), nil
		case k1 == uintKind && k2 == intKind:
			return v2.Int() >= 0 && v1.Uint() == uint64(v2.Int()), nil
		default:
			return false, errBadComparison
		}
	}
	switch k1 {
	case boolKind:
		return v1.Bool() == v2.Bool(), nil
	case complexKind:
		return v1.Complex() == v2.Complex(), nil
	case floatKind:
		return v1.Float() == v2.Float(), nil
	case intKind:
		return v1.Int() == v2.Int(), nil
	case stringKind:
		return v1.String() == v2.String(), nil
	case uintKind:
		return v1.Uint() == v2.Uint(), nil
	}
	return false, errBadComparisonType
}

func lt(arg1, arg2 any) (bool, error) {
	v1 := reflect.ValueOf(arg1)
	k1, err := basicKind(v1)
	if err != nil {
		return false, err
	}
	v2 := reflect.ValueOf(arg2)
	k2, err := basicKind(v2)
	if err != nil {
		return false, err
	}
	if k1 != k2 {
		switch {
		case k1 == intKind && k2 == uintKind:
			return v1.Int() < 0 || uint64(v1.Int()) < v2.Uint(), nil
		case k1 == uintKind && k2 == intKind:
			return v2.Int() >= 0 && v1.Uint() < uint64(v2.Int()), nil
		default:
			return false, errBadComparison
		}
	}
	switch k1 {
	case boolKind, complexKind:
		return false, errBadComparisonType
	case floatKind:
		return v1.Float() < v2.Float(), nil
	case intKind:
		return v1.Int() < v2.Int(), nil
	case stringKind:
		return v1.String() < v2.String(), nil
	case uintKind:
		return v1.Uint() < v2.Uint(), nil
	}
	return false, errBadComparisonType
}

func le(arg1, arg2 any) (bool, error) {
	lessThan, err := lt(arg1, arg2)
	if lessThan || err != nil {
		return lessThan, err
	}
	return eq(arg1, arg2)
}
