{"command":"cat > /workspace/internal/jq/lexer.go <<'EOF'
package jq

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokKind int

const (
	tEOF tokKind = iota
	tIdent
	tField   // .foo
	tVar     // $foo
	tNumber  // 1.5
	tString  // "..." (raw with interpolation parts)
	tFormat  // @base64
	tOp      // operators & punctuation
	tKeyword // if then else ...
)

type token struct {
	kind tokKind
	val  string
	str  *strLit
	pos  int
}

// strLit is a string literal possibly containing interpolations
type strLit struct {
	parts []any // string or *strInterp
}

type strInterp struct {
	src string
}

var keywords = map[string]bool{
	"def": true, "if": true, "then": true, "elif": true, "else": true, "end": true,
	"as": true, "reduce": true, "foreach": true, "try": true, "catch": true,
	"label": true, "import": true, "include": true, "and": true, "or": true,
	"not": false, "__loc__": true,
}

type lexer struct {
	src  string
	pos  int
	toks []token
}

func isIdentStart(r rune) bool {
	return r == '_' || unicode.IsLetter(r)
}

func isIdentChar(r rune) bool {
	return r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

func lex(src string) ([]token, error) {
	l := &lexer{src: src}
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		l.toks = append(l.toks, t)
		if t.kind == tEOF {
			return l.toks, nil
		}
	}
}

var ops3 = []string{"?//", "//="}
var ops2 = []string{"|=", "+=", "-=", "*=", "/=", "%=", "==", "!=", "<=", ">=", "//", "..", "?/"}

func (l *lexer) next() (token, error) {
	// skip whitespace & comments
	for l.pos < len(l.src) {
		c := l.src[l.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			l.pos++
			continue
		}
		if c == '#' {
			for l.pos < len(l.src) && l.src[l.pos] != '\n' {
				l.pos++
			}
			continue
		}
		break
	}
	if l.pos >= len(l.src) {
		return token{kind: tEOF, pos: l.pos}, nil
	}
	start := l.pos
	c := l.src[l.pos]
	switch {
	case c == '"':
		s, err := l.lexString()
		if err != nil {
			return token{}, err
		}
		return token{kind: tString, str: s, pos: start}, nil
	case c == '.':
		if l.pos+1 < len(l.src) {
			r, _ := utf8.DecodeRuneInString(l.src[l.pos+1:])
			if isIdentStart(r) {
				l.pos++
				for l.pos < len(l.src) {
					r, w := utf8.DecodeRuneInString(l.src[l.pos:])
					if !isIdentChar(r) {
						break
					}
					l.pos += w
				}
				return token{kind: tField, val: l.src[start+1 : l.pos], pos: start}, nil
			}
			if l.src[l.pos+1] == '.' {
				l.pos += 2
				return token{kind: tOp, val: "..", pos: start}, nil
			}
			if l.src[l.pos+1] >= '0' && l.src[l.pos+1] <= '9' {
				return l.lexNumber()
			}
		}
		l.pos++
		return token{kind: tOp, val: ".", pos: start}, nil
	case c == '$':
		l.pos++
		for l.pos < len(l.src) {
			r, w := utf8.DecodeRuneInString(l.src[l.pos:])
			if !isIdentChar(r) && r != ':' {
				break
			}
			if r == ':' {
				if l.pos+1 < len(l.src) && l.src[l.pos+1] == ':' {
					l.pos += 2
					continue
				}
				break
			}
			l.pos += w
		}
		return token{kind: tVar, val: l.src[start+1 : l.pos], pos: start}, nil
	case c == '@':
		l.pos++
		for l.pos < len(l.src) {
			r, w := utf8.DecodeRuneInString(l.src[l.pos:])
			if !isIdentChar(r) {
				break
			}
			l.pos += w
		}
		return token{kind: tFormat, val: l.src[start:l.pos], pos: start}, nil
	case c >= '0' && c <= '9':
		return l.lexNumber()
	}
	r, w := utf8.DecodeRuneInString(l.src[l.pos:])
	if isIdentStart(r) {
		l.pos += w
		for l.pos < len(l.src) {
			r, w := utf8.DecodeRuneInString(l.src[l.pos:])
			if isIdentChar(r) {
				l.pos += w
				continue
			}
			if r == ':' && l.pos+1 < len(l.src) && l.src[l.pos+1] == ':' {
				l.pos += 2
				continue
			}
			break
		}
		v := l.src[start:l.pos]
		if keywords[v] {
			return token{kind: tKeyword, val: v, pos: start}, nil
		}
		return token{kind: tIdent, val: v, pos: start}, nil
	}
	for _, o := range ops3 {
		if strings.HasPrefix(l.src[l.pos:], o) {
			l.pos += len(o)
			return token{kind: tOp, val: o, pos: start}, nil
		}
	}
	for _, o := range ops2 {
		if strings.HasPrefix(l.src[l.pos:], o) {
			l.pos += len(o)
			return token{kind: tOp, val: o, pos: start}, nil
		}
	}
	switch c {
	case '|', ',', '+', '-', '*', '/', '%', '=', '<', '>', '(', ')', '[', ']', '{', '}', ':', ';', '?':
		l.pos++
		return token{kind: tOp, val: string(c), pos: start}, nil
	}
	return token{}, fmt.Errorf("unexpected token %q", string(r))
}

func (l *lexer) lexNumber() (token, error) {
	start := l.pos
	for l.pos < len(l.src) && (l.src[l.pos] >= '0' && l.src[l.pos] <= '9' || l.src[l.pos] == '.') {
		l.pos++
	}
	if l.pos < len(l.src) && (l.src[l.pos] == 'e' || l.src[l.pos] == 'E') {
		l.pos++
		if l.pos < len(l.src) && (l.src[l.pos] == '+' || l.src[l.pos] == '-') {
			l.pos++
		}
		for l.pos < len(l.src) && l.src[l.pos] >= '0' && l.src[l.pos] <= '9' {
			l.pos++
		}
	}
	return token{kind: tNumber, val: l.src[start:l.pos], pos: start}, nil
}

func (l *lexer) lexString() (*strLit, error) {
	l.pos++ // opening quote
	s := &strLit{}
	var cur strings.Builder
	for {
		if l.pos >= len(l.src) {
			return nil, fmt.Errorf("unterminated string literal")
		}
		c := l.src[l.pos]
		if c == '"' {
			l.pos++
			break
		}
		if c == '\\' {
			l.pos++
			if l.pos >= len(l.src) {
				return nil, fmt.Errorf("unterminated string literal")
			}
			e := l.src[l.pos]
			switch e {
			case 'n':
				cur.WriteByte('\n')
			case 't':
				cur.WriteByte('\t')
			case 'r':
				cur.WriteByte('\r')
			case 'b':
				cur.WriteByte('\b')
			case 'f':
				cur.WriteByte('\f')
			case '/':
				cur.WriteByte('/')
			case '\\':
				cur.WriteByte('\\')
			case '"':
				cur.WriteByte('"')
			case 'u':
				if l.pos+4 >= len(l.src) {
					return nil, fmt.Errorf("invalid escape sequence")
				}
				var r rune
				_, err := fmt.Sscanf(l.src[l.pos+1:l.pos+5], "%04x", &r)
				if err != nil {
					return nil, fmt.Errorf("invalid escape sequence")
				}
				l.pos += 4
				cur.WriteRune(r)
			case '(':
				// interpolation
				depth := 1
				l.pos++
				istart := l.pos
				inStr := false
				for l.pos < len(l.src) && depth > 0 {
					ch := l.src[l.pos]
					if inStr {
						if ch == '\\' {
							l.pos += 2
							continue
						}
						if ch == '"' {
							inStr = false
						}
						l.pos++
						continue
					}
					switch ch {
					case '"':
						inStr = true
					case '(':
						depth++
					case ')':
						depth--
					}
					l.pos++
				}
				if depth != 0 {
					return nil, fmt.Errorf("unterminated string interpolation")
				}
				if cur.Len() > 0 {
					s.parts = append(s.parts, cur.String())
					cur.Reset()
				}
				s.parts = append(s.parts, &strInterp{src: l.src[istart : l.pos-1]})
				continue
			default:
				return nil, fmt.Errorf("invalid escape sequence \"\\%c\" in string literal", e)
			}
			l.pos++
			continue
		}
		cur.WriteByte(c)
		l.pos++
	}
	if cur.Len() > 0 || len(s.parts) == 0 {
		s.parts = append(s.parts, cur.String())
	}
	return s, nil
}
EOF
echo ok"}

