package jq

import (
	"fmt"
	"strconv"
)

type node interface{}

type (
	nIdentity  struct{}
	nRecurseDf struct{}
	nIndex     struct {
		target node
		index  node
	}
	nSlice struct {
		target   node
		from, to node
	}
	nIterate struct{ target node }
	nPipe    struct{ left, right node }
	nComma   struct{ left, right node }
	nAlt     struct{ left, right node }
	nBinop   struct {
		op          string
		left, right node
	}
	nAnd     struct{ left, right node }
	nOr      struct{ left, right node }
	nNeg     struct{ x node }
	nLiteral struct{ v any }
	nString  struct {
		parts  []any // string or node
		format string
	}
	nFormat struct{ name string }
	nArray  struct{ body node }
	nObject struct{ entries []objEntry }
	nIf     struct {
		cond, then, els node
	}
	nTry struct{ body, catch node }
	nOpt struct{ body node }
	nReduce struct {
		source       node
		pattern      *pattern
		init, update node
	}
	nForeach struct {
		source                node
		pattern               *pattern
		init, update, extract node
	}
	nFuncDef struct {
		name   string
		params []string
		body   node
		rest   node
	}
	nCall struct {
		name string
		args []node
	}
	nVar  struct{ name string }
	nBind struct {
		source   node
		patterns []*pattern
		body     node
	}
	nAssign struct {
		op       string
		lhs, rhs node
	}
	nLabel struct {
		name string
		body node
	}
	nBreak struct{ name string }
)

type objEntry struct {
	key      node // nil if keyVar
	keyStr   string
	value    node // may be nil for shorthand
	keyVar   string
	isString bool
}

type pattern struct {
	name   string // variable name for simple $x
	array  []*pattern
	object []objPattern
}

type objPattern struct {
	keyVar string // $name
	key    node
	val    *pattern
}

type parser struct {
	toks []token
	pos  int
}

func parse(src string) (node, error) {
	toks, err := lex(src)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks}
	n, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.peek().kind != tEOF {
		return nil, p.unexpected()
	}
	return n, nil
}

func (p *parser) peek() token { return p.toks[p.pos] }
func (p *parser) advance() token {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *parser) isOp(v string) bool {
	t := p.peek()
	return t.kind == tOp && t.val == v
}

func (p *parser) isKw(v string) bool {
	t := p.peek()
	return t.kind == tKeyword && t.val == v
}

func (p *parser) unexpected() error {
	t := p.peek()
	if t.kind == tEOF {
		return fmt.Errorf("unexpected EOF")
	}
	v := t.val
	if t.kind == tString {
		v = "\"...\""
	}
	if t.kind == tField {
		v = "." + v
	}
	if t.kind == tVar {
		v = "$" + v
	}
	return fmt.Errorf("unexpected token %q", v)
}

func (p *parser) expectOp(v string) error {
	if !p.isOp(v) {
		return p.unexpected()
	}
	p.advance()
	return nil
}

func (p *parser) expectKw(v string) error {
	if !p.isKw(v) {
		return p.unexpected()
	}
	p.advance()
	return nil
}

// pipe: def ... ; pipe | term as $x | pipe | comma ('|' pipe)?
func (p *parser) parsePipe() (node, error) {
	if p.isKw("def") {
		fd, err := p.parseFuncDef()
		if err != nil {
			return nil, err
		}
		rest, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		fd.rest = rest
		return fd, nil
	}
	if p.isKw("label") {
		p.advance()
		t := p.advance()
		if t.kind != tVar {
			return nil, fmt.Errorf("unexpected token %q", t.val)
		}
		if err := p.expectOp("|"); err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &nLabel{name: t.val, body: body}, nil
	}
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	if p.isKw("as") {
		p.advance()
		pats := []*pattern{}
		pat, err := p.parsePattern()
		if err != nil {
			return nil, err
		}
		pats = append(pats, pat)
		for p.isOp("?//") {
			p.advance()
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			pats = append(pats, pat)
		}
		if err := p.expectOp("|"); err != nil {
			return nil, err
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &nBind{source: left, patterns: pats, body: body}, nil
	}
	if p.isOp("|") {
		p.advance()
		right, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &nPipe{left, right}, nil
	}
	return left, nil
}

func (p *parser) parseFuncDef() (*nFuncDef, error) {
	p.advance() // def
	t := p.advance()
	if t.kind != tIdent && t.kind != tKeyword {
		return nil, fmt.Errorf("unexpected token %q", t.val)
	}
	fd := &nFuncDef{name: t.val}
	if p.isOp("(") {
		p.advance()
		for {
			pt := p.advance()
			switch pt.kind {
			case tIdent:
				fd.params = append(fd.params, pt.val)
			case tVar:
				fd.params = append(fd.params, "$"+pt.val)
			default:
				return nil, fmt.Errorf("unexpected token %q", pt.val)
			}
			if p.isOp(";") {
				p.advance()
				continue
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			break
		}
	}
	if err := p.expectOp(":"); err != nil {
		return nil, err
	}
	body, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp(";"); err != nil {
		return nil, err
	}
	fd.body = body
	return fd, nil
}

func (p *parser) parsePattern() (*pattern, error) {
	t := p.peek()
	switch {
	case t.kind == tVar:
		p.advance()
		return &pattern{name: t.val}, nil
	case p.isOp("["):
		p.advance()
		pat := &pattern{array: []*pattern{}}
		if p.isOp("]") {
			p.advance()
			return pat, nil
		}
		for {
			sub, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			pat.array = append(pat.array, sub)
			if p.isOp(",") {
				p.advance()
				continue
			}
			if err := p.expectOp("]"); err != nil {
				return nil, err
			}
			return pat, nil
		}
	case p.isOp("{"):
		p.advance()
		pat := &pattern{object: []objPattern{}}
		for {
			op := objPattern{}
			kt := p.peek()
			switch {
			case kt.kind == tVar:
				p.advance()
				op.keyVar = kt.val
			case kt.kind == tIdent || kt.kind == tKeyword:
				p.advance()
				op.key = &nLiteral{kt.val}
			case kt.kind == tString:
				p.advance()
				op.key = stringNode(kt.str, "")
			case p.isOp("("):
				p.advance()
				k, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				if err := p.expectOp(")"); err != nil {
					return nil, err
				}
				op.key = k
			default:
				return nil, p.unexpected()
			}
			if p.isOp(":") {
				p.advance()
				sub, err := p.parsePattern()
				if err != nil {
					return nil, err
				}
				op.val = sub
			} else if op.keyVar == "" {
				return nil, p.unexpected()
			}
			pat.object = append(pat.object, op)
			if p.isOp(",") {
				p.advance()
				continue
			}
			if err := p.expectOp("}"); err != nil {
				return nil, err
			}
			return pat, nil
		}
	}
	return nil, p.unexpected()
}

func (p *parser) parseComma() (node, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	for p.isOp(",") {
		p.advance()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		left = &nComma{left, right}
	}
	return left, nil
}

func (p *parser) parseAlt() (node, error) {
	left, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	if p.isOp("//") {
		p.advance()
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		return &nAlt{left, right}, nil
	}
	return left, nil
}

func (p *parser) parseAssign() (node, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	t := p.peek()
	if t.kind == tOp {
		switch t.val {
		case "=", "|=", "+=", "-=", "*=", "/=", "%=", "//=":
			p.advance()
			right, err := p.parseAlt()
			if err != nil {
				return nil, err
			}
			return &nAssign{op: t.val, lhs: left, rhs: right}, nil
		}
	}
	return left, nil
}

func (p *parser) parseOr() (node, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.isKw("or") {
		p.advance()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &nOr{left, right}
	}
	return left, nil
}

func (p *parser) parseAnd() (node, error) {
	left, err := p.parseCompare()
	if err != nil {
		return nil, err
	}
	for p.isKw("and") {
		p.advance()
		right, err := p.parseCompare()
		if err != nil {
			return nil, err
		}
		left = &nAnd{left, right}
	}
	return left, nil
}

func (p *parser) parseCompare() (node, error) {
	left, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	t := p.peek()
	if t.kind == tOp {
		switch t.val {
		case "==", "!=", "<", "<=", ">", ">=":
			p.advance()
			right, err := p.parseAdditive()
			if err != nil {
				return nil, err
			}
			return &nBinop{op: t.val, left: left, right: right}, nil
		}
	}
	return left, nil
}

func (p *parser) parseAdditive() (node, error) {
	left, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.isOp("+") || p.isOp("-") {
		op := p.advance().val
		right, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		left = &nBinop{op: op, left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseMultiplicative() (node, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.isOp("*") || p.isOp("/") || p.isOp("%") {
		op := p.advance().val
		right, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		left = &nBinop{op: op, left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseUnary() (node, error) {
	if p.isOp("-") {
		p.advance()
		x, err := p.parsePostfix()
		if err != nil {
			return nil, err
		}
		return &nNeg{x}, nil
	}
	return p.parsePostfix()
}

func (p *parser) parsePostfix() (node, error) {
	term, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	return p.parseSuffixes(term)
}

func (p *parser) parseSuffixes(term node) (node, error) {
	for {
		t := p.peek()
		switch {
		case t.kind == tField:
			p.advance()
			term = &nIndex{target: term, index: &nLiteral{t.val}}
		case t.kind == tOp && t.val == "." && p.toks[p.pos+1].kind == tString:
			p.advance()
			st := p.advance()
			term = &nIndex{target: term, index: stringNode(st.str, "")}
		case t.kind == tOp && t.val == "." && p.toks[p.pos+1].kind == tOp && p.toks[p.pos+1].val == "[":
			p.advance()
		case t.kind == tOp && t.val == "[":
			n, err := p.parseBracket(term)
			if err != nil {
				return nil, err
			}
			term = n
		case t.kind == tOp && t.val == "?":
			p.advance()
			term = &nOpt{body: term}
		default:
			return term, nil
		}
	}
}

func (p *parser) parseBracket(target node) (node, error) {
	p.advance() // [
	if p.isOp("]") {
		p.advance()
		return &nIterate{target: target}, nil
	}
	if p.isOp(":") {
		p.advance()
		to, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if err := p.expectOp("]"); err != nil {
			return nil, err
		}
		return &nSlice{target: target, to: to}, nil
	}
	idx, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if p.isOp(":") {
		p.advance()
		var to node
		if !p.isOp("]") {
			to, err = p.parsePipe()
			if err != nil {
				return nil, err
			}
		}
		if err := p.expectOp("]"); err != nil {
			return nil, err
		}
		return &nSlice{target: target, from: idx, to: to}, nil
	}
	if err := p.expectOp("]"); err != nil {
		return nil, err
	}
	return &nIndex{target: target, index: idx}, nil
}

func stringNode(s *strLit, format string) node {
	if len(s.parts) == 1 {
		if str, ok := s.parts[0].(string); ok && format == "" {
			return &nLiteral{str}
		}
	}
	n := &nString{format: format}
	for _, part := range s.parts {
		switch v := part.(type) {
		case string:
			n.parts = append(n.parts, v)
		case *strInterp:
			sub, err := parse(v.src)
			if err != nil {
				n.parts = append(n.parts, &nCall{name: "error", args: []node{&nLiteral{err.Error()}}})
			} else {
				n.parts = append(n.parts, sub)
			}
		}
	}
	return n
}

func (p *parser) parseTerm() (node, error) {
	t := p.peek()
	switch t.kind {
	case tNumber:
		p.advance()
		if i, err := strconv.Atoi(t.val); err == nil {
			return &nLiteral{i}, nil
		}
		f, err := strconv.ParseFloat(t.val, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid number: %s", t.val)
		}
		return &nLiteral{f}, nil
	case tString:
		p.advance()
		return stringNode(t.str, ""), nil
	case tFormat:
		p.advance()
		if p.peek().kind == tString {
			st := p.advance()
			return stringNode(st.str, t.val), nil
		}
		return &nFormat{name: t.val}, nil
	case tField:
		p.advance()
		return &nIndex{target: &nIdentity{}, index: &nLiteral{t.val}}, nil
	case tVar:
		p.advance()
		if t.val == "__loc__" {
			return &nLiteral{map[string]any{"file": "<stdin>", "line": 1}}, nil
		}
		return &nVar{name: t.val}, nil
	case tKeyword:
		switch t.val {
		case "if":
			return p.parseIf()
		case "try":
			p.advance()
			body, err := p.parsePostTry()
			if err != nil {
				return nil, err
			}
			var catch node
			if p.isKw("catch") {
				p.advance()
				catch, err = p.parsePostTry()
				if err != nil {
					return nil, err
				}
			}
			return &nTry{body: body, catch: catch}, nil
		case "reduce":
			p.advance()
			src, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			if err := p.expectKw("as"); err != nil {
				return nil, err
			}
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("("); err != nil {
				return nil, err
			}
			init, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(";"); err != nil {
				return nil, err
			}
			upd, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return &nReduce{source: src, pattern: pat, init: init, update: upd}, nil
		case "foreach":
			p.advance()
			src, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			if err := p.expectKw("as"); err != nil {
				return nil, err
			}
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("("); err != nil {
				return nil, err
			}
			init, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(";"); err != nil {
				return nil, err
			}
			upd, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			var ext node
			if p.isOp(";") {
				p.advance()
				ext, err = p.parsePipe()
				if err != nil {
					return nil, err
				}
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return &nForeach{source: src, pattern: pat, init: init, update: upd, extract: ext}, nil
		case "def":
			fd, err := p.parseFuncDef()
			if err != nil {
				return nil, err
			}
			rest, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			fd.rest = rest
			return fd, nil
		case "label":
			p.advance()
			v := p.advance()
			if err := p.expectOp("|"); err != nil {
				return nil, err
			}
			body, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			return &nLabel{name: v.val, body: body}, nil
		}
		return nil, p.unexpected()
	case tIdent:
		p.advance()
		switch t.val {
		case "null":
			return &nLiteral{nil}, nil
		case "true":
			return &nLiteral{true}, nil
		case "false":
			return &nLiteral{false}, nil
		case "break":
			v := p.advance()
			if v.kind != tVar {
				return nil, fmt.Errorf("unexpected token %q", v.val)
			}
			return &nBreak{name: v.val}, nil
		}
		call := &nCall{name: t.val}
		if p.isOp("(") {
			p.advance()
			for {
				a, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				call.args = append(call.args, a)
				if p.isOp(";") {
					p.advance()
					continue
				}
				if err := p.expectOp(")"); err != nil {
					return nil, err
				}
				break
			}
		}
		return call, nil
	case tOp:
		switch t.val {
		case ".":
			p.advance()
			if p.peek().kind == tString {
				st := p.advance()
				return &nIndex{target: &nIdentity{}, index: stringNode(st.str, "")}, nil
			}
			if p.isOp("[") {
				return p.parseBracket(&nIdentity{})
			}
			return &nIdentity{}, nil
		case "..":
			p.advance()
			return &nRecurseDf{}, nil
		case "(":
			p.advance()
			n, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return n, nil
		case "[":
			p.advance()
			if p.isOp("]") {
				p.advance()
				return &nArray{}, nil
			}
			body, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp("]"); err != nil {
				return nil, err
			}
			return &nArray{body: body}, nil
		case "{":
			return p.parseObject()
		case "-":
			p.advance()
			x, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			return &nNeg{x}, nil
		}
	}
	return nil, p.unexpected()
}

func (p *parser) parsePostTry() (node, error) {
	term, err := p.parseTerm()
	if err != nil {
		return nil, err
	}
	return p.parseSuffixes(term)
}

func (p *parser) parseIf() (node, error) {
	p.advance() // if or elif
	cond, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	if err := p.expectKw("then"); err != nil {
		return nil, err
	}
	then, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	n := &nIf{cond: cond, then: then}
	switch {
	case p.isKw("elif"):
		els, err := p.parseIf()
		if err != nil {
			return nil, err
		}
		n.els = els
		return n, nil
	case p.isKw("else"):
		p.advance()
		els, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		n.els = els
	}
	if err := p.expectKw("end"); err != nil {
		return nil, err
	}
	return n, nil
}

func (p *parser) parseObject() (node, error) {
	p.advance() // {
	obj := &nObject{}
	if p.isOp("}") {
		p.advance()
		return obj, nil
	}
	for {
		e := objEntry{}
		t := p.peek()
		switch {
		case t.kind == tVar:
			p.advance()
			e.keyVar = t.val
		case t.kind == tIdent || t.kind == tKeyword:
			p.advance()
			e.keyStr = t.val
			e.isString = true
		case t.kind == tNumber:
			p.advance()
			e.keyStr = t.val
			e.isString = true
		case t.kind == tString:
			p.advance()
			e.key = stringNode(t.str, "")
		case t.kind == tFormat:
			p.advance()
			if p.peek().kind == tString {
				st := p.advance()
				e.key = stringNode(st.str, t.val)
			} else {
				e.key = &nFormat{name: t.val}
			}
		case p.isOp("("):
			p.advance()
			k, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			e.key = k
		default:
			return nil, p.unexpected()
		}
		if p.isOp(":") {
			p.advance()
			v, err := p.parseObjVal()
			if err != nil {
				return nil, err
			}
			e.value = v
		}
		obj.entries = append(obj.entries, e)
		if p.isOp(",") {
			p.advance()
			continue
		}
		if err := p.expectOp("}"); err != nil {
			return nil, err
		}
		return obj, nil
	}
}

func (p *parser) parseObjVal() (node, error) {
	left, err := p.parseObjValTerm()
	if err != nil {
		return nil, err
	}
	for p.isOp("|") {
		p.advance()
		right, err := p.parseObjValTerm()
		if err != nil {
			return nil, err
		}
		left = &nPipe{left, right}
	}
	return left, nil
}

func (p *parser) parseObjValTerm() (node, error) {
	return p.parseAlt()
}
