type emitFn func(v any) error
type pathEmitFn func(v any, path []any) error

// env holds variables and functions
type env struct {
	vars   *varScope
	funcs  *funcScope
	labels *labelScope
	ctx    context.Context
}

type varScope struct {
	name  string
	value any
	next  *varScope
}

type funcScope struct {
	name   string
	arity  int
	def    *nFuncDef
	env    *env // closure env
	native func(args []node, e *env, input any, emit emitFn) error
	// closure args (non-$ params): the param name binds to a closure
	closure *closure
	next    *funcScope
}

type closure struct {
	body node
	env  *env
}

type labelScope struct {
	name string
	id   *int
	next *labelScope
}

type breakError struct {
	id *int
}

func (b *breakError) Error() string { return "break" }

// errEmpty is used to stop iteration early
var errStop = errors.New("stop")

func (e *env) lookupVar(name string) (any, bool) {
	for s := e.vars; s != nil; s = s.next {
		if s.name == name {
			return s.value, true
		}
	}
	return nil, false
}

func (e *env) withVar(name string, v any) *env {
	n := *e
	n.vars = &varScope{name: name, value: v, next: e.vars}
	return &n
}

func (e *env) lookupFunc(name string, arity int) *funcScope {
	for s := e.funcs; s != nil; s = s.next {
		if s.name == name && s.arity == arity {
			return s
		}
	}
	return nil
}

func (e *env) withFunc(fs *funcScope) *env {
	n := *e
	fs.next = e.funcs
	n.funcs = fs
	return &n
}

// valueError is an error raised by `error`
type valueError struct {
	v any
}

func (v *valueError) Error() string {
	if s, ok := v.v.(string); ok {
		return s
	}
	b, _ := json.Marshal(v.v)
	return string(b) + " (not a string)"
}

func eval(n node, input any, e *env, emit emitFn) error {
	if e.ctx != nil {
		if err := e.ctx.Err(); err != nil {
			return err
		}
	}
	switch n := n.(type) {
	case *nIdentity:
		return emit(input)
	case *nRecurseDf:
		return recurseValues(input, emit)
	case *nLiteral:
		return emit(n.v)
	case *nIndex:
		return eval(n.target, input, e, func(t any) error {
			return eval(n.index, input, e, func(idx any) error {
				v, err := indexValue(t, idx)
				if err != nil {
					return err
				}
				return emit(v)
			})
		})
	case *nSlice:
		return eval(n.target, input, e, func(t any) error {
			return evalOptional(n.from, input, e, func(from any) error {
				return evalOptional(n.to, input, e, func(to any) error {
					v, err := sliceValue(t, from, to)
					if err != nil {
						return err
					}
					return emit(v)
				})
			})
		})
	case *nIterate:
		return eval(n.target, input, e, func(t any) error {
			return iterate(t, emit)
		})
	case *nPipe:
		return eval(n.left, input, e, func(v any) error {
			return eval(n.right, v, e, emit)
		})
	case *nComma:
		if err := eval(n.left, input, e, emit); err != nil {
			return err
		}
		return eval(n.right, input, e, emit)
	case *nAlt:
		found := false
		err := eval(n.left, input, e, func(v any) error {
			if truthy(v) {
				found = true
				return emit(v)
			}
			return nil
		})
		if err != nil {
			var be *breakError
			if errors.As(err, &be) {
				return err
			}
			if found {
				return nil
			}
		}
		if !found {
			return eval(n.right, input, e, emit)
		}
		return nil
	case *nAnd:
		return eval(n.left, input, e, func(l any) error {
			if !truthy(l) {
				return emit(false)
			}
			return eval(n.right, input, e, func(r any) error {
				return emit(truthy(r))
			})
		})
	case *nOr:
		return eval(n.left, input, e, func(l any) error {
			if truthy(l) {
				return emit(true)
			}
			return eval(n.right, input, e, func(r any) error {
				return emit(truthy(r))
			})
		})
	case *nNeg:
		return eval(n.x, input, e, func(v any) error {
			switch x := v.(type) {
			case int:
				return emit(-x)
			case float64:
				return emit(-x)
			}
			return fmt.Errorf("cannot negate: %s", typePreview(v))
		})
	case *nBinop:
		return eval(n.right, input, e, func(r any) error {
			return eval(n.left, input, e, func(l any) error {
				v, err := binop(n.op, l, r)
				if err != nil {
					return err
				}
				return emit(v)
			})
		})
	case *nString:
		return evalString(n, input, e, emit)
	case *nFormat:
		s, err := applyFormat(n.name, input)
		if err != nil {
			return err
		}
		return emit(s)
	case *nArray:
		arr := []any{}
		if n.body != nil {
			err := eval(n.body, input, e, func(v any) error {
				arr = append(arr, v)
				return nil
			})
			if err != nil {
				return err
			}
		}
		return emit(arr)
	case *nObject:
		return evalObject(n.entries, 0, map[string]any{}, input, e, emit)
	case *nIf:
		return eval(n.cond, input, e, func(c any) error {
			if truthy(c) {
				return eval(n.then, input, e, emit)
			}
			if n.els != nil {
				return eval(n.els, input, e, emit)
			}
			return emit(input)
		})
	case *nTry:
		var emitErr error
		err := eval(n.body, input, e, func(v any) error {
			if err := emit(v); err != nil {
				emitErr = err
				return err
			}
			return nil
		})
		if err != nil {
			if emitErr != nil && errors.Is(err, emitErr) {
				return err
			}
			var be *breakError
			if errors.As(err, &be) {
				return err
			}
			if n.catch != nil {
				var ev any = err.Error()
				var ve *valueError
				if errors.As(err, &ve) {
					ev = ve.v
				}
				return eval(n.catch, ev, e, emit)
			}
		}
		return nil
	case *nOpt:
		return eval(&nTry{body: n.body}, input, e, emit)
	case *nVar:
		if n.name == "ENV" {
			if v, ok := e.lookupVar(n.name); ok {
				return emit(v)
			}
			return emit(envMap())
		}
		v, ok := e.lookupVar(n.name)
		if !ok {
			return fmt.Errorf("variable not defined: $%s", n.name)
		}
		return emit(v)
	case *nBind:
		return eval(n.source, input, e, func(v any) error {
			var lastErr error
			for i, pat := range n.patterns {
				ne, err := bindPattern(pat, v, input, e)
				if err != nil {
					return err
				}
				// for alternatives, bind all variables from all patterns to null first
				if len(n.patterns) > 1 {
					for _, p2 := range n.patterns {
						for _, name := range patternVars(p2) {
							if _, ok := ne.lookupVar(name); !ok {
								ne = ne.withVar(name, nil)
							}
						}
					}
				}
				err = eval(n.body, input, ne, emit)
				if err == nil {
					return nil
				}
				lastErr = err
				if i == len(n.patterns)-1 {
					return err
				}
			}
			return lastErr
		})
	case *nReduce:
		var acc []any
		err := eval(n.init, input, e, func(v any) error {
			acc = append(acc, v)
			return nil
		})
		if err != nil {
			return err
		}
		for _, init := range acc {
			state := []any{init}
			err := eval(n.source, input, e, func(v any) error {
				ne, err := bindPattern(n.pattern, v, input, e)
				if err != nil {
					return err
				}
				next := []any{}
				for _, s := range state {
					err := eval(n.update, s, ne, func(u any) error {
						next = append(next, u)
						return nil
					})
					if err != nil {
						return err
					}
				}
				if len(next) == 0 {
					state = []any{nil}
				} else {
					state = next[len(next)-1:]
				}
				return nil
			})
			if err != nil {
				return err
			}
			for _, s := range state {
				if err := emit(s); err != nil {
					return err
				}
			}
		}
		return nil
	case *nForeach:
		return eval(n.init, input, e, func(init any) error {
			state := init
			return eval(n.source, input, e, func(v any) error {
				ne, err := bindPattern(n.pattern, v, input, e)
				if err != nil {
					return err
				}
				return eval(n.update, state, ne, func(u any) error {
					state = u
					if n.extract == nil {
						return emit(u)
					}
					return eval(n.extract, u, ne, emit)
				})
			})
		})
	case *nFuncDef:
		fs := &funcScope{name: n.name, arity: len(n.params), def: n}
		ne := e.withFunc(fs)
		fs.env = ne
		return eval(n.rest, input, ne, emit)
	case *nCall:
		return callFunc(n, input, e, emit)
	case *nAssign:
		return evalAssign(n, input, e, emit)
	case *nLabel:
		id := new(int)
		ne := *e
		ne.labels = &labelScope{name: n.name, id: id, next: e.labels}
		err := eval(n.body, input, &ne, emit)
		var be *breakError
		if errors.As(err, &be) && be.id == id {
			return nil
		}
		return err
	case *nBreak:
		for l := e.labels; l != nil; l = l.next {
			if l.name == n.name {
				return &breakError{id: l.id}
			}
		}
		return fmt.Errorf("$*label-%s is not defined", n.name)
	}
	return fmt.Errorf("unsupported expression %T", n)
}

func evalOptional(n node, input any, e *env, emit emitFn) error {
	if n == nil {
		return emit(nil)
	}
	return eval(n, input, e, emit)
}

func evalObject(entries []objEntry, i int, acc map[string]any, input any, e *env, emit emitFn) error {
	if i >= len(entries) {
		out := make(map[string]any, len(acc))
		for k, v := range acc {
			out[k] = v
		}
		return emit(out)
	}
	ent := entries[i]
	withKV := func(k any, valNode node, valFromInput bool) error {
		ks, ok := k.(string)
		if !ok {
			return fmt.Errorf("expected a string for object key but got: %s", typePreview(k))
		}
		if valNode == nil {
			var v any
			if valFromInput {
				v2, err := indexValue(input, ks)
				if err != nil {
					return err
				}
				v = v2
			}
			acc2 := copyObj(acc)
			acc2[ks] = v
			return evalObject(entries, i+1, acc2, input, e, emit)
		}
		return eval(valNode, input, e, func(v any) error {
			acc2 := copyObj(acc)
			acc2[ks] = v
			return evalObject(entries, i+1, acc2, input, e, emit)
		})
	}
	switch {
	case ent.keyVar != "":
		v, ok := e.lookupVar(ent.keyVar)
		if !ok {
			return fmt.Errorf("variable not defined: $%s", ent.keyVar)
		}
		if ent.value == nil {
			acc2 := copyObj(acc)
			acc2[ent.keyVar] = v
			return evalObject(entries, i+1, acc2, input, e, emit)
		}
		return withKV(v, ent.value, false)
	case ent.isString:
		return withKV(ent.keyStr, ent.value, true)
	default:
		return eval(ent.key, input, e, func(k any) error {
			return withKV(k, ent.value, true)
		})
	}
}

func copyObj(m map[string]any) map[string]any {
	out := make(map[string]any, len(m)+1)
	for k, v := range m {
		out[k] = v
	}
	return out
}

func evalString(n *nString, input any, e *env, emit emitFn) error {
	var rec func(i int, acc string) error
	rec = func(i int, acc string) error {
		if i >= len(n.parts) {
			return emit(acc)
		}
		switch p := n.parts[i].(type) {
		case string:
			return rec(i+1, acc+p)
		case node:
			return eval(p, input, e, func(v any) error {
				var s string
				if n.format != "" {
					fs, err := applyFormat(n.format, v)
					if err != nil {
						return err
					}
					s = fs
				} else {
					if str, ok := v.(string); ok {
						s = str
					} else {
						s = toJSON(v)
					}
				}
				return rec(i+1, acc+s)
			})
		}
		return nil
	}
	return rec(0, "")
}

func patternVars(p *pattern) []string {
	out := []string{}
	if p.name != "" {
		out = append(out, p.name)
	}
	for _, a := range p.array {
		out = append(out, patternVars(a)...)
	}
	for _, o := range p.object {
		if o.keyVar != "" {
			out = append(out, o.keyVar)
		}
		if o.val != nil {
			out = append(out, patternVars(o.val)...)
		}
	}
	return out
}

func bindPattern(p *pattern, v any, input any, e *env) (*env, error) {
	if p.name != "" {
		return e.withVar(p.name, v), nil
	}
	if p.array != nil {
		if v != nil {
			if _, ok := v.([]any); !ok {
				return nil, fmt.Errorf("cannot index %s with number", typeName(v))
			}
		}
		ne := e
		for i, sub := range p.array {
			var item any
			if arr, ok := v.([]any); ok && i < len(arr) {
				item = arr[i]
			}
			var err error
			ne, err = bindPattern(sub, item, input, ne)
			if err != nil {
				return nil, err
			}
		}
		return ne, nil
	}
	ne := e
	for _, op := range p.object {
		var key any
		if op.keyVar != "" {
			key = op.keyVar
		} else {
			var keys []any
			err := eval(op.key, input, ne, func(k any) error {
				keys = append(keys, k)
				return nil
			})
			if err != nil {
				return nil, err
			}
			if len(keys) > 0 {
				key = keys[0]
			}
		}
		ks, ok := key.(string)
		if !ok {
			return nil, fmt.Errorf("cannot index object with %s", typeName(key))
		}
		var val any
		if v != nil {
			m, ok := v.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("cannot index %s with \"%s\"", typeName(v), ks)
			}
			val = m[ks]
		}
		if op.keyVar != "" {
			ne = ne.withVar(op.keyVar, val)
		}
		if op.val != nil {
			var err error
			ne, err = bindPattern(op.val, val, input, ne)
			if err != nil {
				return nil, err
			}
		}
	}
	return ne, nil
}

func callFunc(n *nCall, input any, e *env, emit emitFn) error {
	fs := e.lookupFunc(n.name, len(n.args))
	if fs != nil {
		if fs.closure != nil {
			return eval(fs.closure.body, input, fs.closure.env, emit)
		}
		if fs.native != nil {
			return fs.native(n.args, e, input, emit)
		}
		return callDef(fs, n.args, input, e, emit)
	}
	if b, ok := builtins[builtinKey(n.name, len(n.args))]; ok {
		return b(n.args, e, input, emit)
	}
	if def, ok := builtinDefs[builtinKey(n.name, len(n.args))]; ok {
		fs := &funcScope{name: n.name, arity: len(n.args), def: def, env: rootEnv(e)}
		return callDef(fs, n.args, input, e, emit)
	}
	return fmt.Errorf("function not defined: %s/%d", n.name, len(n.args))
}

func rootEnv(e *env) *env {
	return &env{ctx: e.ctx}
}

func callDef(fs *funcScope, args []node, input any, callerEnv *env, emit emitFn) error {
	def := fs.def
	// function body env: closure env + self (for recursion) + params
	fenv := fs.env
	self := &funcScope{name: def.name, arity: len(def.params), def: def}
	fenv = fenv.withFunc(self)
	self.env = fs.env
	var bindVals func(i int, e2 *env) error
	bindVals = func(i int, e2 *env) error {
		if i >= len(def.params) {
			return eval(def.body, input, e2, emit)
		}
		pname := def.params[i]
		if strings.HasPrefix(pname, "$") {
			name := pname[1:]
			return eval(args[i], input, callerEnv, func(v any) error {
				ne := e2.withVar(name, v)
				ne = ne.withFunc(&funcScope{name: name, arity: 0, closure: &closure{body: &nLiteral{v}, env: callerEnv}})
				return bindVals(i+1, ne)
			})
		}
		ne := e2.withFunc(&funcScope{name: pname, arity: 0, closure: &closure{body: args[i], env: callerEnv}})
		return bindVals(i+1, ne)
	}
	return bindVals(0, fenv)
}

func builtinKey(name string, arity int) string {
	return name + "/" + strconv.Itoa(arity)
}

// value helpers

func typeName(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case int, float64:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	}
	return fmt.Sprintf("%T", v)
}

func toJSON(v any) string {
	var b strings.Builder
	writeJSON(&b, v)
	return b.String()
}

func writeJSON(b *strings.Builder, v any) {
	switch x := v.(type) {
	case nil:
		b.WriteString("null")
	case bool:
		if x {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case int:
		b.WriteString(strconv.Itoa(x))
	case float64:
		b.WriteString(formatNumber(x))
	case string:
		bs, _ := json.Marshal(x)
		b.Write(bs)
	case []any:
		b.WriteByte('[')
		for i, e := range x {
			if i > 0 {
				b.WriteByte(',')
			}
			writeJSON(b, e)
		}
		b.WriteByte(']')
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		b.WriteByte('{')
		for i, k := range keys {
			if i > 0 {
				b.WriteByte(',')
			}
			bs, _ := json.Marshal(k)
			b.Write(bs)
			b.WriteByte(':')
			writeJSON(b, x[k])
		}
		b.WriteByte('}')
	default:
		bs, _ := json.Marshal(x)
		b.Write(bs)
	}
}

func formatNumber(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e17 {
		return strconv.FormatFloat(f, 'f', -1, 64)
	}
	return strconv.FormatFloat(f, 'g', 17, 64)
}

func typePreview(v any) string {
	s := toJSON(v)
	if len(s) > 11 {
		s = s[:10] + " ..."
	}
	return typeName(v) + " (" + s + ")"
}

func truthy(v any) bool {
	switch x := v.(type) {
	case nil:
		return false
	case bool:
		return x
	}
	return true
}

func toFloat(v any) (float64, bool) {
	switch x := v.(type) {
	case int:
		return float64(x), true
	case float64:
		return x, true
	}
	return 0, false
}

func normalizeNumber(f float64) any {
	if f == math.Trunc(f) && math.Abs(f) <= 1<<53 {
		return int(f)
	}
	return f
}

func indexValue(t, idx any) (any, error) {
	switch x := t.(type) {
	case nil:
		switch idx.(type) {
		case string, int, float64, nil:
			return nil, nil
		case map[string]any:
			return nil, nil
		}
	case map[string]any:
		if k, ok := idx.(string); ok {
			return x[k], nil
		}
		return nil, fmt.Errorf("expected a string for object key but got: %s", typePreview(idx))
	case []any:
		switch i := idx.(type) {
		case int:
			if i < 0 {
				i += len(x)
			}
			if i < 0 || i >= len(x) {
				return nil, nil
			}
			return x[i], nil
		case float64:
			n := int(math.Floor(i))
			if n < 0 {
				n += len(x)
			}
			if n < 0 || n >= len(x) {
				return nil, nil
			}
			return x[n], nil
		case map[string]any:
			start, _ := toFloat(i["start"])
			end, hasEnd := toFloat(i["end"])
			var to any
			if hasEnd {
				to = end
			}
			return sliceValue(x, start, to)
		case []any:
			return indices(x, i), nil
		}
		return nil, fmt.Errorf("expected a number for indexing an array but got: %s", typePreview(idx))
	case string:
		if m, ok := idx.(map[string]any); ok {
			start, _ := toFloat(m["start"])
			end, hasEnd := toFloat(m["end"])
			var to any
			if hasEnd {
				to = end
			}
			return sliceValue(x, start, to)
		}
	}
	switch idx.(type) {
	case string:
		return nil, fmt.Errorf("expected an object but got: %s", typePreview(t))
	case int, float64:
		return nil, fmt.Errorf("expected an array but got: %s", typePreview(t))
	}
	return nil, fmt.Errorf("cannot index %s with %s", typeName(t), typeName(idx))
}

func clampSlice(length int, from, to any) (int, int, error) {
	start, end := 0, length
	if from != nil {
		f, ok := toFloat(from)
		if !ok {
			return 0, 0, fmt.Errorf("start index must be a number but got: %s", typePreview(from))
		}
		start = int(math.Floor(f))
	}
	if to != nil {
		f, ok := toFloat(to)
		if !ok {
			return 0, 0, fmt.Errorf("end index must be a number but got: %s", typePreview(to))
		}
		end = int(math.Ceil(f))
	}
	if start < 0 {
		start += length
		if start < 0 {
			start = 0
		}
	}
	if end < 0 {
		end += length
	}
	if start > length {
		start = length
	}
	if end > length {
		end = length
	}
	if end < start {
		end = start
	}
	return start, end, nil
}

func sliceValue(t, from, to any) (any, error) {
	switch x := t.(type) {
	case nil:
		return nil, nil
	case []any:
		s, e, err := clampSlice(len(x), from, to)
		if err != nil {
			return nil, err
		}
		return append([]any{}, x[s:e]...), nil
	case string:
		r := []rune(x)
		s, e, err := clampSlice(len(r), from, to)
		if err != nil {
			return nil, err
		}
		return string(r[s:e]), nil
	}
	return nil, fmt.Errorf("cannot slice %s", typePreview(t))
}

func iterate(t any, emit emitFn) error {
	switch x := t.(type) {
	case []any:
		for _, v := range x {
			if err := emit(v); err != nil {
				return err
			}
		}
		return nil
	case map[string]any:
		keys := sortedKeys(x)
		for _, k := range keys {
			if err := emit(x[k]); err != nil {
				return err
			}
		}
		return nil
	}
	return fmt.Errorf("cannot iterate over: %s", typePreview(t))
}

func sortedKeys(m map[string]any) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func recurseValues(v any, emit emitFn) error {
	if err := emit(v); err != nil {
		return err
	}
	switch x := v.(type) {
	case []any:
		for _, c := range x {
			if err := recurseValues(c, emit); err != nil {
				return err
			}
		}
	case map[string]any:
		for _, k := range sortedKeys(x) {
			if err := recurseValues(x[k], emit); err != nil {
				return err
			}
		}
	}
	return nil
}

// typeOrder for sorting
func typeOrder(v any) int {
	switch x := v.(type) {
	case nil:
		return 0
	case bool:
		if x {
			return 2
		}
		return 1
	case int, float64:
		return 3
	case string:
		return 4
	case []any:
		return 5
	case map[string]any:
		return 6
	}
	return 7
}

func compare(a, b any) int {
	ta, tb := typeOrder(a), typeOrder(b)
	if ta != tb {
		if ta < tb {
			return -1
		}
		return 1
	}
	switch x := a.(type) {
	case int, float64:
		fa, _ := toFloat(x)
		fb, _ := toFloat(b)
		switch {
		case fa < fb:
			return -1
		case fa > fb:
			return 1
		}
		return 0
	case string:
		return strings.Compare(x, b.(string))
	case []any:
		y := b.([]any)
		for i := 0; i < len(x) && i < len(y); i++ {
			if c := compare(x[i], y[i]); c != 0 {
				return c
			}
		}
		switch {
		case len(x) < len(y):
			return -1
		case len(x) > len(y):
			return 1
		}
		return 0
	case map[string]any:
		y := b.(map[string]any)
		ka := sortedKeys(x)
		kb := sortedKeys(y)
		ia := make([]any, len(ka))
		for i, k := range ka {
			ia[i] = k
		}
		ib := make([]any, len(kb))
		for i, k := range kb {
			ib[i] = k
		}
		if c := compare(ia, ib); c != 0 {
			return c
		}
		for _, k := range ka {
			if c := compare(x[k], y[k]); c != 0 {
				return c
			}
		}
		return 0
	}
	return 0
}

func binop(op string, l, r any) (any, error) {
	switch op {
	case "+":
		return add(l, r)
	case "-":
		return subtract(l, r)
	case "*":
		return multiply(l, r)
	case "/":
		return divide(l, r)
	case "%":
		return modulo(l, r)
	case "==":
		return compare(l, r) == 0, nil
	case "!=":
		return compare(l, r) != 0, nil
	case "<":
		return compare(l, r) < 0, nil
	case "<=":
		return compare(l, r) <= 0, nil
	case ">":
		return compare(l, r) > 0, nil
	case ">=":
		return compare(l, r) >= 0, nil
	}
	return nil, fmt.Errorf("unknown operator %s", op)
}

func add(l, r any) (any, error) {
	if l == nil {
		return r, nil
	}
	if r == nil {
		return l, nil
	}
	switch x := l.(type) {
	case int:
		switch y := r.(type) {
		case int:
			return x + y, nil
		case float64:
			return float64(x) + y, nil
		}
	case float64:
		if y, ok := toFloat(r); ok {
			return x + y, nil
		}
	case string:
		if y, ok := r.(string); ok {
			return x + y, nil
		}
	case []any:
		if y, ok := r.([]any); ok {
			out := make([]any, 0, len(x)+len(y))
			out = append(out, x...)
			return append(out, y...), nil
		}
	case map[string]any:
		if y, ok := r.(map[string]any); ok {
			out := copyObj(x)
			for k, v := range y {
				out[k] = v
			}
			return out, nil
		}
	}
	return nil, fmt.Errorf("cannot add: %s and %s", typePreview(l), typePreview(r))
}

func subtract(l, r any) (any, error) {
	switch x := l.(type) {
	case int:
		switch y := r.(type) {
		case int:
			return x - y, nil
		case float64:
			return float64(x) - y, nil
		}
	case float64:
		if y, ok := toFloat(r); ok {
			return x - y, nil
		}
	case []any:
		if y, ok := r.([]any); ok {
			out := []any{}
			for _, v := range x {
				found := false
				for _, w := range y {
					if compare(v, w) == 0 {
						found = true
						break
					}
				}
				if !found {
					out = append(out, v)
				}
			}
			return out, nil
		}
	}
	return nil, fmt.Errorf("cannot subtract: %s and %s", typePreview(l), typePreview(r))
}

func deepMerge(a, b map[string]any) map[string]any {
	out := copyObj(a)
	for k, v := range b {
		if av, ok := out[k].(map[string]any); ok {
			if bv, ok := v.(map[string]any); ok {
				out[k] = deepMerge(av, bv)
				continue
			}
		}
		out[k] = v
	}
	return out
}

func multiply(l, r any) (any, error) {
	switch x := l.(type) {
	case int:
		switch y := r.(type) {
		case int:
			return x * y, nil
		case float64:
			return float64(x) * y, nil
		case string:
			return repeatString(y, float64(x)), nil
		}
	case float64:
		if y, ok := toFloat(r); ok {
			return x * y, nil
		}
		if y, ok := r.(string); ok {
			return repeatString(y, x), nil
		}
	case string:
		if y, ok := toFloat(r); ok {
			return repeatString(x, y), nil
		}
	case map[string]any:
		if y, ok := r.(map[string]any); ok {
			return deepMerge(x, y), nil
		}
	}
	return nil, fmt.Errorf("cannot multiply: %s and %s", typePreview(l), typePreview(r))
}

func repeatString(s string, n float64) any {
	if n <= 0 {
		return nil
	}
	c := int(math.Ceil(n))
	if c < 1 {
		c = 1
	}
	return strings.Repeat(s, c)
}

func divide(l, r any) (any, error) {
	switch x := l.(type) {
	case int:
		switch y := r.(type) {
		case int:
			if y == 0 {
				return nil, fmt.Errorf("cannot divide %s by: %s", typePreview(l), typePreview(r))
			}
			if x%y == 0 {
				return x / y, nil
			}
			return float64(x) / float64(y), nil
		case float64:
			if y == 0 {
				return nil, fmt.Errorf("cannot divide %s by: %s", typePreview(l), typePreview(r))
			}
			return float64(x) / y, nil
		}
	case float64:
		if y, ok := toFloat(r); ok {
			if y == 0 {
				return nil, fmt.Errorf("cannot divide %s by: %s", typePreview(l), typePreview(r))
			}
			return x / y, nil
		}
	case string:
		if y, ok := r.(string); ok {
			out := []any{}
			if x == "" {
				return out, nil
			}
			for _, s := range strings.Split(x, y) {
				out = append(out, s)
			}
			return out, nil
		}
	}
	return nil, fmt.Errorf("cannot divide: %s and %s", typePreview(l), typePreview(r))
}

func modulo(l, r any) (any, error) {
	lf, lok := toFloat(l)
	rf, rok := toFloat(r)
	if lok && rok {
		li := int(lf)
		ri := int(rf)
		if ri == 0 {
			return nil, fmt.Errorf("cannot modulo %s by: %s", typePreview(l), typePreview(r))
		}
		if ri < 0 {
			ri = -ri
		}
		res := li % ri
		return res, nil
	}
	return nil, fmt.Errorf("cannot modulo: %s and %s", typePreview(l), typePreview(r))
}

// normalize converts arbitrary Go values into jq-compatible values
func normalize(v any) any {
	switch x := v.(type) {
	case nil, bool, string, int, float64:
		return x
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = normalize(e)
		}
		return out
	case map[string]any:
		out := make(map[string]any, len(x))
		for k, e := range x {
			out[k] = normalize(e)
		}
		return out
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return int(rv.Int())
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		u := rv.Uint()
		if u > math.MaxInt64 {
			return float64(u)
		}
		return int(u)
	case reflect.Float32, reflect.Float64:
		return rv.Float()
	case reflect.String:
		return rv.String()
	case reflect.Bool:
		return rv.Bool()
	case reflect.Slice, reflect.Array:
		if rv.Kind() == reflect.Slice && rv.Type().Elem().Kind() == reflect.Uint8 {
			break
		}
		out := make([]any, rv.Len())
		for i := 0; i < rv.Len(); i++ {
			out[i] = normalize(rv.Index(i).Interface())
		}
		return out
	case reflect.Map:
		out := make(map[string]any, rv.Len())
		iter := rv.MapRange()
		for iter.Next() {
			out[fmt.Sprint(iter.Key().Interface())] = normalize(iter.Value().Interface())
		}
		return out
	case reflect.Pointer, reflect.Interface:
		if rv.IsNil() {
			return nil
		}
	}
	// fall back to a JSON round-trip
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	var out any
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.UseNumber()
	if err := dec.Decode(&out); err != nil {
		return fmt.Sprint(v)
	}
	return fromJSONNumbers(out)
}

func fromJSONNumbers(v any) any {
	switch x := v.(type) {
	case json.Number:
		if i, err := strconv.Atoi(string(x)); err == nil {
			return i
		}
		f, _ := x.Float64()
		return f
	case []any:
		for i, e := range x {
			x[i] = fromJSONNumbers(e)
		}
		return x
	case map[string]any:
		for k, e := range x {
			x[k] = fromJSONNumbers(e)
		}
		return x
	}
	return v
}
