	case *nAlt:
		found := false
		err := evalPath(n.left, input, path, root, e, func(v any, p []any) error {
			if truthy(v) {
				found = true
				return emit(v, p)
			}
			return nil
		})
		if err != nil && found {
			return nil
		}
		if !found {
			return evalPath(n.right, input, path, root, e, emit)
		}
		return nil
	case *nIf:
		return eval(n.cond, input, e, func(c any) error {
			if truthy(c) {
				return evalPath(n.then, input, path, root, e, emit)
			}
			if n.els != nil {
				return evalPath(n.els, input, path, root, e, emit)
			}
			return emit(input, path)
		})
	case *nTry:
		var emitErr error
		err := evalPath(n.body, input, path, root, e, func(v any, p []any) error {
			if err := emit(v, p); err != nil {
				emitErr = err
				return err
			}
			return nil
		})
		if err != nil && emitErr != nil {
			return err
		}
		return nil
	case *nOpt:
		return evalPath(&nTry{body: n.body}, input, path, root, e, emit)
	case *nFuncDef:
		fs := &funcScope{name: n.name, arity: len(n.params), def: n}
		ne := e.withFunc(fs)
		fs.env = ne
		return evalPath(n.rest, input, path, root, ne, emit)
	case *nBind:
		return eval(n.source, input, e, func(v any) error {
			ne, err := bindPattern(n.patterns[0], v, input, e)
			if err != nil {
				return err
			}
			return evalPath(n.body, input, path, root, ne, emit)
		})
	case *nLiteral:
		if n.v == nil {
			return emit(nil, path)
		}
	case *nReduce:
		var acc []any
		var accPaths [][]any
		err := evalPath(n.init, input, path, root, e, func(v any, p []any) error {
			acc = append(acc, v)
			accPaths = append(accPaths, p)
			return nil
		})
		if err != nil {
			return err
		}
		for i := range acc {
			state, statePath := acc[i], accPaths[i]
			err := eval(n.source, input, e, func(v any) error {
				ne, err := bindPattern(n.pattern, v, input, e)
				if err != nil {
					return err
				}
				return evalPath(n.update, state, statePath, root, ne, func(u any, p []any) error {
					state, statePath = u, p
					return nil
				})
			})
			if err != nil {
				return err
			}
			if err := emit(state, statePath); err != nil {
				return err
			}
		}
		return nil
	case *nCall:
		return callFuncPath(n, input, path, root, e, emit)
	}
	return fmt.Errorf("invalid path expression with result %s", previewEval(n, input, e))
}

func previewEval(n node, input any, e *env) string {
	var out any
	_ = eval(n, input, e, func(v any) error {
		out = v
		return errStop
	})
	return typePreview(out)
}

func appendPath(p []any, k any) []any {
	out := make([]any, len(p), len(p)+1)
	copy(out, p)
	return append(out, k)
}

func recursePaths(v any, path []any, emit pathEmitFn) error {
	if err := emit(v, path); err != nil {
		return err
	}
	switch x := v.(type) {
	case []any:
		for i, c := range x {
			if err := recursePaths(c, appendPath(path, i), emit); err != nil {
				return err
			}
		}
	case map[string]any:
		for _, k := range sortedKeys(x) {
			if err := recursePaths(x[k], appendPath(path, k), emit); err != nil {
				return err
			}
		}
	}
	return nil
}

func callFuncPath(n *nCall, input any, path []any, root any, e *env, emit pathEmitFn) error {
	fs := e.lookupFunc(n.name, len(n.args))
	if fs != nil {
		if fs.closure != nil {
			return evalPath(fs.closure.body, input, path, root, fs.closure.env, emit)
		}
		if fs.def != nil {
			return callDefPath(fs, n.args, input, path, root, e, emit)
		}
	}
	switch builtinKey(n.name, len(n.args)) {
	case "empty/0":
		return nil
	case "error/0", "error/1":
		return eval(n, input, e, func(any) error { return nil })
	case "getpath/1":
		return eval(n.args[0], input, e, func(pv any) error {
			p, ok := pv.([]any)
			if !ok {
				return fmt.Errorf("path must be specified as an array")
			}
			v, err := getPath(input, p)
			if err != nil {
				v = nil
			}
			full := append(append([]any{}, path...), p...)
			return emit(v, full)
		})
	case "first/0":
		v, _ := indexValue(input, 0)
		return emit(v, appendPath(path, 0))
	case "last/0":
		v, _ := indexValue(input, -1)
		return emit(v, appendPath(path, -1))
	}
	if def, ok := builtinDefs[builtinKey(n.name, len(n.args))]; ok {
		fs := &funcScope{name: n.name, arity: len(n.args), def: def, env: rootEnv(e)}
		return callDefPath(fs, n.args, input, path, root, e, emit)
	}
	if _, ok := builtins[builtinKey(n.name, len(n.args))]; ok {
		return fmt.Errorf("invalid path expression with result %s", previewEval(n, input, e))
	}
	return fmt.Errorf("function not defined: %s/%d", n.name, len(n.args))
}

func callDefPath(fs *funcScope, args []node, input any, path []any, root any, callerEnv *env, emit pathEmitFn) error {
	def := fs.def
	fenv := fs.env
	self := &funcScope{name: def.name, arity: len(def.params), def: def}
	fenv = fenv.withFunc(self)
	self.env = fs.env
	var bindVals func(i int, e2 *env) error
	bindVals = func(i int, e2 *env) error {
		if i >= len(def.params) {
			return evalPath(def.body, input, path, root, e2, emit)
		}
		pname := def.params[i]
		if pname[0] == '$' {
			name := pname[1:]
			return eval(args[i], input, callerEnv, func(v any) error {
				ne := e2.withVar(name, v)
				ne = ne.withFunc(&funcScope{name: name, arity: 0, closure: &closure{body: &nLiteral{v}, env: callerEnv}})
				return bindVals(i+1, ne)
			})
		}
		ne := e2.withFunc(&funcScope{name: pname, arity: 0, closure: &closure{body: args[i], env: callerEnv}})
		return bindVals(i+1, ne)
	}
	return bindVals(0, fenv)
}

func getPath(v any, path []any) (any, error) {
	cur := v
	for _, p := range path {
		if cur == nil {
			return nil, nil
		}
		next, err := indexValue(cur, p)
		if err != nil {
			return nil, err
		}
		cur = next
	}
	return cur, nil
}

func setPath(v any, path []any, val any) (any, error) {
	if len(path) == 0 {
		return val, nil
	}
	k := path[0]
	switch key := k.(type) {
	case string:
		var m map[string]any
		switch x := v.(type) {
		case nil:
			m = map[string]any{}
		case map[string]any:
			m = copyObj(x)
		default:
			return nil, fmt.Errorf("expected an object but got: %s", typePreview(v))
		}
		nv, err := setPath(m[key], path[1:], val)
		if err != nil {
			return nil, err
		}
		m[key] = nv
		return m, nil
	case int, float64:
		f, _ := toFloat(key)
		i := int(math.Floor(f))
		var arr []any
		switch x := v.(type) {
		case nil:
			arr = []any{}
		case []any:
			arr = append([]any{}, x...)
		default:
			return nil, fmt.Errorf("expected an array but got: %s", typePreview(v))
		}
		if i < 0 {
			i += len(arr)
			if i < 0 {
				return nil, fmt.Errorf("out of bounds negative array index")
			}
		}
		for len(arr) <= i {
			arr = append(arr, nil)
		}
		nv, err := setPath(arr[i], path[1:], val)
		if err != nil {
			return nil, err
		}
		arr[i] = nv
		return arr, nil
	case map[string]any:
		arr, ok := v.([]any)
		if v == nil {
			arr, ok = []any{}, true
		}
		if !ok {
			return nil, fmt.Errorf("cannot update field at object index of %s", typeName(v))
		}
		s, e, err := clampSlice(len(arr), key["start"], key["end"])
		if err != nil {
			return nil, err
		}
		cur := append([]any{}, arr[s:e]...)
		nv, err := setPath(cur, path[1:], val)
		if err != nil {
			return nil, err
		}
		nvArr, ok := nv.([]any)
		if !ok {
			return nil, fmt.Errorf("a slice of an array can only be assigned another array")
		}
		out := append([]any{}, arr[:s]...)
		out = append(out, nvArr...)
		return append(out, arr[e:]...), nil
	case nil:
		return setPath(v, append([]any{0}, path[1:]...), val)
	}
	return nil, fmt.Errorf("invalid path component %v", k)
}

func deletePaths(v any, paths [][]any) (any, error) {
	sort.Slice(paths, func(i, j int) bool {
		return compare(toAnySlice(paths[i]), toAnySlice(paths[j])) > 0
	})
	var err error
	for _, p := range paths {
		v, err = deletePath(v, p)
		if err != nil {
			return nil, err
		}
	}
	return v, nil
}

func toAnySlice(p []any) []any { return p }

func deletePath(v any, path []any) (any, error) {
	if len(path) == 0 {
		return nil, nil
	}
	if v == nil {
		return nil, nil
	}
	k := path[0]
	if len(path) == 1 {
		switch x := v.(type) {
		case map[string]any:
			ks, ok := k.(string)
			if !ok {
				return nil, fmt.Errorf("cannot delete field at index of object")
			}
			m := copyObj(x)
			delete(m, ks)
			return m, nil
		case []any:
			switch key := k.(type) {
			case int, float64:
				f, _ := toFloat(key)
				i := int(f)
				if i < 0 {
					i += len(x)
				}
				if i < 0 || i >= len(x) {
					return x, nil
				}
				out := append([]any{}, x[:i]...)
				return append(out, x[i+1:]...), nil
			case map[string]any:
				s, e, err := clampSlice(len(x), key["start"], key["end"])
				if err != nil {
					return nil, err
				}
				out := append([]any{}, x[:s]...)
				return append(out, x[e:]...), nil
			}
			return nil, fmt.Errorf("cannot delete field at object index of array")
		}
		return nil, fmt.Errorf("cannot delete field at index of %s", typeName(v))
	}
	child, err := indexValue(v, k)
	if err != nil {
		return nil, err
	}
	nc, err := deletePath(child, path[1:])
	if err != nil {
		return nil, err
	}
	return setPath(v, []any{k}, nc)
}

func collectPaths(n node, input any, e *env) ([][]any, error) {
	paths := [][]any{}
	err := evalPath(n, input, []any{}, input, e, func(_ any, p []any) error {
		paths = append(paths, p)
		return nil
	})
	return paths, err
}

func evalAssign(n *nAssign, input any, e *env, emit emitFn) error {
	switch n.op {
	case "|=":
		paths, err := collectPaths(n.lhs, input, e)
		if err != nil {
			return err
		}
		v := input
		var toDelete [][]any
		for _, p := range paths {
			old, err := getPath(v, p)
			if err != nil {
				return err
			}
			var nv any
			found := false
			err = eval(n.rhs, old, e, func(r any) error {
				nv = r
				found = true
				return errStop
			})
			if err != nil && !errors.Is(err, errStop) {
				return err
			}
			if !found {
				toDelete = append(toDelete, p)
				continue
			}
			v, err = setPath(v, p, nv)
			if err != nil {
				return err
			}
		}
		if len(toDelete) > 0 {
			v, err = deletePaths(v, toDelete)
			if err != nil {
				return err
			}
		}
		return emit(v)
	case "=":
		return eval(n.rhs, input, e, func(r any) error {
			paths, err := collectPaths(n.lhs, input, e)
			if err != nil {
				return err
			}
			v := input
			for _, p := range paths {
				v, err = setPath(v, p, r)
				if err != nil {
					return err
				}
			}
			return emit(v)
		})
	default:
		op := n.op[:len(n.op)-1]
		return eval(n.rhs, input, e, func(r any) error {
			paths, err := collectPaths(n.lhs, input, e)
			if err != nil {
				return err
			}
			v := input
			for _, p := range paths {
				old, err := getPath(v, p)
				if err != nil {
					return err
				}
				var nv any
				if op == "//" {
					if truthy(old) {
						nv = old
					} else {
						nv = r
					}
				} else {
					nv, err = binop(op, old, r)
					if err != nil {
						return err
					}
				}
				v, err = setPath(v, p, nv)
				if err != nil {
					return err
				}
			}
			return emit(v)
		})
	}
}
EOF
