func getPath(v any, path []any) (any, error) {
	cur := v
	for _, p := range path {
		if cur == nil {
			return nil, nil
		}
		next, err := indexValue(cur, p)
		if err != nil {
			return nil, err
		}
		cur = next
	}
	return cur, nil
}

func setPath(v any, path []any, val any) (any, error) {
	if len(path) == 0 {
		return val, nil
	}
	k := path[0]
	switch key := k.(type) {
	case string:
		var m map[string]any
		switch x := v.(type) {
		case nil:
			m = map[string]any{}
		case map[string]any:
			m = copyObj(x)
		default:
			return nil, fmt.Errorf("expected an object but got: %s", typePreview(v))
		}
		nv, err := setPath(m[key], path[1:], val)
		if err != nil {
			return nil, err
		}
		m[key] = nv
		return m, nil
	case int, float64:
		f, _ := toFloat(key)
		i := int(math.Floor(f))
		var arr []any
		switch x := v.(type) {
		case nil:
			arr = []any{}
		case []any:
			arr = append([]any{}, x...)
		default:
			return nil, fmt.Errorf("expected an array but got: %s", typePreview(v))
		}
		if i < 0 {
			i += len(arr)
			if i < 0 {
				return nil, fmt.Errorf("out of bounds negative array index")
			}
		}
		for len(arr) <= i {
			arr = append(arr, nil)
		}
		nv, err := setPath(arr[i], path[1:], val)
		if err != nil {
			return nil, err
		}
		arr[i] = nv
		return arr, nil
	case map[string]any:
		arr, ok := v.([]any)
		if v == nil {
			arr, ok = []any{}, true
		}
		if !ok {
			return nil, fmt.Errorf("cannot update field at object index of %s", typeName(v))
		}
		s, e, err := clampSlice(len(arr), key["start"], key["end"])
		if err != nil {
			return nil, err
		}
		cur := append([]any{}, arr[s:e]...)
		nv, err := setPath(cur, path[1:], val)
		if err != nil {
			return nil, err
		}
		nvArr, ok := nv.([]any)
		if !ok {
			return nil, fmt.Errorf("a slice of an array can only be assigned another array")
		}
		out := append([]any{}, arr[:s]...)
		out = append(out, nvArr...)
		return append(out, arr[e:]...), nil
	case nil:
		return setPath(v, append([]any{0}, path[1:]...), val)
	}
	return nil, fmt.Errorf("invalid path component %v", k)
}

func deletePaths(v any, paths [][]any) (any, error) {
	sort.Slice(paths, func(i, j int) bool {
		return compare(toAnySlice(paths[i]), toAnySlice(paths[j])) > 0
	})
	var err error
	for _, p := range paths {
		v, err = deletePath(v, p)
		if err != nil {
			return nil, err
		}
	}
	return v, nil
}

func toAnySlice(p []any) []any { return p }

func deletePath(v any, path []any) (any, error) {
	if len(path) == 0 {
		return nil, nil
	}
	if v == nil {
		return nil, nil
	}
	k := path[0]
	if len(path) == 1 {
		switch x := v.(type) {
		case map[string]any:
			ks, ok := k.(string)
			if !ok {
				return nil, fmt.Errorf("cannot delete field at index of object")
			}
			m := copyObj(x)
			delete(m, ks)
			return m, nil
		case []any:
			switch key := k.(type) {
			case int, float64:
				f, _ := toFloat(key)
				i := int(f)
				if i < 0 {
					i += len(x)
				}
				if i < 0 || i >= len(x) {
					return x, nil
				}
				out := append([]any{}, x[:i]...)
				return append(out, x[i+1:]...), nil
			case map[string]any:
				s, e, err := clampSlice(len(x), key["start"], key["end"])
				if err != nil {
					return nil, err
				}
				out := append([]any{}, x[:s]...)
				return append(out, x[e:]...), nil
			}
			return nil, fmt.Errorf("cannot delete field at object index of array")
		}
		return nil, fmt.Errorf("cannot delete field at index of %s", typeName(v))
	}
	child, err := indexValue(v, k)
	if err != nil {
		return nil, err
	}
	nc, err := deletePath(child, path[1:])
	if err != nil {
		return nil, err
	}
	return setPath(v, []any{k}, nc)
}

func collectPaths(n node, input any, e *env) ([][]any, error) {
	paths := [][]any{}
	err := evalPath(n, input, []any{}, input, e, func(_ any, p []any) error {
		paths = append(paths, p)
		return nil
	})
	return paths, err
}

func evalAssign(n *nAssign, input any, e *env, emit emitFn) error {
	switch n.op {
	case "|=":
		paths, err := collectPaths(n.lhs, input, e)
		if err != nil {
			return err
		}
		v := input
		var toDelete [][]any
		for _, p := range paths {
			old, err := getPath(v, p)
			if err != nil {
				return err
			}
			var nv any
			found := false
			err = eval(n.rhs, old, e, func(r any) error {
				nv = r
				found = true
				return errStop
			})
			if err != nil && !errors.Is(err, errStop) {
				return err
			}
			if !found {
				toDelete = append(toDelete, p)
				continue
			}
			v, err = setPath(v, p, nv)
			if err != nil {
				return err
			}
		}
		if len(toDelete) > 0 {
			v, err = deletePaths(v, toDelete)
			if err != nil {
				return err
			}
		}
		return emit(v)
	case "=":
		return eval(n.rhs, input, e, func(r any) error {
			paths, err := collectPaths(n.lhs, input, e)
			if err != nil {
				return err
			}
			v := input
			for _, p := range paths {
				v, err = setPath(v, p, r)
				if err != nil {
					return err
				}
			}
			return emit(v)
		})
	default:
		op := n.op[:len(n.op)-1]
		return eval(n.rhs, input, e, func(r any) error {
			paths, err := collectPaths(n.lhs, input, e)
			if err != nil {
				return err
			}
			v := input
			for _, p := range paths {
				old, err := getPath(v, p)
				if err != nil {
					return err
				}
				var nv any
				if op == "//" {
					if truthy(old) {
						nv = old
					} else {
						nv = r
					}
				} else {
					nv, err = binop(op, old, r)
					if err != nil {
						return err
					}
				}
				v, err = setPath(v, p, nv)
				if err != nil {
					return err
				}
			}
			return emit(v)
		})
	}
}
