func envMap() map[string]any {
	m := map[string]any{}
	for _, kv := range os.Environ() {
		k, v, _ := strings.Cut(kv, "=")
		m[k] = v
	}
	return m
}

func keysOf(input any, emit emitFn) error {
	switch x := input.(type) {
	case map[string]any:
		out := []any{}
		for _, k := range sortedKeys(x) {
			out = append(out, k)
		}
		return emit(out)
	case []any:
		out := make([]any, len(x))
		for i := range x {
			out[i] = i
		}
		return emit(out)
	}
	return fmt.Errorf("keys cannot be applied to: %s", typePreview(input))
}

func strFunc(name string, f func(string) any) builtinFn {
	return func(args []node, e *env, input any, emit emitFn) error {
		s, ok := input.(string)
		if !ok {
			return fmt.Errorf("%s cannot be applied to: %s", name, typePreview(input))
		}
		return emit(f(s))
	}
}

func strArgFunc(name string, f func(string, string) any) builtinFn {
	return func(args []node, e *env, input any, emit emitFn) error {
		return eval(args[0], input, e, func(a any) error {
			s, ok := input.(string)
			as, ok2 := a.(string)
			if !ok || !ok2 {
				return fmt.Errorf("%s(%s) cannot be applied to: %s", name, toJSON(a), typePreview(input))
			}
			return emit(f(s, as))
		})
	}
}

func mathFunc(f func(float64) float64) builtinFn {
	return func(args []node, e *env, input any, emit emitFn) error {
		v, ok := toFloat(input)
		if !ok {
			return fmt.Errorf("number required")
		}
		r := f(v)
		if _, isInt := input.(int); isInt || (r == math.Trunc(r) && !math.IsInf(r, 0)) {
			return emit(normalizeNumber(r))
		}
		return emit(r)
	}
}

func numPred(name string, f func(float64) bool) builtinFn {
	return func(args []node, e *env, input any, emit emitFn) error {
		v, ok := toFloat(input)
		if !ok {
			return fmt.Errorf("%s cannot be applied to: %s", name, typePreview(input))
		}
		return emit(f(v))
	}
}

func byFunc(name string, f func(arr []any, keys []any) any) builtinFn {
	return func(args []node, e *env, input any, emit emitFn) error {
		arr, ok := input.([]any)
		if !ok {
			return fmt.Errorf("%s cannot be applied to: %s", name, typePreview(input))
		}
		keys := make([]any, len(arr))
		for i, v := range arr {
			ks := []any{}
			err := eval(args[0], v, e, func(k any) error {
				ks = append(ks, k)
				return nil
			})
			if err != nil {
				return err
			}
			keys[i] = ks
		}
		return emit(f(arr, keys))
	}
}

type kv struct {
	k any
	v any
}

func sortedPairs(arr, keys []any) []kv {
	pairs := make([]kv, len(arr))
	for i := range arr {
		pairs[i] = kv{keys[i], arr[i]}
	}
	sort.SliceStable(pairs, func(i, j int) bool { return compare(pairs[i].k, pairs[j].k) < 0 })
	return pairs
}

func sortBy(arr, keys []any) any {
	out := []any{}
	for _, p := range sortedPairs(arr, keys) {
		out = append(out, p.v)
	}
	return out
}

func groupBy(arr, keys []any) any {
	out := []any{}
	var cur []any
	var curKey any
	for i, p := range sortedPairs(arr, keys) {
		if i == 0 || compare(p.k, curKey) != 0 {
			if cur != nil {
				out = append(out, cur)
			}
			cur = []any{}
			curKey = p.k
		}
		cur = append(cur, p.v)
	}
	if cur != nil {
		out = append(out, cur)
	}
	return out
}

func uniqueBy(arr, keys []any) any {
	out := []any{}
	var curKey any
	for i, p := range sortedPairs(arr, keys) {
		if i == 0 || compare(p.k, curKey) != 0 {
			out = append(out, p.v)
			curKey = p.k
		}
	}
	return out
}

func minBy(arr, keys []any) any {
	if len(arr) == 0 {
		return nil
	}
	best := 0
	for i := 1; i < len(arr); i++ {
		if compare(keys[i], keys[best]) < 0 {
			best = i
		}
	}
	return arr[best]
}

func maxBy(arr, keys []any) any {
	if len(arr) == 0 {
		return nil
	}
	best := 0
	for i := 1; i < len(arr); i++ {
		if compare(keys[i], keys[best]) >= 0 {
			best = i
		}
	}
	return arr[best]
}

func flattenDepth(arr []any, depth float64) []any {
	out := []any{}
	for _, v := range arr {
		if sub, ok := v.([]any); ok && depth > 0 {
			out = append(out, flattenDepth(sub, depth-1)...)
			continue
		}
		out = append(out, v)
	}
	return out
}

func indices(in, x []any) []any {
	out := []any{}
	if len(x) == 0 {
		return nil
	}
	for i := 0; i+len(x) <= len(in); i++ {
		match := true
		for j := range x {
			if compare(in[i+j], x[j]) != 0 {
				match = false
				break
			}
		}
		if match {
			out = append(out, i)
		}
	}
	return out
}

func containsValue(a, b any) (bool, error) {
	switch x := a.(type) {
	case map[string]any:
		y, ok := b.(map[string]any)
		if !ok {
			return false, fmt.Errorf("%s and %s cannot have their containment checked", typePreview(a), typePreview(b))
		}
		for k, bv := range y {
			av, ok := x[k]
			if !ok {
				return false, nil
			}
			r, err := containsValue(av, bv)
			if err != nil || !r {
				return r, err
			}
		}
		return true, nil
	case []any:
		y, ok := b.([]any)
		if !ok {
			return false, fmt.Errorf("%s and %s cannot have their containment checked", typePreview(a), typePreview(b))
		}
		for _, bv := range y {
			found := false
			for _, av := range x {
				if typeOrder(av) != typeOrder(bv) {
					continue
				}
				r, err := containsValue(av, bv)
				if err == nil && r {
					found = true
					break
				}
			}
			if !found {
				return false, nil
			}
		}
		return true, nil
	case string:
		y, ok := b.(string)
		if !ok {
			return false, fmt.Errorf("%s and %s cannot have their containment checked", typePreview(a), typePreview(b))
		}
		return strings.Contains(x, y), nil
	}
	if typeOrder(a) != typeOrder(b) {
		return false, fmt.Errorf("%s and %s cannot have their containment checked", typePreview(a), typePreview(b))
	}
	return compare(a, b) == 0, nil
}

func compileRe(re, flags any) (*regexp.Regexp, error) {
	rs, ok := re.(string)
	if !ok {
		return nil, fmt.Errorf("%s cannot be matched, as it is not a string", typePreview(re))
	}
	prefix := ""
	if flags != nil {
		fs, ok := flags.(string)
		if !ok {
			return nil, fmt.Errorf("%s is not a string", typePreview(flags))
		}
		for _, f := range fs {
			switch f {
			case 'g', 'n':
			case 'i':
				prefix += "i"
			case 'x':
			case 's':
				prefix += "s"
			case 'm':
				prefix += "s"
			case 'l', 'p':
			default:
				return nil, fmt.Errorf("unsupported regular expression flag: %q", f)
			}
		}
	}
	if prefix != "" {
		rs = "(?" + prefix + ")" + rs
	}
	r, err := regexp.Compile(rs)
	if err != nil {
		return nil, fmt.Errorf("invalid regular expression %q: %s", rs, err)
	}
	return r, nil
}

func matchObject(r *regexp.Regexp, s string, m []int) map[string]any {
	runeOffset := func(b int) int { return utf8.RuneCountInString(s[:b]) }
	out := map[string]any{
		"offset": runeOffset(m[0]),
		"length": utf8.RuneCountInString(s[m[0]:m[1]]),
		"string": s[m[0]:m[1]],
	}
	caps := []any{}
	names := r.SubexpNames()
	for i := 1; i < len(names); i++ {
		c := map[string]any{}
		if names[i] != "" {
			c["name"] = names[i]
		} else {
			c["name"] = nil
		}
		if m[2*i] < 0 {
			c["offset"] = -1
			c["length"] = 0
			c["string"] = nil
		} else {
			c["offset"] = runeOffset(m[2*i])
			c["length"] = utf8.RuneCountInString(s[m[2*i]:m[2*i+1]])
			c["string"] = s[m[2*i]:m[2*i+1]]
		}
		caps = append(caps, c)
	}
	out["captures"] = caps
	return out
}

func applyFormat(name string, v any) (string, error) {
	switch name {
	case "@text":
		if s, ok := v.(string); ok {
			return s, nil
		}
		return toJSON(v), nil
	case "@json":
		return toJSON(v), nil
	case "@html":
		s, _ := applyFormat("@text", v)
		s = html.EscapeString(s)
		s = strings.ReplaceAll(s, "&#34;", "&quot;")
		return s, nil
	case "@uri":
		s, _ := applyFormat("@text", v)
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			c := s[i]
			if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~' {
				b.WriteByte(c)
			} else {
				fmt.Fprintf(&b, "%%%02X", c)
			}
		}
		_ = url.QueryEscape
		return b.String(), nil
	case "@csv", "@tsv":
		arr, ok := v.([]any)
		if !ok {
			return "", fmt.Errorf("cannot %s format: %s, expected an array", name[1:], typePreview(v))
		}
		parts := []string{}
		for _, e := range arr {
			switch x := e.(type) {
			case nil:
				parts = append(parts, "")
			case bool, int, float64:
				parts = append(parts, toJSON(x))
			case string:
				if name == "@csv" {
					parts = append(parts, `"`+strings.ReplaceAll(x, `"`, `""`)+`"`)
				} else {
					r := strings.NewReplacer("\\", "\\\\", "\t", "\\t", "\r", "\\r", "\n", "\\n")
					parts = append(parts, r.Replace(x))
				}
			default:
				return "", fmt.Errorf("cannot %s format: %s, expected an array of scalars", name[1:], typePreview(e))
			}
		}
		sep := ","
		if name == "@tsv" {
			sep = "\t"
		}
		return strings.Join(parts, sep), nil
	case "@sh":
		quote := func(e any) (string, error) {
			switch x := e.(type) {
			case string:
				return "'" + strings.ReplaceAll(x, "'", `'\''`) + "'", nil
			case nil, bool, int, float64:
				return toJSON(x), nil
			}
			return "", fmt.Errorf("can not be escaped for shell: %s", typePreview(e))
		}
		if arr, ok := v.([]any); ok {
			parts := []string{}
			for _, e := range arr {
				q, err := quote(e)
				if err != nil {
					return "", err
				}
				parts = append(parts, q)
			}
			return strings.Join(parts, " "), nil
		}
		return quote(v)
	case "@base64":
		s, _ := applyFormat("@text", v)
		return base64.StdEncoding.EncodeToString([]byte(s)), nil
	case "@base64d":
		s, _ := applyFormat("@text", v)
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			b, err = base64.RawStdEncoding.DecodeString(strings.TrimRight(s, "="))
			if err != nil {
				return "", fmt.Errorf("%s is not valid base64 data", typePreview(v))
			}
		}
		return string(b), nil
	}
	return "", fmt.Errorf("unknown format: %s", name)
}

func timeToBrokenDown(t time.Time, frac float64) []any {
	sec := float64(t.Second()) + frac
	var secv any = normalizeNumber(sec)
	return []any{t.Year(), int(t.Month()) - 1, t.Day(), t.Hour(), t.Minute(), secv, int(t.Weekday()), t.YearDay() - 1}
}

func brokenDownToTime(v any) (time.Time, error) {
	arr, ok := v.([]any)
	if !ok || len(arr) < 6 {
		return time.Time{}, fmt.Errorf("mktime requires array of 6 numbers")
	}
	n := make([]float64, 6)
	for i := 0; i < 6; i++ {
		f, ok := toFloat(arr[i])
		if !ok {
			return time.Time{}, fmt.Errorf("mktime requires array of 6 numbers")
		}
		n[i] = f
	}
	return time.Date(int(n[0]), time.Month(int(n[1])+1), int(n[2]), int(n[3]), int(n[4]), int(n[5]), 0, time.UTC), nil
}

var strftimeMap = map[byte]string{
	'Y': "2006", 'm': "01", 'd': "02", 'H': "15", 'M': "04", 'S': "05", 'y': "06",
	'b': "Jan", 'B': "January", 'a': "Mon", 'A': "Monday", 'Z': "MST", 'z': "-0700",
	'e': "_2", 'I': "03", 'p': "PM", 'j': "002",
}

func strftime(t time.Time, f string) string {
	var b strings.Builder
	for i := 0; i < len(f); i++ {
		if f[i] == '%' && i+1 < len(f) {
			i++
			c := f[i]
			switch c {
			case '%':
				b.WriteByte('%')
			case 's':
				b.WriteString(strconv.FormatInt(t.Unix(), 10))
			case 'T':
				b.WriteString(t.Format("15:04:05"))
			case 'D':
				b.WriteString(t.Format("01/02/06"))
			case 'F':
				b.WriteString(t.Format("2006-01-02"))
			case 'u':
				wd := int(t.Weekday())
				if wd == 0 {
					wd = 7
				}
				b.WriteString(strconv.Itoa(wd))
			case 'w':
				b.WriteString(strconv.Itoa(int(t.Weekday())))
			default:
				if layout, ok := strftimeMap[c]; ok {
					b.WriteString(t.Format(layout))
				} else {
					b.WriteByte('%')
					b.WriteByte(c)
				}
			}
			continue
		}
		b.WriteByte(f[i])
	}
	return b.String()
}

func strptime(s, f string) (time.Time, error) {
	var layout strings.Builder
	for i := 0; i < len(f); i++ {
		if f[i] == '%' && i+1 < len(f) {
			i++
			c := f[i]
			switch c {
			case 'T':
				layout.WriteString("15:04:05")
			case 'F':
				layout.WriteString("2006-01-02")
			case 'z':
				layout.WriteString("-0700")
			case '%':
				layout.WriteByte('%')
			default:
				if l, ok := strftimeMap[c]; ok {
					layout.WriteString(l)
				} else {
					layout.WriteByte('%')
					layout.WriteByte(c)
				}
			}
			continue
		}
		layout.WriteByte(f[i])
	}
	return time.Parse(layout.String(), s)
}
