// Package jq implements a subset of the jq language
package jq

import (
	"context"
	"errors"
	"fmt"
)

// Query runs the jq expression against the input
func Query(ctx context.Context, expr string, in any) (any, error) {
	query, err := parse(expr)
	if err != nil {
		return nil, fmt.Errorf("jq parsing expression %q: %w", expr, err)
	}

	in = normalize(in)

	e := &env{ctx: ctx}
	a := []any{}
	err = eval(query, in, e, func(v any) error {
		a = append(a, v)
		return nil
	})
	if err != nil {
		var be *breakError
		if errors.As(err, &be) {
			err = errors.New("break")
		}
		return nil, fmt.Errorf("jq execution: %w", err)
	}
	if len(a) == 1 {
		return a[0], nil
	}
	return a, nil
}
