			return nil, errors.New("string literal not terminated")
		}
		if strings.HasPrefix(l.src[l.pos:], closing) {
			l.advance(len(closing))
			break
		}
		if strings.HasPrefix(l.src[l.pos:], escape) {
			l.advance(len(escape))
			if l.pos >= len(l.src) {
				return nil, errors.New("string literal not terminated")
			}
			e := l.src[l.pos]
			switch e {
			case 'n':
				cur.WriteByte('\n')
			case 't':
				cur.WriteByte('\t')
			case 'r':
				cur.WriteByte('\r')
			case 'b':
				cur.WriteByte('\b')
			case 'f':
				cur.WriteByte('\f')
			case 'v':
				cur.WriteByte('\v')
			case 'a':
				cur.WriteByte('\a')
			case '/':
				cur.WriteByte('/')
			case '\\':
				cur.WriteByte('\\')
			case '"':
				cur.WriteByte('"')
			case '\'':
				cur.WriteByte('\'')
			case 'u', 'U', 'x':
				n := map[byte]int{'u': 4, 'U': 8, 'x': 2}[e]
				if l.pos+n >= len(l.src) {
					return nil, errors.New("invalid escape")
				}
				v, err := strconv.ParseUint(l.src[l.pos+1:l.pos+1+n], 16, 32)
				if err != nil {
					return nil, errors.New("invalid escape")
				}
				if e == 'x' {
					cur.WriteByte(byte(v))
				} else {
					cur.WriteRune(rune(v))
				}
				l.advance(n)
			case '(':
				depth := 1
				l.advance(1)
				istart := l.pos
				for l.pos < len(l.src) && depth > 0 {
					switch l.src[l.pos] {
					case '(':
						depth++
					case ')':
						depth--
					}
					l.advance(1)
				}
				if cur.Len() > 0 {
					s.parts = append(s.parts, cur.String())
					cur.Reset()
				}
				s.parts = append(s.parts, &cueStrInterp{src: l.src[istart : l.pos-1]})
				continue
			default:
				return nil, fmt.Errorf("unknown escape sequence")
			}
			l.advance(1)
			continue
		}
		cur.WriteByte(l.src[l.pos])
		l.advance(1)
	}
	str := cur.String()
	if multi {
		// remove indentation determined by the closing delimiter line
		lines := strings.Split(str, "\n")
		last := lines[len(lines)-1]
		indent := last
		if strings.TrimSpace(indent) == "" {
			lines = lines[:len(lines)-1]
			for i, ln := range lines {
				lines[i] = strings.TrimPrefix(ln, indent)
			}
			str = strings.Join(lines, "\n")
		}
	}
	if str != "" || len(s.parts) == 0 {
		s.parts = append(s.parts, str)
	}
	return s, nil
}

// AST

type cueExpr interface{}

type (
	cueLit    struct{ v any }
	cueRef    struct{ name string }
	cueSel    struct {
		x    cueExpr
		name string
	}
	cueIndexE struct{ x, idx cueExpr }
	cueBin    struct {
		op   string
		l, r cueExpr
	}
	cueUnary struct {
		op string
		x  cueExpr
	}
	cueDefault struct{ x cueExpr }
	cueList    struct {
		elems []cueExpr
		open  bool
	}
	cueStruct struct{ fields []*cueField }
	cueStrE   struct {
		parts []any
		bytes bool
	}
	cueType struct{ name string }
	cueCall struct {
		fn   cueExpr
		args []cueExpr
	}
)

type cueField struct {
	label    string
	labelX   cueExpr
	value    cueExpr
	hidden   bool
	optional bool
	embed    bool
}

type cueParserS struct {
	toks []cueTok
	pos  int
}

func (p *cueParserS) peek() cueTok { return p.toks[p.pos] }
func (p *cueParserS) next() cueTok {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}

func (p *cueParserS) skipNewlines() {
	for p.peek().kind == ctNewline {
		p.next()
	}
}

func (p *cueParserS) isOp(v string) bool {
	t := p.peek()
	return t.kind == ctOp && t.val == v
}

func tokDesc(t cueTok) string {
	switch t.kind {
	case ctEOF:
		return "EOF"
	case ctNewline:
		return "newline"
	case ctString, ctBytes:
		return "string literal"
	case ctInt, ctFloat:
		return t.val
	case ctIdent:
		return t.val
	}
	return "'" + t.val + "'"
}

func (p *cueParserS) errExpected(what string) error {
	return fmt.Errorf("expected %s, found %s", what, tokDesc(p.peek()))
}

// parseFile parses a whole CUE file
func (p *cueParser) parseFile() (any, error) {
	toks, err := cueLex(p.src)
	if err != nil {
		return nil, err
	}
	ps := &cueParserS{toks: toks}
	ps.skipNewlines()
	// package clause
	if t := ps.peek(); t.kind == ctIdent && t.val == "package" {
		ps.next()
		ps.next()
		ps.skipNewlines()
	}
	for t := ps.peek(); t.kind == ctIdent && t.val == "import"; t = ps.peek() {
		return nil, errors.New("import statements are not supported")
	}
	st, err := ps.parseStructBody(true)
	if err != nil {
		return nil, err
	}
	ev := &cueEval{}
	return ev.evalFile(st)
}

func (p *cueParserS) parseStructBody(top bool) (*cueStruct, error) {
	st := &cueStruct{}
	for {
		p.skipNewlines()
		t := p.peek()
		if t.kind == ctEOF {
			if !top {
				return nil, p.errExpected("'}'")
			}
			return st, nil
		}
		if !top && p.isOp("}") {
			return st, nil
		}
		f, err := p.parseDecl()
		if err != nil {
			return nil, err
		}
		st.fields = append(st.fields, f)
		// separator
		t = p.peek()
		switch {
		case t.kind == ctNewline || p.isOp(","):
			p.next()
		case t.kind == ctEOF:
		case !top && p.isOp("}"):
		default:
			return nil, fmt.Errorf("missing ',' in struct literal")
		}
	}
}

func (p *cueParserS) labelAhead() bool {
	// a declaration is a field if it is LABEL followed by ':' (possibly with ?/!)
	t := p.peek()
	switch t.kind {
	case ctIdent, ctString:
		n := p.toks[p.pos+1]
		if n.kind == ctOp && (n.val == ":" || n.val == "?" || n.val == "!") {
			if n.val != ":" {
				n2 := p.toks[p.pos+2]
				return n2.kind == ctOp && n2.val == ":"
			}
			return true
		}
	case ctOp:
		if t.val == "(" || t.val == "[" {
			// dynamic or pattern label: look for matching close followed by ':'
			depth := 0
			for i := p.pos; i < len(p.toks); i++ {
				tk := p.toks[i]
				if tk.kind == ctOp && (tk.val == "(" || tk.val == "[") {
					depth++
				}
				if tk.kind == ctOp && (tk.val == ")" || tk.val == "]") {
					depth--
					if depth == 0 {
						n := p.toks[i+1]
						return n.kind == ctOp && n.val == ":"
					}
				}
				if tk.kind == ctNewline || tk.kind == ctEOF {
					return false
				}
			}
		}
	}
	return false
}

func (p *cueParserS) parseDecl() (*cueField, error) {
	if p.isOp("...") {
		p.next()
		return &cueField{hidden: true, value: &cueLit{nil}}, nil
	}
	if !p.labelAhead() {
		x, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		return &cueField{embed: true, value: x}, nil
	}
	f := &cueField{}
	t := p.next()
	switch t.kind {
	case ctIdent:
		f.label = t.val
		if strings.HasPrefix(t.val, "_") || strings.HasPrefix(t.val, "#") {
			f.hidden = true
		}
	case ctString:
		s, err := cueStringValue(t.str)
		if err != nil {
			return nil, err
		}
		f.label = s
	case ctOp:
		// dynamic label (expr) or pattern [expr]
		closeOp := ")"
		if t.val == "[" {
			closeOp = "]"
			f.hidden = true
		}
		x, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.isOp(closeOp) {
			return nil, p.errExpected("'" + closeOp + "'")
		}
		p.next()
		f.labelX = x
	}
	if p.isOp("?") || p.isOp("!") {
		if p.next().val == "?" {
			f.optional = true
		}
	}
	if !p.isOp(":") {
		return nil, p.errExpected("':'")
	}
	p.next()
	// nested shorthand a: b: c
	if p.labelAhead() {
		sub, err := p.parseDecl()
		if err != nil {
			return nil, err
		}
		f.value = &cueStruct{fields: []*cueField{sub}}
		return f, nil
	}
	x, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	f.value = x
	return f, nil
}

var cuePrec = map[string]int{
	"|": 1, "&": 2, "||": 3, "&&": 4,
	"==": 5, "!=": 5, "<": 5, "<=": 5, ">": 5, ">=": 5, "=~": 5, "!~": 5,
	"+": 6, "-": 6, "*": 7, "/": 7,
}

func (p *cueParserS) parseExpr() (cueExpr, error) {
	return p.parseBinary(1)
}

func (p *cueParserS) parseBinary(minPrec int) (cueExpr, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t.kind != ctOp {
			return left, nil
		}
		prec, ok := cuePrec[t.val]
		if !ok || prec < minPrec {
			return left, nil
		}
		p.next()
		p.skipNewlines()
		right, err := p.parseBinary(prec + 1)
		if err != nil {
			return nil, err
		}
		left = &cueBin{op: t.val, l: left, r: right}
	}
}

func (p *cueParserS) parseUnary() (cueExpr, error) {
	t := p.peek()
	if t.kind == ctOp {
		switch t.val {
		case "*":
			p.next()
			x, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			return &cueDefault{x}, nil
		case "-", "+", "!", "<", "<=", ">", ">=", "!=", "=~", "!~":
			p.next()
			x, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			return &cueUnary{op: t.val, x: x}, nil
		}
	}
	return p.parsePrimary()
}

func (p *cueParserS) parsePrimary() (cueExpr, error) {
	x, err := p.parseOperand()
	if err != nil {
		return nil, err
	}
	for {
		switch {
		case p.isOp("."):
			p.next()
			t := p.next()
			if t.kind != ctIdent {
				return nil, fmt.Errorf("expected selector, found %s", tokDesc(t))
			}
			x = &cueSel{x: x, name: t.val}
		case p.isOp("["):
			p.next()
			idx, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if !p.isOp("]") {
				return nil, p.errExpected("']'")
			}
			p.next()
			x = &cueIndexE{x: x, idx: idx}
		case p.isOp("("):
			p.next()
			call := &cueCall{fn: x}
			for !p.isOp(")") {
				a, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				call.args = append(call.args, a)
				if p.isOp(",") {
					p.next()
				}
			}
			p.next()
			x = call
		default:
			return x, nil
		}
	}
}

func (p *cueParserS) parseOperand() (cueExpr, error) {
	t := p.peek()
	switch t.kind {
	case ctInt:
		p.next()
		v, err := parseCueInt(t.val)
		if err != nil {
			return nil, err
		}
		return &cueLit{v}, nil
	case ctFloat:
		p.next()
		f, err := strconv.ParseFloat(strings.ReplaceAll(t.val, "_", ""), 64)
		if err != nil {
			return nil, err
		}
		return &cueLit{f}, nil
	case ctString, ctBytes:
		p.next()
		return &cueStrE{parts: t.str.parts, bytes: t.kind == ctBytes}, nil
	case ctIdent:
		p.next()
		switch t.val {
		case "null":
			return &cueLit{nil}, nil
		case "true":
			return &cueLit{true}, nil
		case "false":
			return &cueLit{false}, nil
		case "int", "float", "number", "string", "bytes", "bool", "_", "_|_", "uint", "int8", "int16", "int32", "int64", "uint8", "uint16", "uint32", "uint64", "float32", "float64":
			return &cueType{name: t.val}, nil
		}
		return &cueRef{name: t.val}, nil
	case ctOp:
		switch t.val {
		case "(":
			p.next()
			x, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if !p.isOp(")") {
				return nil, p.errExpected("')'")
			}
			p.next()
			return x, nil
		case "{":
			p.next()
			st, err := p.parseStructBody(false)
			if err != nil {
				return nil, err
			}
			p.next()
			return st, nil
		case "[":
			p.next()
			l := &cueList{}
			for {
				p.skipNewlines()
				if p.isOp("]") {
					p.next()
					return l, nil
				}
				if p.isOp("...") {
					p.next()
					l.open = true
					if !p.isOp("]") && !p.isOp(",") && p.peek().kind != ctNewline {
						if _, err := p.parseExpr(); err != nil {
							return nil, err
						}
					}
				} else {
					x, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					l.elems = append(l.elems, x)
				}
				p.skipNewlines()
				if p.isOp(",") {
					p.next()
					continue
				}
				if p.isOp("]") {
					continue
				}
				return nil, fmt.Errorf("missing ',' before newline in list literal")
			}
		}
	}
	return nil, fmt.Errorf("expected operand, found %s", tokDesc(t))
}

func parseCueInt(s string) (any, error) {
	mult := int64(1)
	switch {
	case strings.HasSuffix(s, "Ki"):
		mult, s = 1<<10, strings.TrimSuffix(s, "Ki")
	case strings.HasSuffix(s, "Mi"):
		mult, s = 1<<20, strings.TrimSuffix(s, "Mi")
	case strings.HasSuffix(s, "Gi"):
		mult, s = 1<<30, strings.TrimSuffix(s, "Gi")
	case strings.HasSuffix(s, "Ti"):
		mult, s = 1<<40, strings.TrimSuffix(s, "Ti")
	case strings.HasSuffix(s, "K"):
		mult, s = 1000, strings.TrimSuffix(s, "K")
	case strings.HasSuffix(s, "M"):
		mult, s = 1000000, strings.TrimSuffix(s, "M")
	case strings.HasSuffix(s, "G"):
		mult, s = 1000000000, strings.TrimSuffix(s, "G")
	case strings.HasSuffix(s, "T"):
		mult, s = 1000000000000, strings.TrimSuffix(s, "T")
	}
	s = strings.ReplaceAll(s, "_", "")
	if strings.Contains(s, ".") || strings.ContainsAny(s, "eE") && !strings.HasPrefix(s, "0x") {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return nil, err
		}
		return int(f * float64(mult)), nil
	}
	b, ok := new(big.Int).SetString(s, 0)
	if !ok {
		return nil, fmt.Errorf("invalid number %s", s)
	}
	b.Mul(b, big.NewInt(mult))
	if b.IsInt64() {
		return int(b.Int64()), nil
	}
	f, _ := new(big.Float).SetInt(b).Float64()
	return f, nil
}

func cueStringValue(s *cueStrLit) (string, error) {
	var b strings.Builder
	for _, p := range s.parts {
		str, ok := p.(string)
		if !ok {
			return "", errors.New("interpolation not allowed in label")
		}
		b.WriteString(str)
	}
	return b.String(), nil
}

// evaluator

type cueIncomplete struct{ desc string }

type cueBytesV []byte

type cueEval struct {
	scopes []*cueScope
	depth  int
}

type cueScope struct {
	st     *cueStruct
	values map[string]any
	inProg map[string]bool
	parent *cueScope
}

func (ev *cueEval) evalFile(st *cueStruct) (any, error) {
	// if the file is a single embedded expression, return it
	if len(st.fields) == 1 && st.fields[0].embed {
		v, err := ev.eval(st.fields[0].value, &cueScope{st: st, values: map[string]any{}, inProg: map[string]bool{}})
		if err != nil {
			return nil, err
		}
		return cueExport(v, "")
	}
	v, err := ev.evalStruct(st, nil)
	if err != nil {
		return nil, err
	}
	return cueExport(v, "")
}

func cueExport(v any, path string) (any, error) {
	switch x := v.(type) {
	case *cueIncomplete:
		if path == "" {
			return nil, fmt.Errorf("incomplete value %s", x.desc)
		}
		return nil, fmt.Errorf("%s: incomplete value %s", path, x.desc)
	case *cueObj:
		out := map[string]any{}
		for _, k := range x.order {
			if x.hidden[k] {
				continue
			}
			sub := k
			if path != "" {
				sub = path + "." + k
			}
			ev, err := cueExport(x.fields[k], sub)
			if err != nil {
				if x.optional[k] {
					continue
				}
				return nil, err
			}
			out[k] = ev
		}
		return out, nil
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			ev, err := cueExport(e, fmt.Sprintf("%s.%d", path, i))
			if err != nil {
				return nil, err
			}
			out[i] = ev
		}
		return out, nil
	case cueBytesV:
		return []byte(x), nil
	case *cueDisj:
		if x.def != nil {
			return cueExport(x.def, path)
		}
		if len(x.vals) == 1 {
			return cueExport(x.vals[0], path)
		}
		return nil, fmt.Errorf("%s: incomplete value %s", path, "disjunction")
	}
	return v, nil
}

type cueObj struct {
	fields   map[string]any
	order    []string
	hidden   map[string]bool
	optional map[string]bool
}

type cueDisj struct {
	vals []any
	def  any
}

func (ev *cueEval) evalStruct(st *cueStruct, parent *cueScope) (*cueObj, error) {
	ev.depth++
	defer func() { ev.depth-- }()
	if ev.depth > 100 {
		return nil, errors.New("structural cycle")
	}
	scope := &cueScope{st: st, values: map[string]any{}, inProg: map[string]bool{}, parent: parent}
	obj := &cueObj{fields: map[string]any{}, hidden: map[string]bool{}, optional: map[string]bool{}}
	for _, f := range st.fields {
		if f.embed {
			v, err := ev.eval(f.value, scope)
			if err != nil {
				return nil, err
			}
			if o, ok := v.(*cueObj); ok {
				for _, k := range o.order {
					if err := obj.set(k, o.fields[k], o.hidden[k], o.optional[k]); err != nil {
						return nil, err
					}
				}
				continue
			}
			return nil, errors.New("embedding of non-struct values is not supported")
		}
		label := f.label
		if f.labelX != nil {
			if f.hidden {
				continue
			}
			lv, err := ev.eval(f.labelX, scope)
			if err != nil {
				return nil, err
			}
			s, ok := lv.(string)
			if !ok {
				return nil, errors.New("invalid label type")
			}
			label = s
		}
		if label == "" && f.hidden {
			continue
		}
		v, err := ev.fieldValue(scope, label)
		if err != nil {
			return nil, err
		}
		if err := obj.set(label, v, f.hidden, f.optional); err != nil {
			return nil, err
		}
	}
	return obj, nil
}

func (o *cueObj) set(k string, v any, hidden, optional bool) error {
	if old, ok := o.fields[k]; ok {
		u, err := cueUnify(old, v)
		if err != nil {
			return fmt.Errorf("%s: %w", k, err)
		}
		o.fields[k] = u
		if !optional {
			o.optional[k] = false
		}
		return nil
	}
	o.fields[k] = v
	o.order = append(o.order, k)
	o.hidden[k] = hidden
	o.optional[k] = optional
	return nil
}

// fieldValue computes the unified value of all fields with the label in the scope
func (ev *cueEval) fieldValue(scope *cueScope, label string) (any, error) {
	if v, ok := scope.values[label]; ok {
		return v, nil
	}
	if scope.inProg[label] {
		return &cueIncomplete{desc: "cycle"}, nil
	}
	scope.inProg[label] = true
	defer delete(scope.inProg, label)
	var result any
	found := false
	for _, f := range scope.st.fields {
		if f.embed || f.labelX != nil || f.label != label {
			continue
		}
		v, err := ev.eval(f.value, scope)
		if err != nil {
			return nil, err
		}
		if !found {
			result = v
			found = true
			continue
		}
		result, err = cueUnify(result, v)
		if err != nil {
			return nil, err
		}
	}
	if !found {
		return nil, fmt.Errorf("reference %q not found", label)
	}
	scope.values[label] = result
	return result, nil
}

func (ev *cueEval) lookup(name string, scope *cueScope) (any, error) {
	for s := scope; s != nil; s = s.parent {
		for _, f := range s.st.fields {
			if f.label == name && !f.embed && f.labelX == nil {
				return ev.fieldValue(s, name)
			}
		}
	}
	return nil, fmt.Errorf("reference %q not found", name)
}

func (ev *cueEval) eval(x cueExpr, scope *cueScope) (any, error) {
	switch x := x.(type) {
	case *cueLit:
		return x.v, nil
	case *cueType:
		return &cueIncomplete{desc: x.name}, nil
	case *cueStrE:
		var b strings.Builder
		for _, part := range x.parts {
			switch v := part.(type) {
			case string:
				b.WriteString(v)
			case *cueStrInterp:
				toks, err := cueLex(v.src)
				if err != nil {
					return nil, err
				}
				ps := &cueParserS{toks: toks}
				e, err := ps.parseExpr()
				if err != nil {
					return nil, err
				}
				val, err := ev.eval(e, scope)
				if err != nil {
					return nil, err
				}
				switch vv := val.(type) {
				case string:
					b.WriteString(vv)
				case int:
					b.WriteString(strconv.Itoa(vv))
				case float64:
					b.WriteString(cueFloat(vv))
				case bool:
					b.WriteString(strconv.FormatBool(vv))
				case *cueIncomplete:
					return vv, nil
				default:
					return nil, errors.New("invalid interpolation")
				}
			}
		}
		if x.bytes {
			return cueBytesV(b.String()), nil
		}
		return b.String(), nil
	case *cueRef:
		return ev.lookup(x.name, scope)
	case *cueSel:
		v, err := ev.eval(x.x, scope)
		if err != nil {
			return nil, err
		}
		o, ok := v.(*cueObj)
		if !ok {
			return nil, fmt.Errorf("invalid selector %s", x.name)
		}
		fv, ok := o.fields[x.name]
		if !ok {
			return nil, fmt.Errorf("undefined field: %s", x.name)
		}
		return fv, nil
	case *cueIndexE:
		v, err := ev.eval(x.x, scope)
		if err != nil {
			return nil, err
		}
		idx, err := ev.eval(x.idx, scope)
		if err != nil {
			return nil, err
		}
		switch c := v.(type) {
		case []any:
			i, ok := idx.(int)
			if !ok || i < 0 || i >= len(c) {
				return nil, fmt.Errorf("index out of range")
			}
			return c[i], nil
		case *cueObj:
			s, ok := idx.(string)
			if !ok {
				return nil, fmt.Errorf("invalid index")
			}
			fv, ok := c.fields[s]
			if !ok {
				return nil, fmt.Errorf("undefined field: %s", s)
			}
			return fv, nil
		}
		return nil, errors.New("invalid index operation")
	case *cueStruct:
		return ev.evalStruct(x, scope)
	case *cueList:
		out := []any{}
		for _, e := range x.elems {
			v, err := ev.eval(e, scope)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case *cueDefault:
		v, err := ev.eval(x.x, scope)
		if err != nil {
			return nil, err
		}
		return &cueDisj{vals: []any{v}, def: v}, nil
	case *cueUnary:
		v, err := ev.eval(x.x, scope)
		if err != nil {
			return nil, err
		}
		switch x.op {
		case "-":
			switch n := v.(type) {
			case int:
				return -n, nil
			case float64:
				return -n, nil
			}
		case "+":
			return v, nil
		case "!":
			if b, ok := v.(bool); ok {
				return !b, nil
			}
		default:
			return &cueIncomplete{desc: x.op + " constraint"}, nil
		}
		return nil, fmt.Errorf("invalid operand for unary %s", x.op)
	case *cueBin:
		l, err := ev.eval(x.l, scope)
		if err != nil {
			return nil, err
		}
		r, err := ev.eval(x.r, scope)
		if err != nil {
			return nil, err
		}
		return cueBinop(x.op, l, r)
	case *cueCall:
		return nil, errors.New("function calls are not supported")
	}
	return nil, fmt.Errorf("unsupported expression")
}

func cueBinop(op string, l, r any) (any, error) {
	switch op {
	case "&":
		return cueUnify(l, r)
	case "|":
		d := &cueDisj{}
		for _, v := range []any{l, r} {
			if dj, ok := v.(*cueDisj); ok {
				d.vals = append(d.vals, dj.vals...)
				if dj.def != nil && d.def == nil {
					d.def = dj.def
				}
				continue
			}
			d.vals = append(d.vals, v)
		}
		return d, nil
	}
	l = cueResolve(l)
	r = cueResolve(r)
	if _, ok := l.(*cueIncomplete); ok {
		return l, nil
	}
	if _, ok := r.(*cueIncomplete); ok {
		return r, nil
	}
	switch op {
	case "+":
		switch a := l.(type) {
		case int:
			switch b := r.(type) {
			case int:
				return a + b, nil
			case float64:
				return float64(a) + b, nil
			}
		case float64:
			switch b := r.(type) {
			case int:
				return a + float64(b), nil
			case float64:
				return a + b, nil
			}
		case string:
			if b, ok := r.(string); ok {
				return a + b, nil
			}
		case []any:
			if b, ok := r.([]any); ok {
				return append(append([]any{}, a...), b...), nil
			}
		}
	case "-", "*", "/":
		af, aok := cueNum(l)
		bf, bok := cueNum(r)
		if aok && bok {
			_, ai := l.(int)
			_, bi := r.(int)
			switch op {
			case "-":
				if ai && bi {
					return l.(int) - r.(int), nil
				}
				return af - bf, nil
			case "*":
				if ai && bi {
					return l.(int) * r.(int), nil
				}
				return af * bf, nil
			case "/":
				if bf == 0 {
					return nil, errors.New("division by zero")
				}
				return af / bf, nil
			}
		}
		if op == "*" {
			if s, ok := l.(string); ok {
				if n, ok := r.(int); ok {
					return strings.Repeat(s, n), nil
				}
			}
		}
	case "==":
		return cueEqual(l, r), nil
	case "!=":
		return !cueEqual(l, r), nil
	case "<", "<=", ">", ">=":
		af, aok := cueNum(l)
		bf, bok := cueNum(r)
		if aok && bok {
			switch op {
			case "<":
				return af < bf, nil
			case "<=":
				return af <= bf, nil
			case ">":
				return af > bf, nil
			case ">=":
				return af >= bf, nil
			}
		}
		as, aok := l.(string)
		bs, bok := r.(string)
		if aok && bok {
			switch op {
			case "<":
				return as < bs, nil
			case "<=":
				return as <= bs, nil
			case ">":
				return as > bs, nil
			case ">=":
				return as >= bs, nil
			}
		}
	case "&&", "||":
		ab, aok := l.(bool)
		bb, bok := r.(bool)
		if aok && bok {
			if op == "&&" {
				return ab && bb, nil
			}
			return ab || bb, nil
		}
	}
	return nil, fmt.Errorf("invalid operands %s and %s to '%s'", cueKindName(l), cueKindName(r), op)
}

func cueResolve(v any) any {
	if d, ok := v.(*cueDisj); ok {
		if d.def != nil {
			return d.def
		}
		if len(d.vals) == 1 {
			return d.vals[0]
		}
	}
	return v
}

func cueKindName(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "bool"
	case int:
		return "int"
	case float64:
		return "float"
	case string:
		return "string"
	case cueBytesV:
		return "bytes"
	case []any:
		return "list"
	case *cueObj:
		return "struct"
	}
	return "_"
}

func cueNum(v any) (float64, bool) {
	switch n := v.(type) {
	case int:
		return float64(n), true
	case float64:
		return n, true
	}
	return 0, false
}

func cueEqual(a, b any) bool {
	a, b = cueResolve(a), cueResolve(b)
	if af, ok := cueNum(a); ok {
		if bf, ok := cueNum(b); ok {
			return af == bf
		}
		return false
	}
	switch x := a.(type) {
	case nil:
		return b == nil
	case bool, string:
		return a == b
	case cueBytesV:
		y, ok := b.(cueBytesV)
		return ok && string(x) == string(y)
	case []any:
		y, ok := b.([]any)
		if !ok || len(x) != len(y) {
			return false
		}
		for i := range x {
			if !cueEqual(x[i], y[i]) {
				return false
			}
		}
		return true
	case *cueObj:
		y, ok := b.(*cueObj)
		if !ok || len(x.fields) != len(y.fields) {
			return false
		}
		for k, v := range x.fields {
			if !cueEqual(v, y.fields[k]) {
				return false
			}
		}
		return true
	}
	return false
}

func cueUnify(a, b any) (any, error) {
	if ia, ok := a.(*cueIncomplete); ok {
		if _, ok := b.(*cueIncomplete); ok {
			return a, nil
		}
		if cueTypeMatches(ia.desc, b) {
			return b, nil
		}
		return nil, fmt.Errorf("conflicting values %s and %s", ia.desc, cueKindName(b))
	}
	if ib, ok := b.(*cueIncomplete); ok {
		if cueTypeMatches(ib.desc, a) {
			return a, nil
		}
		return nil, fmt.Errorf("conflicting values %s and %s", cueKindName(a), ib.desc)
	}
	if da, ok := a.(*cueDisj); ok {
		return cueUnifyDisj(da, b)
	}
	if db, ok := b.(*cueDisj); ok {
		return cueUnifyDisj(db, a)
	}
	oa, aok := a.(*cueObj)
	ob, bok := b.(*cueObj)
	if aok && bok {
		out := &cueObj{fields: map[string]any{}, hidden: map[string]bool{}, optional: map[string]bool{}}
		for _, k := range oa.order {
			if err := out.set(k, oa.fields[k], oa.hidden[k], oa.optional[k]); err != nil {
				return nil, err
			}
		}
		for _, k := range ob.order {
			if err := out.set(k, ob.fields[k], ob.hidden[k], ob.optional[k]); err != nil {
				return nil, err
			}
		}
		return out, nil
	}
	la, aok := a.([]any)
	lb, bok := b.([]any)
	if aok && bok {
		if len(la) != len(lb) {
			return nil, fmt.Errorf("incompatible list lengths (%d and %d)", len(la), len(lb))
		}
		out := make([]any, len(la))
		for i := range la {
			u, err := cueUnify(la[i], lb[i])
			if err != nil {
				return nil, err
			}
			out[i] = u
		}
		return out, nil
	}
	if cueEqual(a, b) {
		if _, ok := a.(float64); ok {
			return a, nil
		}
		return b, nil
	}
	return nil, fmt.Errorf("conflicting values %s and %s", cueValueString(a), cueValueString(b))
}

func cueUnifyDisj(d *cueDisj, other any) (any, error) {
	out := &cueDisj{}
	for _, v := range d.vals {
		u, err := cueUnify(v, other)
		if err == nil {
			out.vals = append(out.vals, u)
			if d.def != nil && cueEqual(v, d.def) {
				out.def = u
			}
		}
	}
	if len(out.vals) == 0 {
		return nil, fmt.Errorf("empty disjunction")
	}
	if len(out.vals) == 1 {
		return out.vals[0], nil
	}
	return out, nil
}

func cueValueString(v any) string {
	switch x := v.(type) {
	case string:
		return strconv.Quote(x)
	case int:
		return strconv.Itoa(x)
	case float64:
		return cueFloat(x)
	case bool:
		return strconv.FormatBool(x)
	case nil:
		return "null"
	}
	return cueKindName(v)
}

func cueTypeMatches(t string, v any) bool {
	v = cueResolve(v)
	switch t {
	case "_":
		return true
	case "int", "uint", "int8", "int16", "int32", "int64", "uint8", "uint16", "uint32", "uint64":
		_, ok := v.(int)
		return ok
	case "float", "float32", "float64":
		_, ok := v.(float64)
		return ok
	case "number":
		_, ok := cueNum(v)
		return ok
	case "string":
		_, ok := v.(string)
		return ok
	case "bytes":
		_, ok := v.(cueBytesV)
		return ok
	case "bool":
		_, ok := v.(bool)
		return ok
	}
	return true
}

