type metaClient struct {
	endpoint string
	timeout  time.Duration
	headers  map[string]string
	mu       sync.Mutex
	cache    map[string]string
	nonCloud bool
}

func newMetaClient(endpoint, timeoutEnv string, headers map[string]string) *metaClient {
	timeout := 500 * time.Millisecond
	if t := os.Getenv(timeoutEnv); t != "" {
		if n, err := strconv.Atoi(t); err == nil {
			timeout = time.Duration(n) * time.Millisecond
		}
	}
	return &metaClient{endpoint: strings.TrimSuffix(endpoint, "/"), timeout: timeout, headers: headers, cache: map[string]string{}}
}

func returnDefault(def []string) string {
	if len(def) > 0 {
		return def[0]
	}
	return ""
}

func (m *metaClient) get(ctx context.Context, path string, def ...string) (string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	u := m.endpoint + path
	if v, ok := m.cache[u]; ok {
		return v, nil
	}
	if m.nonCloud {
		return returnDefault(def), nil
	}
	cctx, cancel := context.WithTimeout(ctx, m.timeout)
	defer cancel()
	req, err := http.NewRequestWithContext(cctx, http.MethodGet, u, nil)
	if err != nil {
		return returnDefault(def), nil
	}
	for k, v := range m.headers {
		req.Header.Set(k, v)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		m.nonCloud = true
		return returnDefault(def), nil
	}
	defer resp.Body.Close()
	if resp.StatusCode > 399 {
		return returnDefault(def), nil
	}
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		return returnDefault(def), nil
	}
	v := strings.TrimSpace(string(b))
	m.cache[u] = v
	return v, nil
}

