// String -
func (a *IPAddr) String() string {
	ones, bits := a.Mask.Size()
	ipStr := a.IP.String()
	if a.Port != 0 {
		if a.v6 {
			return fmt.Sprintf("[%s]:%d", ipStr, a.Port)
		}
		return fmt.Sprintf("%s:%d", ipStr, a.Port)
	}
	if ones == bits {
		return ipStr
	}
	return fmt.Sprintf("%s/%d", ipStr, ones)
}

