	ones, _ := a.Mask.Size()
	return fmt.Sprintf("%s/%d", a.NetworkIP().String(), ones)
}

// Broadcast returns the broadcast address
func (a *IPAddr) Broadcast() net.IP {
	ip := make(net.IP, len(a.IP))
	for i := range a.IP {
		ip[i] = a.IP[i] | ^a.Mask[i]
	}
	return ip
}

