// GetAllInterfaces returns all addresses on all interfaces
func GetAllInterfaces() (IfAddrs, error) {
	ifs, err := net.Interfaces()
	if err != nil {
		return nil, err
	}
	out := IfAddrs{}
	for _, intf := range ifs {
		addrs, err := intf.Addrs()
		if err != nil {
			return nil, err
		}
		for _, a := range addrs {
			ipnet, ok := a.(*net.IPNet)
			if !ok {
				continue
			}
			ia := newIPAddr(ipnet)
			out = append(out, IfAddr{SockAddr: ia, Interface: intf})
		}
	}
	return out, nil
}

func newIPAddr(n *net.IPNet) *IPAddr {
	if ip4 := n.IP.To4(); ip4 != nil {
		mask := n.Mask
		if len(mask) == 16 {
			mask = mask[12:]
		}
		return &IPAddr{IP: ip4, Mask: mask}
	}
	return &IPAddr{IP: n.IP.To16(), Mask: n.Mask, v6: true}
}

// defaultInterfaceName finds the name of the interface with the default route
func defaultInterfaceName() (string, error) {
	f, err := os.Open("/proc/net/route")
	if err != nil {
		return "", err
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	first := true
	for s.Scan() {
		if first {
			first = false
			continue
		}
		fields := strings.Fields(s.Text())
		if len(fields) < 8 {
			continue
		}
		if fields[1] == "00000000" && fields[7] == "00000000" {
			return fields[0], nil
		}
	}
	return "", errors.New("No default route found")
}

// GetDefaultInterfaces returns the addresses on the default interface
func GetDefaultInterfaces() (IfAddrs, error) {
	name, err := defaultInterfaceName()
	if err != nil {
		return nil, err
	}
	all, err := GetAllInterfaces()
	if err != nil {
		return nil, err
	}
	out := IfAddrs{}
	for _, a := range all {
		if a.Name == name {
			out = append(out, a)
		}
	}
	return out, nil
}

// GetPrivateInterfaces returns private, forwardable addresses on the default interface
func GetPrivateInterfaces() (IfAddrs, error) {
	defs, err := GetDefaultInterfaces()
	if err != nil {
		return nil, err
	}
	out := IfAddrs{}
	for _, a := range defs {
		ip := ipOf(a)
		if ip == nil || a.Flags&net.FlagUp == 0 {
			continue
		}
		if isForwardable(ip) && isRFC(6890, ip) {
			out = append(out, a)
		}
	}
	return out, nil
}

