// Sort sorts the IfAddrs by the given (comma-separated) selectors
func Sort(selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	sortedIfs := append(IfAddrs{}, inputIfAddrs...)
	clauses := strings.Split(selectorParam, ",")
	type cmp func(a, b IfAddr) int
	cmps := []cmp{}
	for _, c := range clauses {
		c = strings.TrimSpace(c)
		desc := false
		if strings.HasPrefix(c, "-") {
			desc = true
			c = c[1:]
		} else if strings.HasPrefix(c, "+") {
			c = c[1:]
		}
		var f cmp
		switch strings.ToLower(c) {
		case "address":
			f = func(a, b IfAddr) int {
				ia, ib := ipOf(a), ipOf(b)
				if ia == nil || ib == nil {
					return 0
				}
				if a.Type() != b.Type() {
					return 0
				}
				return ipToBig(ia).Cmp(ipToBig(ib))
			}
		case "default":
			def, _ := defaultInterfaceName()
			f = func(a, b IfAddr) int {
				ad, bd := a.Name == def, b.Name == def
				switch {
				case ad && !bd:
					return -1
				case !ad && bd:
					return 1
				}
				return 0
			}
		case "name":
			f = func(a, b IfAddr) int { return strings.Compare(a.Name, b.Name) }
		case "port":
			f = func(a, b IfAddr) int {
				pa, pb := portOf(a), portOf(b)
				switch {
				case pa < pb:
					return -1
				case pa > pb:
					return 1
				}
				return 0
			}
		case "private":
			f = func(a, b IfAddr) int {
				ap, bp := isRFC(6890, ipOf(a)), isRFC(6890, ipOf(b))
				switch {
				case ap && !bp:
					return -1
				case !ap && bp:
					return 1
				}
				return 0
			}
		case "size":
			f = func(a, b IfAddr) int {
				sa, sb := sizeOf(a), sizeOf(b)
				switch {
				case sa > sb:
					return -1
				case sa < sb:
					return 1
				}
				return 0
			}
		case "type":
			f = func(a, b IfAddr) int {
				ta, tb := typeOrder(a.Type()), typeOrder(b.Type())
				switch {
				case ta < tb:
					return -1
				case ta > tb:
					return 1
				}
				return 0
			}
		default:
			return nil, fmt.Errorf("invalid sort selector %q", c)
		}
		if desc {
			orig := f
			f = func(a, b IfAddr) int { return -orig(a, b) }
		}
		cmps = append(cmps, f)
	}
	sort.SliceStable(sortedIfs, func(i, j int) bool {
		for _, c := range cmps {
			if r := c(sortedIfs[i], sortedIfs[j]); r != 0 {
				return r < 0
			}
		}
		return false
	})
	return sortedIfs, nil
}

func typeOrder(t SockAddrType) int {
	switch t {
	case TypeUnix:
		return 0
	case TypeIPv4:
		return 1
	case TypeIPv6:
		return 2
	}
	return 3
}

func portOf(a IfAddr) uint16 {
	if ia, ok := a.SockAddr.(*IPAddr); ok {
		return ia.Port
	}
	return 0
}

func sizeOf(a IfAddr) int {
	if ia, ok := a.SockAddr.(*IPAddr); ok {
		ones, bits := ia.Mask.Size()
		return bits - ones
	}
	return 0
}

