			}
		}
		return false, nil
	case "size":
		n, err := strconv.Atoi(value)
		if err != nil {
			return false, err
		}
		if ia, ok := a.SockAddr.(*IPAddr); ok {
			ones, _ := ia.Mask.Size()
			return ones == n, nil
		}
		return false, nil
	case "type":
		for _, t := range strings.Split(value, "|") {
			if strings.EqualFold(a.Type().String(), t) {
				return true, nil
			}
		}
		return false, nil
	}
	return false, fmt.Errorf("invalid include/exclude selector %q", selector)
}

// Include filters the IfAddrs to those matching the selector
func Include(selectorName, selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	out := IfAddrs{}
	for _, a := range inputIfAddrs {
		ok, err := matches(selectorName, selectorParam, a)
		if err != nil {
			return nil, err
		}
		if ok {
			out = append(out, a)
		}
	}
	return out, nil
}

// Exclude filters out the IfAddrs matching the selector
func Exclude(selectorName, selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	out := IfAddrs{}
	for _, a := range inputIfAddrs {
		ok, err := matches(selectorName, selectorParam, a)
		if err != nil {
			return nil, err
		}
		if !ok {
			out = append(out, a)
		}
	}
	return out, nil
}

// Attr returns the named attribute of the IfAddr
func Attr(selectorName string, ifAddrs any) (string, error) {
	switch v := ifAddrs.(type) {
	case IfAddr:
		return ifAttr(selectorName, v)
	case IfAddrs:
		if len(v) == 0 {
			return "", nil
		}
		return ifAttr(selectorName, v[0])
	}
	return "", fmt.Errorf("unable to obtain attribute %s from type %T (%v)", selectorName, ifAddrs, ifAddrs)
}

func ifAttr(name string, a IfAddr) (string, error) {
	ia, _ := a.SockAddr.(*IPAddr)
	switch strings.ToLower(name) {
	case "name":
		return a.Name, nil
	case "flags":
		return a.Flags.String(), nil
	case "hardwareaddr", "hardware_addr":
		return a.HardwareAddr.String(), nil
	case "mtu":
		return strconv.Itoa(a.MTU), nil
	case "type":
		return a.Type().String(), nil
	case "string":
		return a.SockAddr.String(), nil
	}
	if ia == nil {
		return "", fmt.Errorf("unsupported attribute name %q", name)
	}
	ones, bits := ia.Mask.Size()
	switch strings.ToLower(name) {
	case "address":
		return ia.IP.String(), nil
	case "network":
		return ia.NetworkIP().String(), nil
	case "mask", "netmask":
		if !ia.v6 {
			return net.IP(ia.Mask).String(), nil
		}
		return ia.Mask.String(), nil
	case "size":
		return new(big.Int).Lsh(big.NewInt(1), uint(bits-ones)).String(), nil
	case "port":
		return strconv.Itoa(int(ia.Port)), nil
	case "host":
		return fmt.Sprintf("%s/%d", ia.IP.String(), bits), nil
	case "broadcast":
		if ia.v6 {
			return "", nil
		}
		return ia.Broadcast().String(), nil
	case "first_usable":
		n := ipToBig(ia.NetworkIP())
		if bits-ones > 1 {
			n.Add(n, big.NewInt(1))
		}
		return bigToIP(n, ia.v6).String(), nil
	case "last_usable":
		b := ipToBig(ia.Broadcast())
		if bits-ones > 1 {
			b.Sub(b, big.NewInt(1))
		}
		return bigToIP(b, ia.v6).String(), nil
	case "octets":
		parts := []string{}
		for _, b := range ia.IP {
			parts = append(parts, strconv.Itoa(int(b)))
		}
		return strings.Join(parts, " "), nil
	case "uint32":
		if ia.v6 {
			return "", fmt.Errorf("unsupported attribute name %q", name)
		}
		return strconv.FormatUint(uint64(binary.BigEndian.Uint32(ia.IP.To4())), 10), nil
	}
	return "", fmt.Errorf("unsupported attribute name %q", name)
}

func bigToIP(n *big.Int, v6 bool) net.IP {
	l := 4
	if v6 {
		l = 16
	}
	b := n.Bytes()
	out := make([]byte, l)
	copy(out[l-len(b):], b)
	return net.IP(out)
}

// Join joins the named attribute of each IfAddr with the separator
func Join(selectorName, joinString string, inputIfAddrs IfAddrs) (string, error) {
	out := []string{}
	for _, a := range inputIfAddrs {
		s, err := ifAttr(selectorName, a)
		if err != nil {
			return "", err
		}
		out = append(out, s)
	}
	return strings.Join(out, joinString), nil
}

// Limit -
func Limit(lim uint, in IfAddrs) (IfAddrs, error) {
	if int(lim) > len(in) {
		lim = uint(len(in))
	}
	return in[:lim], nil
}

// Offset -
func Offset(off int, in IfAddrs) (IfAddrs, error) {
	switch {
	case off > 0:
		if off > len(in) {
			return nil, fmt.Errorf("unable to seek past the end of the interface array: offset (%d) exceeds the number of interfaces (%d)", off, len(in))
		}
		return in[off:], nil
	case off < 0:
		end := len(in) + off
		if end < 0 {
			return nil, fmt.Errorf("unable to seek past the beginning of the interface array: offset (%d) exceeds the number of interfaces (%d)", off, len(in))
		}
		return in[end:], nil
	}
	return in, nil
}

// Unique removes duplicates by the given attribute
func Unique(selectorName string, in IfAddrs) (IfAddrs, error) {
	seen := map[string]bool{}
	out := IfAddrs{}
	for _, a := range in {
		k, err := ifAttr(selectorName, a)
		if err != nil {
			return nil, err
		}
		if seen[k] {
			continue
		}
		seen[k] = true
		out = append(out, a)
	}
	return out, nil
}

// Math applies an operation to each address
func Math(operation, value string, in IfAddrs) (IfAddrs, error) {
	out := IfAddrs{}
	for _, a := range in {
		ia, ok := a.SockAddr.(*IPAddr)
		if !ok {
			out = append(out, a)
			continue
		}
		n, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("unable to convert %q to int for operation %q: %v", value, operation, err)
		}
		ip := ipToBig(ia.IP)
		switch strings.ToLower(operation) {
		case "address":
			ip.Add(ip, big.NewInt(n))
		case "network":
			nw := ipToBig(ia.NetworkIP())
			ones, bits := ia.Mask.Size()
			size := new(big.Int).Lsh(big.NewInt(1), uint(bits-ones))
			off := new(big.Int).Mod(big.NewInt(n), size)
			ip = nw.Add(nw, off)
		default:
			return nil, fmt.Errorf("unsupported math operation: %q", operation)
		}
		nia := &IPAddr{IP: bigToIP(ip, ia.v6), Mask: ia.Mask, Port: ia.Port, v6: ia.v6}
		out = append(out, IfAddr{SockAddr: nia, Interface: a.Interface})
	}
	return out, nil
}

func joinIPs(in IfAddrs) string {
	var b bytes.Buffer
	for i, a := range in {
		if i > 0 {
			b.WriteByte(' ')
		}
		b.WriteString(ipOf(a).String())
	}
	return b.String()
}

// GetPrivateIP -
func GetPrivateIP() (string, error) {
	ifs, err := GetPrivateInterfaces()
	if err != nil {
		return "", err
	}
	if len(ifs) == 0 {
		return "", nil
	}
	return ipOf(ifs[0]).String(), nil
}

// GetPrivateIPs -
func GetPrivateIPs() (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	out := IfAddrs{}
	for _, a := range ifs {
		ip := ipOf(a)
		if ip != nil && ip.To4() != nil && isRFC(6890, ip) && isForwardable(ip) && a.Flags&net.FlagUp != 0 {
			out = append(out, a)
		}
	}
	return joinIPs(out), nil
}

// GetPublicIP -
func GetPublicIP() (string, error) {
	ifs, err := GetPublicInterfaces()
	if err != nil {
		return "", err
	}
	if len(ifs) == 0 {
		return "", nil
	}
	return ipOf(ifs[0]).String(), nil
}

// GetPublicIPs -
func GetPublicIPs() (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	out := IfAddrs{}
	for _, a := range ifs {
		ip := ipOf(a)
		if ip != nil && ip.To4() != nil && !isRFC(6890, ip) && isForwardable(ip) && a.Flags&net.FlagUp != 0 {
			out = append(out, a)
		}
	}
	return joinIPs(out), nil
}

// GetInterfaceIP -
func GetInterfaceIP(namedIfRE string) (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	for _, a := range ifs {
		if a.Name == namedIfRE {
			if ip := ipOf(a); ip != nil && ip.To4() != nil {
				return ip.String(), nil
			}
		}
	}
	return "", nil
}

// GetInterfaceIPs -
func GetInterfaceIPs(namedIfRE string) (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	out := IfAddrs{}
	for _, a := range ifs {
		if a.Name == namedIfRE {
			out = append(out, a)
		}
	}
	return joinIPs(out), nil
}
