	5735: {"192.0.2.0/24", "198.51.100.0/24", "203.0.113.0/24"},
	5737: {"192.0.2.0/24", "198.51.100.0/24", "203.0.113.0/24"},
	6052: {"64:ff9b::/96"},
	6333: {"192.0.0.0/29"},
	6598: {"100.64.0.0/10"},
	6666: {"100::/64"},
	6890: {"0.0.0.0/8", "10.0.0.0/8", "100.64.0.0/10", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24", "192.0.0.0/29", "192.0.2.0/24", "192.88.99.0/24", "192.168.0.0/16", "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "255.255.255.255/32", "::1/128", "::/128", "64:ff9b::/96", "::ffff:0:0/96", "100::/64", "2001::/23", "2001::/32", "2001:2::/48", "2001:db8::/32", "2001:10::/28", "2002::/16", "fc00::/7", "fe80::/10"},
	7335: {"192.0.0.0/29"},
	7450: {"2001::/32"},
}

func isRFC(rfc uint, ip net.IP) bool {
	for _, n := range rfcNets[rfc] {
		_, ipnet, err := net.ParseCIDR(n)
		if err == nil && ipnet.Contains(ip) {
			return true
		}
	}
	return false
}

var nonForwardable = []string{"0.0.0.0/8", "127.0.0.0/8", "169.254.0.0/16", "192.0.0.0/24", "192.0.2.0/24", "198.18.0.0/15", "198.51.100.0/24", "203.0.113.0/24", "240.0.0.0/4", "255.255.255.255/32", "::1/128", "::/128", "::ffff:0:0/96", "2001::/32", "2001:2::/48", "2001:db8::/32", "2001:10::/28", "fe80::/10"}

func isForwardable(ip net.IP) bool {
	for _, n := range nonForwardable {
		_, ipnet, err := net.ParseCIDR(n)
		if err == nil && ipnet.Contains(ip) {
			return false
		}
	}
	return true
}

func ipToBig(ip net.IP) *big.Int {
	if ip4 := ip.To4(); ip4 != nil {
		return new(big.Int).SetUint64(uint64(binary.BigEndian.Uint32(ip4)))
	}
	return new(big.Int).SetBytes(ip.To16())
}

// Sort sorts the IfAddrs by the given (comma-separated) selectors
func Sort(selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	sortedIfs := append(IfAddrs{}, inputIfAddrs...)
	clauses := strings.Split(selectorParam, ",")
	type cmp func(a, b IfAddr) int
	cmps := []cmp{}
	for _, c := range clauses {
		c = strings.TrimSpace(c)
		desc := false
		if strings.HasPrefix(c, "-") {
			desc = true
			c = c[1:]
		} else if strings.HasPrefix(c, "+") {
			c = c[1:]
		}
		var f cmp
		switch strings.ToLower(c) {
		case "address":
			f = func(a, b IfAddr) int {
				ia, ib := ipOf(a), ipOf(b)
				if ia == nil || ib == nil {
					return 0
				}
				if a.Type() != b.Type() {
					return 0
				}
				return ipToBig(ia).Cmp(ipToBig(ib))
			}
		case "default":
			def, _ := defaultInterfaceName()
			f = func(a, b IfAddr) int {
				ad, bd := a.Name == def, b.Name == def
				switch {
				case ad && !bd:
					return -1
				case !ad && bd:
					return 1
				}
				return 0
			}
		case "name":
			f = func(a, b IfAddr) int { return strings.Compare(a.Name, b.Name) }
		case "port":
			f = func(a, b IfAddr) int {
				pa, pb := portOf(a), portOf(b)
				switch {
				case pa < pb:
					return -1
				case pa > pb:
					return 1
				}
				return 0
			}
		case "private":
			f = func(a, b IfAddr) int {
				ap, bp := isRFC(6890, ipOf(a)), isRFC(6890, ipOf(b))
				switch {
				case ap && !bp:
					return -1
				case !ap && bp:
					return 1
				}
				return 0
			}
		case "size":
			f = func(a, b IfAddr) int {
				sa, sb := sizeOf(a), sizeOf(b)
				switch {
				case sa > sb:
					return -1
				case sa < sb:
					return 1
				}
				return 0
			}
		case "type":
			f = func(a, b IfAddr) int {
				ta, tb := typeOrder(a.Type()), typeOrder(b.Type())
				switch {
				case ta < tb:
					return -1
				case ta > tb:
					return 1
				}
				return 0
			}
		default:
			return nil, fmt.Errorf("invalid sort selector %q", c)
		}
		if desc {
			orig := f
			f = func(a, b IfAddr) int { return -orig(a, b) }
		}
		cmps = append(cmps, f)
	}
	sort.SliceStable(sortedIfs, func(i, j int) bool {
		for _, c := range cmps {
			if r := c(sortedIfs[i], sortedIfs[j]); r != 0 {
				return r < 0
			}
		}
		return false
	})
	return sortedIfs, nil
}

func typeOrder(t SockAddrType) int {
	switch t {
	case TypeUnix:
		return 0
	case TypeIPv4:
		return 1
	case TypeIPv6:
		return 2
	}
	return 3
}

func portOf(a IfAddr) uint16 {
	if ia, ok := a.SockAddr.(*IPAddr); ok {
		return ia.Port
	}
	return 0
}

func sizeOf(a IfAddr) int {
	if ia, ok := a.SockAddr.(*IPAddr); ok {
		ones, bits := ia.Mask.Size()
		return bits - ones
	}
	return 0
}

// flagNames maps flag selector names to their test
var flagNames = map[string]func(a IfAddr) bool{
	"broadcast":                 func(a IfAddr) bool { return a.Flags&net.FlagBroadcast != 0 },
	"down":                      func(a IfAddr) bool { return a.Flags&net.FlagUp == 0 },
	"forwardable":               func(a IfAddr) bool { ip := ipOf(a); return ip != nil && isForwardable(ip) },
	"global unicast":            func(a IfAddr) bool { ip := ipOf(a); return ip != nil && ip.IsGlobalUnicast() },
	"interface-local multicast": func(a IfAddr) bool { ip := ipOf(a); return ip != nil && ip.IsInterfaceLocalMulticast() },
	"link-local multicast":      func(a IfAddr) bool { ip := ipOf(a); return ip != nil && ip.IsLinkLocalMulticast() },
	"link-local unicast":        func(a IfAddr) bool { ip := ipOf(a); return ip != nil && ip.IsLinkLocalUnicast() },
	"loopback":                  func(a IfAddr) bool { return a.Flags&net.FlagLoopback != 0 },
	"multicast":                 func(a IfAddr) bool { return a.Flags&net.FlagMulticast != 0 },
	"point-to-point":            func(a IfAddr) bool { return a.Flags&net.FlagPointToPoint != 0 },
	"unspecified":               func(a IfAddr) bool { ip := ipOf(a); return ip != nil && ip.IsUnspecified() },
	"up":                        func(a IfAddr) bool { return a.Flags&net.FlagUp != 0 },
}

func matches(selector, value string, a IfAddr) (bool, error) {
	switch strings.ToLower(selector) {
	case "address":
		ip := ipOf(a)
		return ip != nil && ip.String() == value, nil
	case "flag", "flags":
		for _, f := range strings.Split(value, "|") {
			fn, ok := flagNames[strings.ToLower(f)]
			if !ok {
				return false, fmt.Errorf("Invalid flag %q", f)
			}
			if !fn(a) {
				return false, nil
			}
		}
		return true, nil
	case "name":
		return a.Name == value, nil
	case "network":
		_, ipnet, err := net.ParseCIDR(value)
		if err != nil {
			ip := net.ParseIP(value)
			if ip == nil {
				return false, fmt.Errorf("Unable to create an IP address from %q", value)
			}
			return ipOf(a).Equal(ip), nil
		}
		ip := ipOf(a)
		return ip != nil && ipnet.Contains(ip), nil
	case "port":
		p, err := strconv.Atoi(value)
		if err != nil {
			return false, err
		}
		return int(portOf(a)) == p, nil
	case "rfc", "rfcs":
		for _, r := range strings.Split(value, "|") {
			n, err := strconv.Atoi(r)
			if err != nil {
				return false, fmt.Errorf("Invalid RFC %q", r)
			}
			if _, ok := rfcNets[uint(n)]; !ok {
				return false, fmt.Errorf("Unsupported RFC %d", n)
			}
			if isRFC(uint(n), ipOf(a)) {
				return true, nil
			}
		}
		return false, nil
	case "size":
		n, err := strconv.Atoi(value)
		if err != nil {
			return false, err
		}
		if ia, ok := a.SockAddr.(*IPAddr); ok {
			ones, _ := ia.Mask.Size()
			return ones == n, nil
		}
		return false, nil
	case "type":
		for _, t := range strings.Split(value, "|") {
			if strings.EqualFold(a.Type().String(), t) {
				return true, nil
			}
		}
		return false, nil
	}
	return false, fmt.Errorf("invalid include/exclude selector %q", selector)
}

// Include filters the IfAddrs to those matching the selector
func Include(selectorName, selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	out := IfAddrs{}
	for _, a := range inputIfAddrs {
		ok, err := matches(selectorName, selectorParam, a)
		if err != nil {
			return nil, err
		}
		if ok {
			out = append(out, a)
		}
	}
	return out, nil
}

// Exclude filters out the IfAddrs matching the selector
func Exclude(selectorName, selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	out := IfAddrs{}
	for _, a := range inputIfAddrs {
		ok, err := matches(selectorName, selectorParam, a)
		if err != nil {
			return nil, err
		}
		if !ok {
			out = append(out, a)
		}
	}
	return out, nil
}

// Attr returns the named attribute of the IfAddr
func Attr(selectorName string, ifAddrs any) (string, error) {
	switch v := ifAddrs.(type) {
	case IfAddr:
		return ifAttr(selectorName, v)
	case IfAddrs:
		if len(v) == 0 {
			return "", nil
		}
		return ifAttr(selectorName, v[0])
	}
	return "", fmt.Errorf("unable to obtain attribute %s from type %T (%v)", selectorName, ifAddrs, ifAddrs)
}

func ifAttr(name string, a IfAddr) (string, error) {
	ia, _ := a.SockAddr.(*IPAddr)
	switch strings.ToLower(name) {
	case "name":
		return a.Name, nil
	case "flags":
		return a.Flags.String(), nil
	case "hardwareaddr", "hardware_addr":
		return a.HardwareAddr.String(), nil
	case "mtu":
		return strconv.Itoa(a.MTU), nil
	case "type":
		return a.Type().String(), nil
	case "string":
		return a.SockAddr.String(), nil
	}
	if ia == nil {
		return "", fmt.Errorf("unsupported attribute name %q", name)
	}
	ones, bits := ia.Mask.Size()
	switch strings.ToLower(name) {
	case "address":
		return ia.IP.String(), nil
	case "network":
		return ia.NetworkIP().String(), nil
	case "mask", "netmask":
		if !ia.v6 {
			return net.IP(ia.Mask).String(), nil
		}
		return ia.Mask.String(), nil
	case "size":
		return new(big.Int).Lsh(big.NewInt(1), uint(bits-ones)).String(), nil
	case "port":
		return strconv.Itoa(int(ia.Port)), nil
	case "host":
		return fmt.Sprintf("%s/%d", ia.IP.String(), bits), nil
	case "broadcast":
		if ia.v6 {
			return "", nil
		}
		return ia.Broadcast().String(), nil
	case "first_usable":
		n := ipToBig(ia.NetworkIP())
		if bits-ones > 1 {
			n.Add(n, big.NewInt(1))
		}
		return bigToIP(n, ia.v6).String(), nil
	case "last_usable":
		b := ipToBig(ia.Broadcast())
		if bits-ones > 1 {
			b.Sub(b, big.NewInt(1))
		}
		return bigToIP(b, ia.v6).String(), nil
	case "octets":
		parts := []string{}
		for _, b := range ia.IP {
			parts = append(parts, strconv.Itoa(int(b)))
		}
		return strings.Join(parts, " "), nil
	case "uint32":
		if ia.v6 {
			return "", fmt.Errorf("unsupported attribute name %q", name)
		}
		return strconv.FormatUint(uint64(binary.BigEndian.Uint32(ia.IP.To4())), 10), nil
	}
	return "", fmt.Errorf("unsupported attribute name %q", name)
}

func bigToIP(n *big.Int, v6 bool) net.IP {
	l := 4
	if v6 {
		l = 16
	}
	b := n.Bytes()
	out := make([]byte, l)
	copy(out[l-len(b):], b)
	return net.IP(out)
}

// Join joins the named attribute of each IfAddr with the separator
func Join(selectorName, joinString string, inputIfAddrs IfAddrs) (string, error) {
	out := []string{}
	for _, a := range inputIfAddrs {
		s, err := ifAttr(selectorName, a)
		if err != nil {
			return "", err
		}
		out = append(out, s)
	}
	return strings.Join(out, joinString), nil
}

// Limit -
func Limit(lim uint, in IfAddrs) (IfAddrs, error) {
	if int(lim) > len(in) {
		lim = uint(len(in))
	}
	return in[:lim], nil
}

// Offset -
func Offset(off int, in IfAddrs) (IfAddrs, error) {
	switch {
	case off > 0:
		if off > len(in) {
			return nil, fmt.Errorf("unable to seek past the end of the interface array: offset (%d) exceeds the number of interfaces (%d)", off, len(in))
		}
		return in[off:], nil
	case off < 0:
		end := len(in) + off
		if end < 0 {
			return nil, fmt.Errorf("unable to seek past the beginning of the interface array: offset (%d) exceeds the number of interfaces (%d)", off, len(in))
		}
		return in[end:], nil
	}
	return in, nil
}

// Unique removes duplicates by the given attribute
func Unique(selectorName string, in IfAddrs) (IfAddrs, error) {
	seen := map[string]bool{}
	out := IfAddrs{}
	for _, a := range in {
		k, err := ifAttr(selectorName, a)
		if err != nil {
			return nil, err
		}
		if seen[k] {
			continue
		}
		seen[k] = true
		out = append(out, a)
	}
	return out, nil
}

// Math applies an operation to each address
func Math(operation, value string, in IfAddrs) (IfAddrs, error) {
	out := IfAddrs{}
	for _, a := range in {
		ia, ok := a.SockAddr.(*IPAddr)
		if !ok {
			out = append(out, a)
			continue
		}
		n, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("unable to convert %q to int for operation %q: %v", value, operation, err)
		}
		ip := ipToBig(ia.IP)
		switch strings.ToLower(operation) {
		case "address":
			ip.Add(ip, big.NewInt(n))
		case "network":
			nw := ipToBig(ia.NetworkIP())
			ones, bits := ia.Mask.Size()
			size := new(big.Int).Lsh(big.NewInt(1), uint(bits-ones))
			off := new(big.Int).Mod(big.NewInt(n), size)
			ip = nw.Add(nw, off)
		default:
			return nil, fmt.Errorf("unsupported math operation: %q", operation)
		}
		nia := &IPAddr{IP: bigToIP(ip, ia.v6), Mask: ia.Mask, Port: ia.Port, v6: ia.v6}
		out = append(out, IfAddr{SockAddr: nia, Interface: a.Interface})
	}
	return out, nil
}

func joinIPs(in IfAddrs) string {
	var b bytes.Buffer
	for i, a := range in {
		if i > 0 {
			b.WriteByte(' ')
		}
		b.WriteString(ipOf(a).String())
	}
	return b.String()
}

// GetPrivateIP -
func GetPrivateIP() (string, error) {
	ifs, err := GetPrivateInterfaces()
	if err != nil {
		return "", err
	}
	if len(ifs) == 0 {
		return "", nil
	}
	return ipOf(ifs[0]).String(), nil
}

// GetPrivateIPs -
func GetPrivateIPs() (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	out := IfAddrs{}
	for _, a := range ifs {
		ip := ipOf(a)
		if ip != nil && ip.To4() != nil && isRFC(6890, ip) && isForwardable(ip) && a.Flags&net.FlagUp != 0 {
			out = append(out, a)
		}
	}
	return joinIPs(out), nil
}

// GetPublicIP -
func GetPublicIP() (string, error) {
	ifs, err := GetPublicInterfaces()
	if err != nil {
		return "", err
	}
	if len(ifs) == 0 {
		return "", nil
	}
	return ipOf(ifs[0]).String(), nil
}

// GetPublicIPs -
func GetPublicIPs() (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	out := IfAddrs{}
	for _, a := range ifs {
		ip := ipOf(a)
		if ip != nil && ip.To4() != nil && !isRFC(6890, ip) && isForwardable(ip) && a.Flags&net.FlagUp != 0 {
			out = append(out, a)
		}
	}
	return joinIPs(out), nil
}

// GetInterfaceIP -
func GetInterfaceIP(namedIfRE string) (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	for _, a := range ifs {
		if a.Name == namedIfRE {
			if ip := ipOf(a); ip != nil && ip.To4() != nil {
				return ip.String(), nil
			}
		}
	}
	return "", nil
}

// GetInterfaceIPs -
func GetInterfaceIPs(namedIfRE string) (string, error) {
	ifs, err := GetAllInterfaces()
	if err != nil {
		return "", err
	}
	out := IfAddrs{}
	for _, a := range ifs {
		if a.Name == namedIfRE {
			out = append(out, a)
		}
	}
	return joinIPs(out), nil
}
