func getenvWithFile(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	if p := os.Getenv(key + "_FILE"); p != "" {
		if b, err := os.ReadFile(p); err == nil {
			return strings.TrimSpace(string(b))
		}
	}
	return def
}

func parseEJSONKey(s string) (*[32]byte, error) {
	b, err := hex.DecodeString(strings.TrimSpace(s))
	if err != nil || len(b) != 32 {
		return nil, errors.New("invalid key")
	}
	var k [32]byte
	copy(k[:], b)
	return &k, nil
}

func decryptEJSON(in string) (map[string]any, error) {
	keyDir := getenvWithFile("EJSON_KEYDIR", "/opt/ejson/keys")
	key := getenvWithFile("EJSON_KEY", "")

	obj := make(map[string]any)
	if err := yamlDecodeFirst(in, &obj); err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %w", in, err)
	}
	pubStr, ok := obj["_public_key"].(string)
	if !ok {
		return nil, errors.New("public key not present in EJSON file")
	}
	pub, err := parseEJSONKey(pubStr)
	if err != nil {
		return nil, errors.New("public key has invalid format")
	}
	if key == "" {
		b, err := os.ReadFile(filepath.Join(keyDir, pubStr))
		if err != nil {
			return nil, fmt.Errorf("couldn't read key file (%w)", err)
		}
		key = string(b)
	}
	priv, err := parseEJSONKey(key)
	if err != nil {
		return nil, errors.New("invalid private key")
	}
	_ = pub
	out, err := ejsonWalk(obj, priv, false)
	if err != nil {
		return nil, err
	}
	m := stringifyMapKeys(out).(map[string]any)
	delete(m, "_public_key")
	return m, nil
}

func ejsonWalk(v any, priv *[32]byte, skip bool) (any, error) {
	switch x := v.(type) {
	case map[string]any:
		for k, val := range x {
			nv, err := ejsonWalk(val, priv, strings.HasPrefix(k, "_"))
			if err != nil {
				return nil, err
			}
			x[k] = nv
		}
		return x, nil
	case []any:
		for i, val := range x {
			nv, err := ejsonWalk(val, priv, skip)
			if err != nil {
				return nil, err
			}
			x[i] = nv
		}
		return x, nil
	case string:
		if skip {
			return x, nil
		}
		return ejsonDecrypt(x, priv)
	}
	return v, nil
}

func ejsonDecrypt(s string, priv *[32]byte) (string, error) {
	if !strings.HasPrefix(s, "EJ[") || !strings.HasSuffix(s, "]") {
		return s, nil
	}
	parts := strings.Split(s[3:len(s)-1], ":")
	if len(parts) != 4 || parts[0] != "1" {
		return "", errors.New("invalid message format")
	}
	encPub, err := base64.StdEncoding.DecodeString(parts[1])
	if err != nil || len(encPub) != 32 {
		return "", errors.New("invalid message format")
	}
	nonce, err := base64.StdEncoding.DecodeString(parts[2])
	if err != nil || len(nonce) != 24 {
